window.BOOK_GLOSSARY=[{"term": "neuron", "vi": "tế bào thần kinh", "def": "Tế bào chuyên xử lý và truyền tín hiệu điện–hoá của hệ thần kinh; não người có khoảng 86 tỷ.", "ch": "ch01"}, {"term": "synapse", "vi": "khớp thần kinh", "def": "Chỗ tiếp xúc chuyên biệt nơi một neuron truyền tín hiệu sang tế bào khác; cường độ của nó thay đổi được và là cơ sở vật chất của việc học.", "ch": "ch01"}, {"term": "dendrite", "vi": "sợi nhánh", "def": "Các nhánh cây của neuron, nơi nhận hàng nghìn synapse và tích hợp (đôi khi phi tuyến) các dòng điện đi vào.", "ch": "ch01"}, {"term": "soma", "vi": "thân tế bào", "def": "Phần thân chứa nhân của neuron, đường kính cỡ 10–20 µm, nơi các dòng điện từ dendrite hội tụ.", "ch": "ch01"}, {"term": "axon", "vi": "sợi trục", "def": "Dây ra duy nhất của neuron, dẫn spike đi xa (từ dưới 1 mm đến cả mét) rồi chia nhánh tới các synapse.", "ch": "ch01"}, {"term": "spike", "vi": "xung thần kinh", "def": "Tên gọi ngắn của action potential: một xung điện ~1 ms, ~100 mV, tất-cả-hoặc-không.", "ch": "ch01"}, {"term": "action potential", "vi": "điện thế hoạt động", "def": "Xung điện tự tái sinh lan dọc axon khi điện thế màng vượt ngưỡng; là tín hiệu số của hệ thần kinh.", "ch": "ch01"}, {"term": "neurotransmitter", "vi": "chất dẫn truyền thần kinh", "def": "Phân tử (glutamate, GABA, dopamine…) được nhả ra ở synapse khi có spike, gắn vào thụ thể của tế bào nhận và gây hiệu ứng điện hoặc hoá.", "ch": "ch01"}, {"term": "synaptic plasticity", "vi": "tính mềm dẻo synapse", "def": "Sự thay đổi cường độ synapse theo hoạt động, kéo dài từ mili giây đến suốt đời; cơ chế tế bào của học và nhớ.", "ch": "ch01"}, {"term": "McCulloch–Pitts neuron", "vi": "neuron McCulloch–Pitts", "def": "Mô hình neuron năm 1943: đầu vào nhị phân, tổng có trọng số, so với ngưỡng, đầu ra 0/1; tổ tiên của mọi đơn vị mạng neuron nhân tạo.", "ch": "ch01"}, {"term": "Hebbian learning", "vi": "học kiểu Hebb", "def": "Luật học cục bộ: synapse mạnh lên khi neuron trước và neuron sau cùng hoạt động (Δw ∝ pre × post).", "ch": "ch01"}, {"term": "perceptron", "vi": "perceptron", "def": "Đơn vị ngưỡng tuyến tính có luật học theo sai số của Rosenblatt (1958); chỉ học được các bài toán tách được tuyến tính.", "ch": "ch01"}, {"term": "credit assignment", "vi": "quy trách nhiệm", "def": "Bài toán xác định kết nối nào ở sâu trong mạng chịu trách nhiệm cho một sai số ở đầu ra và cần sửa theo hướng nào.", "ch": "ch01"}, {"term": "backpropagation", "vi": "lan truyền ngược", "def": "Thuật toán tính gradient của loss theo mọi trọng số bằng quy tắc chuỗi, truyền sai số ngược từ đầu ra về đầu vào; nền tảng của deep learning nhưng khó hiện thực nguyên bản trong não.", "ch": "ch01"}, {"term": "receptive field", "vi": "trường thụ cảm", "def": "Vùng của không gian kích thích (ví dụ một mảng thị trường) mà kích thích tại đó làm thay đổi hoạt động của một neuron.", "ch": "ch01"}, {"term": "simple cell", "vi": "tế bào đơn giản", "def": "Neuron ở V1 có receptive field gồm các dải kích thích/ức chế song song; kén cả hướng lẫn vị trí của cạnh.", "ch": "ch01"}, {"term": "complex cell", "vi": "tế bào phức hợp", "def": "Neuron ở V1 kén hướng nhưng bất biến với vị trí chính xác của cạnh trong receptive field; nguyên mẫu của pooling.", "ch": "ch01"}, {"term": "Neocognitron", "vi": "Neocognitron", "def": "Mạng nhiều tầng của Fukushima (1980) xen kẽ S-cell và C-cell theo sơ đồ Hubel–Wiesel; tổ tiên trực tiếp của CNN.", "ch": "ch01"}, {"term": "temporal difference learning", "vi": "học chênh lệch thời gian", "def": "Phương pháp RL học dự đoán giá trị từ chênh lệch giữa hai dự đoán liên tiếp: δ = r + γV(s′) − V(s).", "ch": "ch01"}, {"term": "dopamine", "vi": "dopamine", "def": "Neuromodulator do các neuron ở não giữa (VTA, SNc) tiết ra, toả rộng tới striatum và vỏ não trán; hoạt động pha của nó khớp với sai số dự đoán phần thưởng.", "ch": "ch01"}, {"term": "reward prediction error", "vi": "sai số dự đoán phần thưởng", "def": "Chênh lệch giữa phần thưởng nhận được (cộng giá trị kỳ vọng mới) và phần thưởng đã dự đoán; tương ứng với TD error.", "ch": "ch01"}, {"term": "hippocampus", "vi": "hồi hải mã", "def": "Cấu trúc ở mặt trong thuỳ thái dương, thiết yếu cho việc hình thành ký ức sự kiện mới và biểu diễn không gian.", "ch": "ch01"}, {"term": "neocortex", "vi": "vỏ não mới", "def": "Lớp chất xám sáu tầng dày 2–4 mm phủ bán cầu não, chứa khoảng 16 tỷ neuron ở người; nơi diễn ra phần lớn xử lý cảm giác, vận động và nhận thức bậc cao.", "ch": "ch01"}, {"term": "cerebellum", "vi": "tiểu não", "def": "Cấu trúc ở sau–dưới não, chứa khoảng 80% số neuron của não; học giám sát các mô hình cảm giác–vận động chính xác về thời gian.", "ch": "ch01"}, {"term": "complementary learning systems", "vi": "các hệ học bổ sung", "def": "Lý thuyết cho rằng hippocampus học nhanh từng sự kiện còn neocortex học chậm cấu trúc thống kê, và replay từ hippocampus giúp neocortex học mà không quên thảm hoạ.", "ch": "ch01"}, {"term": "experience replay", "vi": "phát lại kinh nghiệm", "def": "Kỹ thuật RL lưu các transition vào bộ đệm và lấy mẫu lại để huấn luyện, phá tương quan thời gian và dùng lại dữ liệu.", "ch": "ch01"}, {"term": "catastrophic forgetting", "vi": "quên thảm hoạ", "def": "Hiện tượng mạng học bằng gradient đánh mất kiến thức cũ khi được huấn luyện tuần tự trên dữ liệu mới.", "ch": "ch01"}, {"term": "Hopfield network", "vi": "mạng Hopfield", "def": "Mạng hồi quy trọng số đối xứng, trong đó ký ức là các cực tiểu của một hàm năng lượng; phiên bản hiện đại tương đương toán học với softmax attention.", "ch": "ch01"}, {"term": "Marr's levels", "vi": "ba tầng của Marr", "def": "Khung phân tích một hệ xử lý thông tin ở ba tầng: computational (bài toán gì, vì sao), algorithmic (biểu diễn và thuật toán), implementational (chất liệu vật lý).", "ch": "ch01"}, {"term": "leaky integrate-and-fire", "vi": "tích phân rò rồi phát xung", "def": "Mô hình neuron tối giản: điện thế màng tích phân input và rò về mức nghỉ; vượt ngưỡng thì phát spike và reset.", "ch": "ch01"}, {"term": "sparse coding", "vi": "mã thưa", "def": "Cách biểu diễn trong đó tại mỗi thời điểm chỉ một phần nhỏ neuron hoạt động; tiết kiệm năng lượng và dễ tách mẫu.", "ch": "ch01"}, {"term": "von Neumann bottleneck", "vi": "nút cổ chai von Neumann", "def": "Giới hạn hiệu năng và năng lượng do bộ nhớ và bộ xử lý tách rời, dữ liệu phải chở qua lại trên bus.", "ch": "ch01"}, {"term": "inductive bias", "vi": "thiên kiến quy nạp", "def": "Các giả định có sẵn trong kiến trúc hay luật học khiến hệ thống ưu tiên một số lời giải; ở não, phần lớn do tiến hoá mã hoá qua genome.", "ch": "ch01"}, {"term": "connectome", "vi": "bản đồ nối dây", "def": "Sơ đồ đầy đủ các neuron và synapse của một hệ thần kinh hay một khối mô, thường dựng từ ảnh kính hiển vi điện tử.", "ch": "ch01"}, {"term": "NeuroAI", "vi": "NeuroAI", "def": "Lĩnh vực giao thoa dùng khoa học thần kinh để cải tiến AI và dùng AI làm mô hình, công cụ để hiểu não.", "ch": "ch01"}, {"term": "neuron doctrine", "vi": "học thuyết neuron", "def": "Nguyên lý của Cajal (đặt tên bởi Waldeyer, 1891): hệ thần kinh gồm các tế bào riêng rẽ, là đơn vị giải phẫu và chức năng độc lập, liên hệ với nhau bằng tiếp xúc (synapse) chứ không bằng liên tục bào tương.", "ch": "ch02"}, {"term": "reticular theory", "vi": "thuyết lưới", "def": "Giả thuyết của Gerlach và Golgi rằng các sợi thần kinh hoà liền thành một mạng bào tương liên tục; bị bác bỏ bởi học thuyết neuron và ảnh hiển vi điện tử năm 1955, nhưng gap junction là một ngoại lệ nhỏ có thật.", "ch": "ch02"}, {"term": "dynamic polarization", "vi": "phân cực động", "def": "Quy luật của Cajal: tín hiệu trong một neuron đi theo một chiều, vào ở dendrite/soma và ra ở axon; nền tảng của mọi đồ thị tính toán có hướng.", "ch": "ch02"}, {"term": "dendritic spine", "vi": "gai dendrite", "def": "Nấm nhỏ ~1 µm trên dendrite mang một synapse kích thích; cổ thắt cô lập hoá học nên mỗi synapse có thể được cập nhật riêng — cơ sở vật lý của 'mỗi trọng số một biến'.", "ch": "ch02"}, {"term": "axon initial segment", "vi": "đoạn đầu axon (AIS)", "def": "20–60 µm đầu tiên của axon với mật độ kênh Na⁺ rất cao và ngưỡng thấp nhất, nơi action potential khởi phát; vị trí và độ dài tự điều chỉnh theo lịch sử hoạt động.", "ch": "ch02"}, {"term": "myelin", "vi": "bao myelin", "def": "Nhiều lớp màng glia (oligodendrocyte ở trung ương, Schwann cell ở ngoại biên) quấn quanh axon làm lớp cách điện, tăng tốc dẫn truyền 10–50 lần và giảm năng lượng; có thể thay đổi theo hoạt động.", "ch": "ch02"}, {"term": "node of Ranvier", "vi": "eo Ranvier", "def": "Khe hở ~1 µm giữa hai đoạn myelin, nơi kênh ion tập trung và spike được tái tạo, cho phép dẫn truyền nhảy cóc.", "ch": "ch02"}, {"term": "bouton", "vi": "cúc tận cùng", "def": "Chỗ phình ~1 µm dọc hoặc ở đầu nhánh axon, là nửa phát của synapse: chứa túi chất dẫn truyền và nhả chúng khi spike tới với xác suất thường 10–50%.", "ch": "ch02"}, {"term": "pyramidal neuron", "vi": "neuron tháp", "def": "Loại neuron kích thích (glutamate) chiếm ~70–80% neuron vỏ não, có chùm dendrite basal quanh soma và một thân apical vươn lên lớp 1; đơn vị biểu diễn chính của vỏ não.", "ch": "ch02"}, {"term": "interneuron", "vi": "neuron trung gian (ức chế)", "def": "Neuron ức chế (GABA) với axon cục bộ, chiếm ~20% neuron vỏ não; ba họ chính PV, SST, VIP nhắm vào các vị trí khác nhau trên tế bào đích và thực hiện gain control, gating, disinhibition.", "ch": "ch02"}, {"term": "Purkinje cell", "vi": "tế bào Purkinje", "def": "Neuron ức chế của vỏ tiểu não với cây dendrite phẳng hình quạt nhận ~1,5–2 × 10⁵ đầu vào từ parallel fiber — fan-in lớn nhất hệ thần kinh — và là đầu ra duy nhất của vỏ tiểu não.", "ch": "ch02"}, {"term": "granule cell", "vi": "tế bào hạt", "def": "Neuron nhỏ nhất (soma 5–8 µm) với ~4 dendrite, ở tiểu não đông tới ~50 tỷ — hơn nửa số neuron của người; đóng vai trò lớp mở rộng thưa trước Purkinje.", "ch": "ch02"}, {"term": "single-cell RNA sequencing", "vi": "giải trình tự RNA đơn bào (scRNA-seq)", "def": "Kỹ thuật đo lượng mRNA của ~20.000 gen trong từng tế bào riêng lẻ, cho ra ma trận tế bào × gen; phân loại tế bào trở thành bài toán clustering trên ma trận này.", "ch": "ch02"}, {"term": "axonal transport", "vi": "vận chuyển axon", "def": "Hệ thống chở bào quan, túi và protein dọc axon trên đường ray microtubule bằng động cơ kinesin (ra xa soma) và dynein (về soma); vận chuyển nhanh 1–4 µm/s, chậm 0,2–8 mm/ngày.", "ch": "ch02"}, {"term": "kinesin", "vi": "kinesin", "def": "Protein động cơ đi về đầu (+) của microtubule, tức ra xa soma; mỗi bước 8 nm tiêu một ATP; chở ty thể, túi synapse, kênh ion, mRNA tới axon.", "ch": "ch02"}, {"term": "dynein", "vi": "dynein", "def": "Protein động cơ đi về đầu (−) của microtubule, tức về soma; chở tín hiệu từ đích (yếu tố dinh dưỡng thần kinh) và rác cần tiêu huỷ.", "ch": "ch02"}, {"term": "ATP", "vi": "adenosine triphosphate", "def": "Đơn vị tiền tệ năng lượng của tế bào; thuỷ phân một phosphate giải phóng ~50–60 kJ/mol (~10⁻¹⁹ J/phân tử). Não tiêu ~2 × 10²⁰ ATP mỗi giây, không có kho dự trữ.", "ch": "ch02"}, {"term": "Na⁺/K⁺-ATPase", "vi": "bơm natri–kali", "def": "Protein bơm đẩy 3 Na⁺ ra và kéo 2 K⁺ vào cho mỗi ATP, dựng lại gradient ion sau spike và synaptic current; chiếm khoảng một nửa năng lượng tín hiệu của chất xám. Phát hiện bởi Skou (1957).", "ch": "ch02"}, {"term": "glia", "vi": "tế bào thần kinh đệm", "def": "Các tế bào không phát spike của hệ thần kinh (astrocyte, oligodendrocyte, microglia, Schwann cell…), chiếm xấp xỉ một nửa số tế bào não; vận hành, cách điện, nuôi dưỡng, dọn dẹp và tỉa mạch neuron.", "ch": "ch02"}, {"term": "astrocyte", "vi": "tế bào hình sao", "def": "Loại glia đông nhất ở vỏ não, mỗi tế bào ôm 10⁵ (chuột) tới ~2 × 10⁶ (người) synapse; hút glutamate, đệm K⁺, cấp năng lượng, nối synapse với mao mạch; liên lạc bằng sóng Ca²⁺ chậm.", "ch": "ch02"}, {"term": "tripartite synapse", "vi": "synapse ba bên", "def": "Khái niệm (Araque và cộng sự, 1999) coi synapse gồm ba thành phần: bouton trước, spine sau, và nhánh astrocyte bao quanh — bên thứ ba tham gia dọn dẹp và điều biến.", "ch": "ch02"}, {"term": "oligodendrocyte", "vi": "tế bào ít nhánh", "def": "Glia của hệ thần kinh trung ương quấn myelin: mỗi tế bào tạo 20–60 đoạn myelin trên nhiều axon, cấp lactate cho axon, và sinh mới ở tuổi trưởng thành theo hoạt động.", "ch": "ch02"}, {"term": "microglia", "vi": "vi bào đệm", "def": "Tế bào miễn dịch thường trú của não (5–10% tế bào), gốc từ túi noãn hoàng; nhánh rà quét mô liên tục, dọn xác tế bào và cắt tỉa synapse yếu được đánh dấu bằng protein bổ thể.", "ch": "ch02"}, {"term": "synaptic pruning", "vi": "cắt tỉa synapse", "def": "Quá trình loại bỏ synapse dư thừa trong phát triển (mật độ giảm ~40% từ tuổi 1–3 tới trưởng thành), phụ thuộc hoạt động, do microglia thực hiện qua hệ bổ thể C1q/C3.", "ch": "ch02"}, {"term": "isotropic fractionator", "vi": "phương pháp phân đoạn đẳng hướng", "def": "Phương pháp đếm tế bào của Herculano-Houzel và Lent (2005): nghiền mô thành dung dịch nhân đồng nhất, đếm nhân (DAPI) và nhân neuron (NeuN) trong mẫu nhỏ rồi nhân lên; cho ra con số 86 tỷ neuron ở người.", "ch": "ch02"}, {"term": "cell type", "vi": "loại tế bào", "def": "Một cụm tế bào ổn định trong không gian biểu hiện gen mà hình thái, điện sinh lý và vị trí cùng đồng ý; taxonomy toàn não chuột (Allen 2023) có ~5.300 cluster ở tầng lá.", "ch": "ch02"}, {"term": "gap junction", "vi": "khớp nối khe", "def": "Kênh protein (connexin) nối trực tiếp bào tương hai tế bào qua khe ~3,5 nm, tạo synapse điện; phổ biến giữa interneuron cùng loại và giữa các astrocyte.", "ch": "ch02"}, {"term": "membrane potential", "vi": "điện thế màng", "def": "Hiệu điện thế giữa bên trong và bên ngoài màng tế bào (trong trừ ngoài); ở neuron đang nghỉ khoảng −70 mV.", "ch": "ch03"}, {"term": "resting potential", "vi": "điện thế nghỉ", "def": "Điện thế màng ổn định khi neuron không nhận input, khoảng −65 đến −75 mV, chủ yếu do K⁺ khuếch tán qua kênh rò quyết định.", "ch": "ch03"}, {"term": "ion channel", "vi": "kênh ion", "def": "Protein xuyên màng tạo lỗ dẫn chọn lọc; khi mở cho ion chảy thụ động xuôi gradient điện hoá với tốc độ 10⁷–10⁸ ion/giây.", "ch": "ch03"}, {"term": "ion pump", "vi": "bơm ion", "def": "Protein dùng ATP để vận chuyển ion ngược gradient; bơm Na⁺/K⁺-ATPase đẩy 3 Na⁺ ra và kéo 2 K⁺ vào cho mỗi ATP, duy trì các gradient nồng độ.", "ch": "ch03"}, {"term": "equilibrium potential", "vi": "điện thế cân bằng", "def": "Điện thế màng tại đó dòng ròng của một loại ion bằng 0 vì lực điện cân bằng với khuếch tán; còn gọi là reversal potential của ion đó.", "ch": "ch03"}, {"term": "Nernst equation", "vi": "phương trình Nernst", "def": "Công thức E = (RT/zF)·ln([ion]ngoài/[ion]trong) cho điện thế cân bằng của một ion; khoảng 61,5 mV cho mỗi bậc 10 chênh lệch nồng độ ở 37 °C.", "ch": "ch03"}, {"term": "GHK equation", "vi": "phương trình Goldman–Hodgkin–Katz", "def": "Công thức cho điện thế màng khi màng thấm nhiều loại ion cùng lúc: một dạng trung bình các điện thế cân bằng với trọng số là độ thấm của từng ion.", "ch": "ch03"}, {"term": "driving force", "vi": "lực đẩy điện hoá", "def": "Hiệu (V_m − E_ion); nhân với độ dẫn cho ra dòng của ion đó. Bằng 0 khi điện thế màng đúng bằng điện thế cân bằng của ion.", "ch": "ch03"}, {"term": "conductance", "vi": "độ dẫn", "def": "Nghịch đảo của điện trở (đơn vị siemens); độ dẫn của màng với một ion tỉ lệ với số kênh của ion ấy đang mở.", "ch": "ch03"}, {"term": "membrane capacitance", "vi": "điện dung màng", "def": "Khả năng tích điện của lớp lipid kép, xấp xỉ 1 µF/cm² ở mọi tế bào; quyết định lượng điện tích cần để đổi điện thế màng.", "ch": "ch03"}, {"term": "membrane time constant", "vi": "hằng số thời gian màng", "def": "τ_m = R_m·C_m, thường 10–30 ms; thời gian để điện thế màng thụ động đi được 63% quãng đường tới giá trị mới, tức cửa sổ tích phân của neuron.", "ch": "ch03"}, {"term": "length constant", "vi": "hằng số không gian", "def": "λ: khoảng cách mà điện thế thụ động suy giảm còn 37% (1/e) dọc dendrite hay axon; thường 0,1–1 mm, tăng theo căn bậc hai đường kính.", "ch": "ch03"}, {"term": "low-pass filter", "vi": "bộ lọc thông thấp", "def": "Hệ chỉ cho tín hiệu biến thiên chậm đi qua; màng RC là bộ lọc thông thấp bậc một với tần số cắt 1/(2πτ_m).", "ch": "ch03"}, {"term": "leaky integrator", "vi": "bộ tích phân rò", "def": "Hệ cộng dồn input theo thời gian nhưng rò dần về mức nghỉ; mô tả màng thụ động và tương đương với exponential moving average.", "ch": "ch03"}, {"term": "temporal summation", "vi": "cộng gộp theo thời gian", "def": "Các input đến cách nhau ít hơn cỡ τ_m chồng lên nhau trên điện thế màng, nhờ đó nhiều input nhỏ liên tiếp có thể đưa neuron tới ngưỡng.", "ch": "ch03"}, {"term": "voltage-gated channel", "vi": "kênh ion nhạy điện áp", "def": "Kênh ion có cảm biến điện áp (đoạn S4 tích điện dương) khiến xác suất mở phụ thuộc điện thế màng; kênh Na⁺ và K⁺ loại này tạo nên action potential.", "ch": "ch03"}, {"term": "selectivity filter", "vi": "bộ lọc chọn lọc", "def": "Đoạn hẹp nhất của lỗ kênh, nơi ion được các nguyên tử oxy của protein thay cho áo nước; quyết định kênh cho loại ion nào đi qua.", "ch": "ch03"}, {"term": "inactivation", "vi": "sự bất hoạt", "def": "Trạng thái kênh Na⁺ bị một nắp protein bịt từ phía trong khoảng 1 ms sau khi mở; chỉ hồi phục khi màng tái phân cực, là nguồn gốc của refractory period.", "ch": "ch03"}, {"term": "gating current", "vi": "dòng cổng", "def": "Dòng điện rất nhỏ sinh ra do các điện tích của cảm biến điện áp dịch chuyển trong màng khi kênh chuyển trạng thái, xuất hiện trước dòng ion.", "ch": "ch03"}, {"term": "voltage clamp", "vi": "kẹp điện áp", "def": "Kỹ thuật dùng mạch hồi tiếp ghim điện thế màng ở giá trị định trước và đo dòng cần bơm vào, qua đó đo được dòng ion theo điện áp và thời gian.", "ch": "ch03"}, {"term": "patch clamp", "vi": "kẹp miếng màng", "def": "Kỹ thuật áp pipette thuỷ tinh vào màng để ghi dòng qua một vài hoặc một kênh ion đơn lẻ, hoặc ghi toàn tế bào (Neher & Sakmann, 1976).", "ch": "ch03"}, {"term": "tetrodotoxin", "vi": "tetrodotoxin (TTX)", "def": "Độc tố cá nóc chặn chọn lọc kênh Na⁺ nhạy điện áp ở nồng độ nanomol; công cụ dược lý kinh điển để loại bỏ action potential.", "ch": "ch03"}, {"term": "threshold", "vi": "ngưỡng", "def": "Mức điện thế màng (khoảng −55 đến −50 mV) mà tại đó dòng Na⁺ vào vượt dòng ra và hồi tiếp dương khởi động; là điểm cân bằng không bền, phụ thuộc lịch sử và tốc độ khử cực.", "ch": "ch03"}, {"term": "depolarization", "vi": "khử cực", "def": "Điện thế màng trở nên bớt âm (tiến về 0 hoặc dương), ví dụ pha lên của action potential do Na⁺ đi vào.", "ch": "ch03"}, {"term": "repolarization", "vi": "tái phân cực", "def": "Pha điện thế màng quay về giá trị âm sau đỉnh spike, do kênh Na⁺ bất hoạt và K⁺ đi ra.", "ch": "ch03"}, {"term": "hyperpolarization", "vi": "quá phân cực", "def": "Điện thế màng trở nên âm hơn điện thế nghỉ, làm neuron khó phát spike hơn.", "ch": "ch03"}, {"term": "afterhyperpolarization", "vi": "quá phân cực sau spike (AHP)", "def": "Giai đoạn vài ms sau spike khi điện thế xuống thấp hơn mức nghỉ vì kênh K⁺ đóng chậm; giúp kênh Na⁺ hồi phục khỏi bất hoạt.", "ch": "ch03"}, {"term": "overshoot", "vi": "phần vượt quá 0 mV", "def": "Phần đỉnh của action potential nơi bên trong tế bào trở nên dương (+30 đến +40 mV) so với bên ngoài, do màng tạm thời thấm Na⁺ là chính.", "ch": "ch03"}, {"term": "all-or-none", "vi": "tất cả hoặc không", "def": "Tính chất của action potential: hoặc không xảy ra, hoặc xảy ra với biên độ đầy đủ không phụ thuộc cường độ kích thích.", "ch": "ch03"}, {"term": "refractory period", "vi": "giai đoạn trơ", "def": "Khoảng thời gian sau spike mà neuron không thể (tuyệt đối, ~1–2 ms) hoặc khó (tương đối, thêm vài ms) phát spike tiếp, do kênh Na⁺ còn bất hoạt và kênh K⁺ còn mở.", "ch": "ch03"}, {"term": "graded potential", "vi": "điện thế biến thiên liên tục", "def": "Thay đổi điện thế màng có biên độ tỉ lệ với input và suy giảm theo khoảng cách, trái với spike all-or-none; là dạng tín hiệu của dendrite và của các neuron ngắn như photoreceptor.", "ch": "ch03"}, {"term": "saltatory conduction", "vi": "dẫn truyền nhảy cóc", "def": "Kiểu lan truyền trên axon có myelin: spike chỉ tái tạo tại các node of Ranvier và lan thụ động rất nhanh qua internode; đạt tới 120 m/s.", "ch": "ch03"}, {"term": "conduction velocity", "vi": "tốc độ dẫn truyền", "def": "Tốc độ spike lan dọc axon: 0,5–2 m/s ở sợi trần mảnh, tới 120 m/s ở sợi myelin to; tỉ lệ √d với sợi trần và gần tuyến tính với d ở sợi myelin.", "ch": "ch03"}, {"term": "channelopathy", "vi": "bệnh kênh ion", "def": "Bệnh do đột biến gene mã hoá kênh ion, ví dụ mất cảm giác đau bẩm sinh (Nav1.7) hay một số thể động kinh (Nav1.1).", "ch": "ch03"}, {"term": "Hodgkin–Huxley model", "vi": "mô hình Hodgkin–Huxley", "def": "Hệ bốn phương trình vi phân (V, m, h, n) mô tả action potential bằng các độ dẫn Na⁺, K⁺ phụ thuộc điện áp; công bố năm 1952 từ dữ liệu voltage clamp trên axon mực.", "ch": "ch04"}, {"term": "gating variable", "vi": "biến cổng", "def": "Số trong [0,1] (m, h, n) biểu diễn tỉ lệ 'hạt cổng' của kênh ion ở vị trí cho phép; đuổi theo giá trị ổn định x∞(V) với hằng số thời gian τx(V).", "ch": "ch04"}, {"term": "activation", "vi": "hoạt hoá", "def": "Quá trình cổng của kênh ion mở ra khi màng khử cực (biến m của Na⁺, n của K⁺). Đừng nhầm với 'activation' của unit trong ANN.", "ch": "ch04"}, {"term": "conductance-based model", "vi": "mô hình dựa trên độ dẫn", "def": "Họ mô hình neuron viết mỗi dòng ion dưới dạng độ dẫn có cổng nhân driving force, g·mᵖhᵠ·(V−E); HH là thành viên đầu tiên.", "ch": "ch04"}, {"term": "separation of time scales", "vi": "tách thang thời gian", "def": "Thủ thuật rút gọn hệ động lực: coi biến rất nhanh là đã cân bằng tức thời và biến rất chậm là tham số.", "ch": "ch04"}, {"term": "FitzHugh–Nagumo model", "vi": "mô hình FitzHugh–Nagumo", "def": "Mô hình hai biến (v nhanh với nonlinearity bậc ba, w chậm tuyến tính) giữ lại hình học định tính của spike trong HH; công cụ chuẩn để phân tích phase plane.", "ch": "ch04"}, {"term": "phase plane", "vi": "mặt phẳng pha", "def": "Mặt phẳng có toạ độ là hai biến trạng thái của hệ; mỗi hành vi của hệ là một quỹ đạo xuôi theo trường vectơ trên đó.", "ch": "ch04"}, {"term": "nullcline", "vi": "nullcline", "def": "Đường cong trên phase plane nơi đạo hàm theo thời gian của một biến bằng 0; giao của các nullcline là fixed point.", "ch": "ch04"}, {"term": "fixed point", "vi": "điểm cân bằng", "def": "Trạng thái mà mọi đạo hàm bằng 0; có thể bền (trạng thái nghỉ) hoặc không bền. Tính bền đọc từ trị riêng của Jacobian.", "ch": "ch04"}, {"term": "limit cycle", "vi": "chu trình giới hạn", "def": "Quỹ đạo khép kín cô lập hút các quỹ đạo lân cận; trong mô hình neuron, nó ứng với việc bắn spike đều đặn.", "ch": "ch04"}, {"term": "bifurcation", "vi": "phân nhánh", "def": "Sự thay đổi định tính của động lực (số lượng hay tính bền của fixed point, limit cycle) khi một tham số vượt qua giá trị tới hạn.", "ch": "ch04"}, {"term": "Hopf bifurcation", "vi": "phân nhánh Hopf", "def": "Fixed point mất ổn định khi cặp trị riêng phức vượt trục ảo, sinh ra dao động với tần số khác 0; cơ chế của type II excitability.", "ch": "ch04"}, {"term": "saddle-node bifurcation", "vi": "phân nhánh saddle-node", "def": "Một fixed point bền và một điểm yên ngựa chạm nhau rồi cùng biến mất; khi xảy ra trên một vòng bất biến (SNIC) nó cho type I excitability.", "ch": "ch04"}, {"term": "type I excitability", "vi": "tính kích thích loại I", "def": "Neuron bắt đầu bắn ở tần số thấp tuỳ ý, f–I liên tục (∝ √(I−I*)); ứng với saddle-node bifurcation; hành xử như integrator.", "ch": "ch04"}, {"term": "type II excitability", "vi": "tính kích thích loại II", "def": "Neuron bắt đầu bắn ngay ở một tần số khác 0, f–I có bước nhảy; ứng với Hopf bifurcation; hành xử như resonator.", "ch": "ch04"}, {"term": "bistability", "vi": "lưỡng ổn định", "def": "Hai trạng thái bền cùng tồn tại với cùng một input (ví dụ nghỉ và bắn đều); hệ ở trạng thái nào tuỳ vào lịch sử.", "ch": "ch04"}, {"term": "integrator", "vi": "bộ tích phân", "def": "Neuron có điện thế dưới ngưỡng hồi phục đơn điệu; cộng dồn input, input càng gần nhau càng dễ gây spike.", "ch": "ch04"}, {"term": "resonator", "vi": "bộ cộng hưởng", "def": "Neuron có dao động tắt dần dưới ngưỡng; phản ứng mạnh nhất với input có nhịp trùng tần số riêng, có thể bắn sau một xung ức chế (rebound).", "ch": "ch04"}, {"term": "phase response curve", "vi": "đường cong đáp ứng pha", "def": "Hàm cho biết một cú đẩy nhỏ tại mỗi pha của chu kỳ bắn làm spike kế tiếp sớm hay muộn bao nhiêu; quyết định khả năng đồng bộ hoá của mạng.", "ch": "ch04"}, {"term": "Izhikevich model", "vi": "mô hình Izhikevich", "def": "Mô hình hai biến (v bậc hai, u hồi phục) với reset và bốn tham số a, b, c, d; tái tạo khoảng 20 kiểu firing với chi phí tính toán thấp.", "ch": "ch04"}, {"term": "regular spiking", "vi": "bắn đều có thích nghi", "def": "Kiểu firing của đa số neuron pyramidal vỏ não: vài spike dồn dập lúc đầu rồi thưa dần do adaptation.", "ch": "ch04"}, {"term": "fast spiking", "vi": "bắn nhanh", "def": "Kiểu firing của interneuron PV: spike hẹp, tần số tới hàng trăm Hz, gần như không adaptation.", "ch": "ch04"}, {"term": "rheobase", "vi": "rheobase", "def": "Dòng hằng nhỏ nhất đủ làm neuron phát spike; với LIF bằng (Vth − EL)/R.", "ch": "ch04"}, {"term": "exponential integrate-and-fire", "vi": "tích phân–bắn dạng mũ", "def": "LIF cộng một số hạng mũ ΔT·exp((V−VT)/ΔT) mô phỏng sự khởi phát spike của kênh Na⁺; khớp với đường I–V động đo trên neuron thật.", "ch": "ch04"}, {"term": "adaptive exponential integrate-and-fire", "vi": "AdEx", "def": "EIF cộng một biến adaptation w (ghép dưới ngưỡng a, bước nhảy sau spike b); hai biến, tham số đo được, tái tạo hầu hết kiểu firing.", "ch": "ch04"}, {"term": "spike-frequency adaptation", "vi": "thích nghi tần số spike", "def": "Hiện tượng tần số bắn giảm dần dưới input hằng, do các dòng K⁺ chậm tích luỹ sau mỗi spike; một dạng hồi tiếp âm chậm.", "ch": "ch04"}, {"term": "interspike interval", "vi": "khoảng cách giữa hai spike", "def": "Thời gian giữa hai spike liên tiếp (ISI); phân bố của nó đặc trưng cho mức đều đặn của chuỗi spike.", "ch": "ch04"}, {"term": "f–I curve", "vi": "đường cong tần số–dòng điện", "def": "Tần số bắn ổn định theo dòng bơm hằng; là hàm truyền tĩnh của neuron và là nguyên mẫu sinh học của activation function.", "ch": "ch04"}, {"term": "firing rate", "vi": "tần số bắn", "def": "Số spike trên đơn vị thời gian, lấy trung bình theo thời gian, theo lần thử hoặc theo quần thể.", "ch": "ch04"}, {"term": "rate model", "vi": "mô hình tần số", "def": "Mô hình bỏ qua từng spike, mô tả neuron bằng tần số r với τ dr/dt = −r + F(input); tương đương RNN liên tục theo thời gian.", "ch": "ch04"}, {"term": "gain modulation", "vi": "điều biến độ khuếch đại", "def": "Thay đổi độ dốc của f–I (kiểu nhân/chia) mà không dời ngưỡng, ví dụ do mức nhiễu synapse nền hoặc neuromodulator.", "ch": "ch04"}, {"term": "coefficient of variation", "vi": "hệ số biến thiên", "def": "CV = độ lệch chuẩn / trung bình của ISI; bằng 0 với đồng hồ, bằng 1 với Poisson process; neuron vỏ não in vivo có CV ≈ 0,5–1.", "ch": "ch04"}, {"term": "Poisson process", "vi": "quá trình Poisson", "def": "Quá trình điểm trong đó mỗi khoảnh khắc dt có xác suất r·dt xảy ra sự kiện, độc lập với quá khứ; mô hình chuẩn cho chuỗi spike bất thường.", "ch": "ch04"}, {"term": "escape noise", "vi": "nhiễu thoát", "def": "Cách đưa tính ngẫu nhiên vào mô hình neuron bằng cường độ bắn tức thời phụ thuộc mũ vào khoảng cách V − ngưỡng, thay vì cộng nhiễu vào V.", "ch": "ch04"}, {"term": "generalized linear model", "vi": "mô hình tuyến tính tổng quát", "def": "Với spike: lọc tuyến tính kích thích + lọc lịch sử spike → hàm mũ → Poisson. Log-likelihood lõm nên khớp được bằng gradient ascent; chính là Poisson regression.", "ch": "ch04"}, {"term": "spike response model", "vi": "mô hình đáp ứng spike", "def": "Dạng tích chập của integrate-and-fire tổng quát (Gerstner): điện thế là tổng các kernel đáp ứng với input và với spike quá khứ của chính neuron.", "ch": "ch04"}, {"term": "point neuron", "vi": "neuron điểm", "def": "Mô hình coi toàn bộ tế bào là một ngăn đẳng thế duy nhất, bỏ qua hình thái và tính toán trong dendrite.", "ch": "ch04"}, {"term": "chemical synapse", "vi": "synapse hoá học", "def": "Synapse truyền tín hiệu bằng cách nhả chất dẫn truyền qua khe ~20 nm tới receptor ở tế bào sau; một chiều, có gain, có dấu, học được.", "ch": "ch05"}, {"term": "electrical synapse", "vi": "synapse điện", "def": "Synapse nối trực tiếp bào tương hai tế bào qua gap junction; rất nhanh, hai chiều, không đổi dấu, chủ yếu để đồng bộ hoá.", "ch": "ch05"}, {"term": "receptor", "vi": "thụ thể", "def": "Protein màng gắn chất dẫn truyền và biến tín hiệu hoá học thành đáp ứng của tế bào (mở kênh ion hoặc khởi động chuỗi tín hiệu nội bào).", "ch": "ch05"}, {"term": "presynaptic bouton", "vi": "cúc tận cùng trước synapse", "def": "Chỗ phình ~0,5–1 µm trên axon chứa vesicle và bộ máy nhả; phía 'pre' của synapse.", "ch": "ch05"}, {"term": "synaptic vesicle", "vi": "túi synapse", "def": "Túi màng đường kính ~40 nm chứa khoảng một đến vài nghìn phân tử chất dẫn truyền; đơn vị vật lý của một quantum.", "ch": "ch05"}, {"term": "active zone", "vi": "vùng hoạt động", "def": "Mảng màng trước synapse đối diện khe, nơi vesicle đậu, kênh Ca²⁺ tập trung và sự hợp màng diễn ra.", "ch": "ch05"}, {"term": "readily releasable pool", "vi": "kho sẵn sàng nhả (RRP)", "def": "Nhóm nhỏ vesicle (5–10 ở synapse vỏ não) đã đậu và lên cò tại active zone, có thể nhả ngay khi spike tới; cạn kho này gây short-term depression.", "ch": "ch05"}, {"term": "SNARE complex", "vi": "phức hợp SNARE", "def": "Bó xoắn của synaptobrevin (trên vesicle) với syntaxin và SNAP-25 (trên màng bouton); khi quấn chặt, nó kéo hai màng hợp nhất. Đích của độc tố botulinum và uốn ván.", "ch": "ch05"}, {"term": "synaptotagmin", "vi": "synaptotagmin", "def": "Protein cảm biến Ca²⁺ ái lực thấp trên vesicle; khi gắn Ca²⁺ trong nanodomain nó kích hoạt sự hợp màng trong ~0,1 ms. Synaptotagmin-7 là cảm biến chậm cho facilitation.", "ch": "ch05"}, {"term": "voltage-gated calcium channel", "vi": "kênh Ca²⁺ nhạy điện áp", "def": "Kênh ion mở khi màng khử cực, cho Ca²⁺ vào bouton (loại P/Q, N); nối action potential với việc nhả vesicle.", "ch": "ch05"}, {"term": "neuromuscular junction", "vi": "chỗ nối thần kinh–cơ (NMJ)", "def": "Synapse lớn giữa neuron vận động và sợi cơ, dùng acetylcholine, có hàng trăm release site nên gần như tuyệt đối tin cậy; nơi Katz phát hiện release lượng tử.", "ch": "ch05"}, {"term": "miniature postsynaptic potential", "vi": "điện thế mini", "def": "Đáp ứng nhỏ, tự phát do một vesicle đơn lẻ được nhả mà không cần spike; biên độ của nó là cỡ lượng tử q.", "ch": "ch05"}, {"term": "quantum", "vi": "lượng tử (synapse)", "def": "Gói chất dẫn truyền cỡ cố định tương ứng với một vesicle; đáp ứng synapse luôn là bội số nguyên của một quantum.", "ch": "ch05"}, {"term": "quantal size", "vi": "cỡ lượng tử (q)", "def": "Biên độ đáp ứng của tế bào sau với một vesicle; chủ yếu do số lượng và vị trí receptor (vd. AMPAR) quyết định.", "ch": "ch05"}, {"term": "release probability", "vi": "xác suất nhả (p)", "def": "Xác suất một release site nhả vesicle khi một action potential tới; 0,1–0,9 ở synapse trung ương, thay đổi theo lịch sử hoạt động và chất điều biến.", "ch": "ch05"}, {"term": "ionotropic receptor", "vi": "receptor kênh ion", "def": "Receptor đồng thời là kênh ion: gắn chất dẫn truyền thì mở trong < 1 ms (AMPA, NMDA, GABA-A, nicotinic).", "ch": "ch05"}, {"term": "metabotropic receptor", "vi": "receptor chuyển hoá", "def": "Receptor (thường là GPCR) tác động qua G-protein và chất truyền tin thứ hai; chậm, kéo dài, khuếch đại, thay đổi tham số của tế bào (GABA-B, mGluR, receptor dopamine…).", "ch": "ch05"}, {"term": "AMPA receptor", "vi": "receptor AMPA", "def": "Receptor glutamate ionotropic nhanh (đóng trong 2–5 ms), cho Na⁺/K⁺ qua; số lượng của nó ở synapse gần như chính là 'trọng số'.", "ch": "ch05"}, {"term": "NMDA receptor", "vi": "receptor NMDA", "def": "Receptor glutamate chậm, cho Ca²⁺ qua, bị Mg²⁺ bịt ở điện thế nghỉ nên chỉ dẫn dòng khi có cả glutamate (pre) lẫn khử cực (post) — bộ phát hiện trùng hợp, cổng của plasticity.", "ch": "ch05"}, {"term": "GABA-A receptor", "vi": "receptor GABA-A", "def": "Kênh Cl⁻ mở bởi GABA, receptor ức chế nhanh chủ đạo của não; reversal potential gần điện thế nghỉ nên thường ức chế theo kiểu shunt.", "ch": "ch05"}, {"term": "EPSP", "vi": "điện thế sau synapse kích thích", "def": "Sự khử cực tạm thời của tế bào sau do một synapse kích thích gây ra; đơn lẻ ở vỏ não chỉ ~0,2–1 mV.", "ch": "ch05"}, {"term": "IPSP", "vi": "điện thế sau synapse ức chế", "def": "Sự thay đổi điện thế (thường là tăng phân cực) do synapse ức chế gây ra, kéo điện thế màng ra xa ngưỡng.", "ch": "ch05"}, {"term": "reversal potential", "vi": "điện thế đảo chiều", "def": "Điện thế màng mà tại đó dòng ròng qua một loại receptor bằng 0; synapse kéo điện thế màng về giá trị này (≈0 mV cho AMPA/NMDA, ≈−70 mV cho GABA-A).", "ch": "ch05"}, {"term": "shunting inhibition", "vi": "ức chế kiểu shunt", "def": "Ức chế bằng cách tăng độ dẫn màng với reversal potential gần điện thế nghỉ: không tạo IPSP rõ nhưng chia nhỏ các EPSP đồng thời.", "ch": "ch05"}, {"term": "Dale's principle", "vi": "nguyên lý Dale", "def": "Một neuron nhả cùng (bộ) chất dẫn truyền ở mọi đầu tận cùng; hệ quả tính toán: mọi synapse đi ra từ một neuron có cùng dấu (kích thích hoặc ức chế).", "ch": "ch05"}, {"term": "short-term plasticity", "vi": "tính mềm dẻo ngắn hạn (STP)", "def": "Thay đổi độ mạnh synapse kéo dài từ chục ms đến vài giây, do lịch sử spike gần đây của neuron pre gây ra; gồm facilitation và depression.", "ch": "ch05"}, {"term": "facilitation", "vi": "tăng cường ngắn hạn", "def": "Dạng STP trong đó đáp ứng lớn dần qua các spike liên tiếp, do Ca²⁺ tồn dư làm tăng xác suất release; điển hình ở synapse có p thấp.", "ch": "ch05"}, {"term": "short-term depression", "vi": "suy giảm ngắn hạn", "def": "Dạng STP trong đó đáp ứng nhỏ dần qua các spike liên tiếp, chủ yếu do kho vesicle sẵn sàng bị cạn; điển hình ở synapse có p cao.", "ch": "ch05"}, {"term": "Tsodyks–Markram model", "vi": "mô hình Tsodyks–Markram", "def": "Mô hình hiện tượng học của STP với hai biến: x (tài nguyên vesicle còn lại) và u (xác suất sử dụng), tham số U, τ_rec, τ_fac.", "ch": "ch05"}, {"term": "postsynaptic density", "vi": "mật độ sau synapse (PSD)", "def": "Đĩa protein dày đặc dưới màng sau synapse, chứa receptor, protein giàn giáo (PSD-95) và enzyme tín hiệu; hơn 1.000 loại protein.", "ch": "ch05"}, {"term": "silent synapse", "vi": "synapse câm", "def": "Synapse có NMDA receptor nhưng không có AMPA receptor, nên không truyền tín hiệu ở điện thế nghỉ; có thể được 'mở tiếng' bằng hoạt động trùng hợp pre–post.", "ch": "ch05"}, {"term": "quantal analysis", "vi": "phân tích lượng tử", "def": "Kỹ thuật suy ra n, p, q của một synapse từ thống kê dao động biên độ đáp ứng (trung bình, phương sai, tỉ lệ thất bại).", "ch": "ch05"}, {"term": "basal dendrite", "vi": "dendrite đáy", "def": "Các dendrite mọc từ đáy soma của neuron pyramidal, vươn 200–300 µm, chủ yếu nhận input feedforward.", "ch": "ch06"}, {"term": "apical dendrite", "vi": "dendrite đỉnh", "def": "Thân dendrite đơn mọc từ đỉnh soma neuron pyramidal, leo qua các lớp vỏ não, mang các nhánh xiên và kết thúc bằng chùm ngọn.", "ch": "ch06"}, {"term": "apical tuft", "vi": "chùm ngọn", "def": "Chùm nhánh tận của dendrite apical nằm ở lớp 1 vỏ não, nhận chủ yếu input feedback từ vùng cao hơn và thalamus bậc cao.", "ch": "ch06"}, {"term": "cable theory", "vi": "lý thuyết cáp", "def": "Khung toán học của Rall mô tả dendrite như sợi cáp dẫn điện có rò: điện thế lan dọc lõi, rò qua màng và sạc điện dung màng.", "ch": "ch06"}, {"term": "cable equation", "vi": "phương trình cáp", "def": "Phương trình đạo hàm riêng λ²∂²V/∂x² = τ∂V/∂t + V cho điện thế dọc một dendrite thụ động; về toán là phương trình khuếch tán có rò.", "ch": "ch06"}, {"term": "input resistance", "vi": "điện trở vào", "def": "Tỉ số giữa điện thế dừng và dòng bơm vào tại một điểm; nhánh mảnh, cụt có điện trở vào rất cao nên EPSP tại chỗ lớn.", "ch": "ch06"}, {"term": "compartmental model", "vi": "mô hình nhiều ngăn", "def": "Mô hình chia neuron thành nhiều ngăn đẳng thế nối bằng điện trở dọc trục, mỗi ngăn có phương trình màng riêng; nền tảng của các simulator như NEURON.", "ch": "ch06"}, {"term": "equivalent cylinder", "vi": "hình trụ tương đương", "def": "Kết quả của Rall: nếu đường kính nhánh thoả quy tắc mũ 3/2 tại mỗi chỗ rẽ, cả cây dendrite thụ động tương đương một hình trụ duy nhất.", "ch": "ch06"}, {"term": "spatial summation", "vi": "tổng hợp theo không gian", "def": "Các EPSP từ những synapse ở vị trí khác nhau cộng lại khi gặp nhau trên đường về soma.", "ch": "ch06"}, {"term": "sublinear summation", "vi": "cộng dưới tuyến tính", "def": "Tổng đáp ứng nhỏ hơn tổng các đáp ứng riêng lẻ, do driving force giảm và màng rò thêm khi nhiều synapse cùng nhánh mở đồng thời.", "ch": "ch06"}, {"term": "dendritic democracy", "vi": "dân chủ dendrite", "def": "Hiện tượng synapse xa có độ dẫn lớn hơn để EPSP đo tại soma gần như không phụ thuộc vị trí; thấy rõ ở CA1, không rõ ở neuron lớp 5 neocortex.", "ch": "ch06"}, {"term": "back-propagating action potential", "vi": "điện thế hoạt động lan ngược (bAP)", "def": "Spike khởi phát ở axon lan ngược chủ động lên cây dendrite, báo cho các synapse biết neuron vừa bắn; không liên quan tới thuật toán backpropagation.", "ch": "ch06"}, {"term": "dendritic spike", "vi": "spike dendrite", "def": "Sự kiện điện tái sinh khởi phát cục bộ trong dendrite; gồm Na⁺ spike, NMDA spike và Ca²⁺ spike, mỗi loại có thang thời gian và vai trò tính toán riêng.", "ch": "ch06"}, {"term": "NMDA spike", "vi": "NMDA spike", "def": "Cao nguyên khử cực 40–50 mV kéo dài 50–100 ms trong một nhánh mảnh khi ~10–20 synapse lân cận cùng hoạt động, do hồi tiếp dương giữa khử cực và việc gỡ nút Mg²⁺ khỏi receptor NMDA.", "ch": "ch06"}, {"term": "calcium spike", "vi": "Ca²⁺ spike", "def": "Spike rộng 20–50 ms do kênh Ca²⁺ nhạy điện áp ở vùng gần chùm ngọn của neuron pyramidal lớp 5; đẩy soma phát burst.", "ch": "ch06"}, {"term": "plateau potential", "vi": "điện thế cao nguyên", "def": "Khử cực dendrite kéo dài hàng chục đến hàng trăm ms (do NMDA và/hoặc Ca²⁺), hoạt động như bộ nhớ ngắn và tín hiệu chỉ dẫn cho plasticity.", "ch": "ch06"}, {"term": "burst", "vi": "chùm spike", "def": "Hai đến vài spike liên tiếp ở tần số cao (~100–200 Hz); ở neuron pyramidal thường báo hiệu một Ca²⁺ spike ở dendrite.", "ch": "ch06"}, {"term": "BAC firing", "vi": "BAC firing", "def": "Backpropagation-activated calcium spike firing: bAP trùng với input ở tuft trong vòng vài chục ms làm bùng Ca²⁺ spike và gây burst — cơ chế phát hiện sự ăn khớp giữa feedforward và feedback.", "ch": "ch06"}, {"term": "burst multiplexing", "vi": "ghép kênh bằng burst", "def": "Giả thuyết rằng tần suất sự kiện mang tín hiệu feedforward còn tỉ lệ burst mang tín hiệu feedback, cùng lúc trên một axon.", "ch": "ch06"}, {"term": "two-layer neuron model", "vi": "mô hình neuron hai lớp", "def": "Mô hình Poirazi–Mel: mỗi nhánh dendrite cộng input của mình rồi qua một sigmoid, soma cộng output các nhánh rồi áp ngưỡng — tương đương MLP hai lớp.", "ch": "ch06"}, {"term": "synaptic clustering", "vi": "gom cụm synapse", "def": "Các synapse có liên quan chức năng nằm cạnh nhau trên cùng nhánh, cho phép chúng hợp tác châm ngòi spike dendrite; mức độ phổ biến trong não còn tranh luận.", "ch": "ch06"}, {"term": "dCaAP", "vi": "dCaAP", "def": "Dendritic calcium-mediated action potential ở neuron pyramidal lớp 2/3 của người (Gidon 2020): biên độ cực đại tại ngưỡng và giảm khi kích thích mạnh hơn, cho phép tính XOR trong mô hình.", "ch": "ch06"}, {"term": "linearly separable", "vi": "tách tuyến tính", "def": "Tính chất của bài toán phân loại giải được bằng một siêu phẳng; XOR và feature binding không có tính chất này nên vượt quá khả năng của một đơn vị ngưỡng tuyến tính.", "ch": "ch06"}, {"term": "temporal convolutional network", "vi": "mạng tích chập thời gian (TCN)", "def": "Mạng nơ-ron dùng các lớp tích chập 1D theo trục thời gian; Beniaguev và cộng sự dùng TCN 5–8 lớp để bắt chước input–output của một neuron pyramidal.", "ch": "ch06"}, {"term": "behavioral timescale synaptic plasticity", "vi": "plasticity thang thời gian hành vi (BTSP)", "def": "Plasticity ở CA1 trong đó một plateau dendrite duy nhất tăng cường các synapse hoạt động trong cửa sổ hàng giây quanh nó, tạo place field chỉ sau một lần.", "ch": "ch06"}, {"term": "high-conductance state", "vi": "trạng thái độ dẫn cao", "def": "Trạng thái của neuron trong não tỉnh khi bị dội input liên tục: màng rò hơn, τm và λ ngắn lại, làm thay đổi cách dendrite tích hợp tín hiệu.", "ch": "ch06"}, {"term": "cell assembly", "vi": "tập hợp tế bào", "def": "Nhóm neuron nối chặt với nhau do hay cùng hoạt động, đến mức kích hoạt một phần là cả nhóm bừng lên; ý tưởng của Hebb, tiền thân của attractor.", "ch": "ch07"}, {"term": "long-term potentiation", "vi": "tăng cường dài hạn (LTP)", "def": "Sự tăng bền vững (giờ đến tháng) của độ mạnh synapse sau hoạt động mạnh hoặc đồng hoạt động pre–post; Bliss & Lømo mô tả năm 1973.", "ch": "ch07"}, {"term": "long-term depression", "vi": "suy giảm dài hạn (LTD)", "def": "Sự giảm bền vững độ mạnh synapse, điển hình sau kích thích tần số thấp kéo dài (1 Hz) hoặc khi post bắn trước pre.", "ch": "ch07"}, {"term": "tetanus", "vi": "loạt kích thích tần số cao", "def": "Chuỗi xung điện dồn dập (vd. 100 Hz trong 1 s) dùng trong thí nghiệm để gây LTP.", "ch": "ch07"}, {"term": "CaMKII", "vi": "kinase II phụ thuộc Ca²⁺/calmodulin", "def": "Protein dồi dào ở mảng sau synapse, được Ca²⁺ kích hoạt và tự phosphoryl hoá để giữ trạng thái hoạt động; bám vào NMDA receptor (GluN2B) và cần thiết cho khởi phát LTP.", "ch": "ch07"}, {"term": "AMPA receptor trafficking", "vi": "vận chuyển thụ thể AMPA", "def": "Việc đưa thêm (LTP) hoặc rút bớt (LTD) AMPA receptor ở màng sau synapse; cơ chế biểu hiện chính của thay đổi weight ở nhiều synapse.", "ch": "ch07"}, {"term": "calcium control hypothesis", "vi": "giả thuyết điều khiển bằng calcium", "def": "Dấu và độ lớn của plasticity do mức Ca²⁺ sau synapse quyết định: vừa phải, kéo dài → LTD (phosphatase); cao, nhanh → LTP (kinase).", "ch": "ch07"}, {"term": "early LTP", "vi": "LTP sớm (E-LTP)", "def": "Pha LTP kéo dài 1–3 giờ, chỉ dùng protein có sẵn (phosphoryl hoá, di chuyển receptor), không cần tổng hợp protein mới.", "ch": "ch07"}, {"term": "late LTP", "vi": "LTP muộn (L-LTP)", "def": "Pha LTP kéo dài nhiều giờ đến nhiều ngày, đòi hỏi phiên mã và tổng hợp protein mới; bị chặn bởi anisomycin.", "ch": "ch07"}, {"term": "CREB", "vi": "yếu tố phiên mã CREB", "def": "Yếu tố phiên mã được kích hoạt bởi tín hiệu mạnh/lặp lại (qua PKA, MAPK), bật các gene cần cho trí nhớ dài hạn; bảo tồn từ Aplysia đến động vật có vú.", "ch": "ch07"}, {"term": "synaptic tagging and capture", "vi": "gắn thẻ và bắt giữ ở synapse", "def": "Giả thuyết Frey & Morris: hoạt động để lại tag cục bộ tạm thời ở synapse; chỉ synapse có tag mới bắt được protein mới tổng hợp phát tán toàn tế bào để củng cố LTP.", "ch": "ch07"}, {"term": "structural plasticity", "vi": "tính dẻo cấu trúc", "def": "Thay đổi vật lý của kết nối: spine to ra hay teo lại, synapse mới mọc và synapse cũ bị tỉa.", "ch": "ch07"}, {"term": "STDP", "vi": "tính dẻo phụ thuộc thời điểm spike", "def": "Spike-timing-dependent plasticity: pre bắn trước post vài–vài chục ms → LTP, thứ tự ngược lại → LTD; hình dạng cửa sổ thay đổi theo loại synapse và điều kiện.", "ch": "ch07"}, {"term": "eligibility trace", "vi": "dấu vết đủ điều kiện", "def": "Biến trạng thái cục bộ tại synapse, suy giảm theo thời gian, ghi nhớ hoạt động vừa qua để kết hợp với một tín hiệu đến sau (spike đối tác, neuromodulator, phần thưởng).", "ch": "ch07"}, {"term": "BTSP", "vi": "tính dẻo synapse theo thang thời gian hành vi", "def": "Behavioral timescale synaptic plasticity: ở CA1, một dendritic plateau potential tăng cường các synapse hoạt động trong vòng vài giây trước/sau nó, tạo place field chỉ sau một vài lần.", "ch": "ch07"}, {"term": "Oja's rule", "vi": "luật Oja", "def": "Δw = η·y·(x − y·w): Hebb cộng số hạng quên tỉ lệ y²; cục bộ, giữ ‖w‖ = 1 và hội tụ về principal component thứ nhất của input.", "ch": "ch07"}, {"term": "BCM rule", "vi": "luật BCM", "def": "Luật Bienenstock–Cooper–Munro: Δw ∝ x·y·(y − θ) với ngưỡng θ trượt theo trung bình của y²; ổn định và sinh ra selectivity.", "ch": "ch07"}, {"term": "metaplasticity", "vi": "siêu dẻo (plasticity của plasticity)", "def": "Lịch sử hoạt động làm thay đổi khả năng và ngưỡng của plasticity về sau, ví dụ ngưỡng LTD/LTP trượt theo hoạt động trung bình.", "ch": "ch07"}, {"term": "homeostatic plasticity", "vi": "tính dẻo cân bằng nội môi", "def": "Các cơ chế hồi tiếp âm chậm giữ hoạt động của neuron quanh một mức đặt trước, đối trọng với hồi tiếp dương của Hebb.", "ch": "ch07"}, {"term": "synaptic scaling", "vi": "co giãn synapse", "def": "Dạng homeostasis do Turrigiano mô tả: neuron nhân toàn bộ các synapse kích thích của nó với cùng một hệ số để đưa firing rate về set point, bảo toàn tỉ lệ giữa các weight.", "ch": "ch07"}, {"term": "intrinsic plasticity", "vi": "tính dẻo nội tại", "def": "Thay đổi tính kích thích của chính neuron (mật độ kênh ion, ngưỡng, độ dốc đường f–I) theo lịch sử hoạt động; tương tự chỉnh bias và gain.", "ch": "ch07"}, {"term": "heterosynaptic plasticity", "vi": "tính dẻo dị synapse", "def": "Thay đổi ở các synapse không trực tiếp hoạt động, ví dụ spine hàng xóm yếu đi khi một spine được tăng cường; giúp giữ tổng weight ổn định một cách nhanh chóng.", "ch": "ch07"}, {"term": "critical period", "vi": "giai đoạn then chốt", "def": "Cửa sổ phát triển trong đó kinh nghiệm định hình mạch thần kinh mạnh mẽ và khó đảo ngược; mở bởi sự trưởng thành của ức chế (PV), đóng bởi các phanh phân tử như perineuronal net.", "ch": "ch07"}, {"term": "ocular dominance", "vi": "ưu thế mắt", "def": "Mức độ một neuron vỏ thị giác đáp ứng với mắt này hơn mắt kia; dịch chuyển mạnh khi bịt một mắt trong critical period.", "ch": "ch07"}, {"term": "perineuronal net", "vi": "lưới quanh neuron (PNN)", "def": "Lớp chất nền ngoại bào đặc bao quanh chủ yếu các interneuron PV, hình thành cuối critical period và kìm hãm plasticity; làm tan nó có thể mở lại độ dẻo.", "ch": "ch07"}, {"term": "fast weights", "vi": "trọng số nhanh", "def": "Thành phần weight thay đổi nhanh và tạm thời theo hoạt động gần đây (thường bằng outer product kiểu Hebb), làm bộ nhớ ngắn hạn trên nền slow weights; tương đương hình thức với linear attention.", "ch": "ch07"}, {"term": "neuromodulation", "vi": "điều biến thần kinh", "def": "Kiểu truyền tin trong đó một chất không trực tiếp kích thích hay ức chế neuron đích mà thay đổi cách neuron và synapse đáp ứng với input khác, thường trên vùng rộng và trong thời gian dài.", "ch": "ch08"}, {"term": "neuromodulator", "vi": "chất điều biến thần kinh", "def": "Chất (dopamine, noradrenaline, acetylcholine, serotonin, neuropeptide…) hoạt động theo kiểu neuromodulation, chủ yếu qua receptor GPCR.", "ch": "ch08"}, {"term": "wired transmission", "vi": "truyền theo dây", "def": "Truyền tin điểm-tới-điểm qua synapse nhanh: chất dẫn truyền bị giam trong khe ~20 nm, tác động lên một cụm receptor trong ~1 ms.", "ch": "ch08"}, {"term": "volume transmission", "vi": "truyền theo thể tích", "def": "Chất dẫn truyền khuếch tán trong khoảng gian bào, tác động lên nhiều đích ở xa chỗ phóng thích vài đến vài chục µm; khái niệm của Agnati và Fuxe (1986).", "ch": "ch08"}, {"term": "varicosity", "vi": "chỗ phình axon", "def": "Chỗ phình dọc axon chứa túi chất dẫn truyền; ở các neuron monoamine, nhiều varicosity phóng chất mà không có màng sau synapse chuyên biệt đối diện.", "ch": "ch08"}, {"term": "dopamine transporter", "vi": "transporter thu hồi dopamine (DAT)", "def": "Protein trên axon dopamine bơm dopamine ngoại bào trở lại tế bào; quyết định tầm lan và thời gian sống của tín hiệu. Đích của cocaine, amphetamine, methylphenidate.", "ch": "ch08"}, {"term": "GPCR", "vi": "receptor ghép cặp protein G", "def": "Họ receptor xuyên màng bảy lần; khi gắn ligand thì kích hoạt protein G nội bào và khởi động chuỗi tín hiệu sinh hoá thay vì mở kênh ion. Còn gọi receptor metabotropic.", "ch": "ch08"}, {"term": "G protein", "vi": "protein G", "def": "Protein gắn GTP truyền tín hiệu từ GPCR tới enzyme hoặc kênh ion; các loại chính: Gs (tăng cAMP), Gi/o (giảm cAMP, mở kênh GIRK), Gq (bật phospholipase C).", "ch": "ch08"}, {"term": "second messenger", "vi": "chất truyền tin thứ hai", "def": "Phân tử nhỏ nội bào (cAMP, IP3, DAG, Ca2+) được sản xuất hàng loạt sau khi receptor bị kích hoạt, khuếch đại và lan truyền tín hiệu trong tế bào.", "ch": "ch08"}, {"term": "PKA", "vi": "protein kinase A", "def": "Enzyme được cAMP kích hoạt, gắn nhóm phosphate lên kênh ion, receptor AMPA, yếu tố phiên mã CREB… qua đó đổi excitability và plasticity.", "ch": "ch08"}, {"term": "noradrenaline", "vi": "noradrenaline (norepinephrine)", "def": "Neuromodulator từ locus coeruleus, chiếu gần như toàn bộ não; gắn với arousal, gain, unexpected uncertainty và cân bằng explore–exploit.", "ch": "ch08"}, {"term": "acetylcholine", "vi": "acetylcholine", "def": "Chất dẫn truyền nhanh ở chỗ nối thần kinh–cơ và neuromodulator trong não (từ basal forebrain, thân não); gắn với attention, cho phép plasticity, chuyển chế độ encoding/retrieval.", "ch": "ch08"}, {"term": "serotonin", "vi": "serotonin (5-HT)", "def": "Neuromodulator từ các nhân raphe với ít nhất 14 loại receptor; các giả thuyết: kiên nhẫn/discount factor, dự đoán trừng phạt, mã giá trị tiên lượng.", "ch": "ch08"}, {"term": "VTA", "vi": "vùng trần bụng (ventral tegmental area)", "def": "Cụm neuron dopamine ở midbrain chiếu lên nucleus accumbens, amygdala và prefrontal cortex.", "ch": "ch08"}, {"term": "SNc", "vi": "chất đen phần đặc (substantia nigra pars compacta)", "def": "Cụm neuron dopamine ở midbrain chiếu lên dorsal striatum; thoái hoá trong bệnh Parkinson.", "ch": "ch08"}, {"term": "locus coeruleus", "vi": "nhân lục (điểm xanh)", "def": "Nhân nhỏ ở pons (~22–51 nghìn neuron ở người), nguồn noradrenaline chính của não trước.", "ch": "ch08"}, {"term": "raphe nuclei", "vi": "các nhân raphe", "def": "Chuỗi nhân dọc đường giữa thân não chứa neuron serotonin; dorsal raphe là nhân lớn nhất.", "ch": "ch08"}, {"term": "basal forebrain", "vi": "nền não trước", "def": "Nhóm nhân (nucleus basalis của Meynert, medial septum…) cung cấp acetylcholine cho vỏ não và hippocampus; thoái hoá sớm trong Alzheimer.", "ch": "ch08"}, {"term": "neuropeptide", "vi": "neuropeptide", "def": "Chuỗi peptide ngắn (opioid, orexin, oxytocin, NPY…) được neuron tiết ra làm chất điều biến, tác động qua GPCR theo kiểu volume transmission.", "ch": "ch08"}, {"term": "orexin", "vi": "orexin (hypocretin)", "def": "Neuropeptide từ vài chục nghìn neuron ở lateral hypothalamus, ổn định trạng thái thức; mất các neuron này gây chứng ngủ rũ.", "ch": "ch08"}, {"term": "M-current", "vi": "dòng M", "def": "Dòng K+ chậm qua kênh KCNQ, gây adaptation; bị acetylcholine (receptor muscarinic) đóng lại, làm neuron dễ kích thích hơn.", "ch": "ch08"}, {"term": "three-factor learning rule", "vi": "luật học ba yếu tố", "def": "Luật plasticity trong đó thay đổi trọng số = (trace cục bộ từ hoạt động pre và post) × (tín hiệu neuromodulator toàn cục). Còn gọi luật neoHebbian.", "ch": "ch08"}, {"term": "distal reward problem", "vi": "bài toán phần thưởng xa", "def": "Vấn đề gán công cho đúng synapse khi phần thưởng đến trễ hàng giây sau hoạt động thần kinh gây ra nó (Izhikevich 2007).", "ch": "ch08"}, {"term": "phasic", "vi": "phasic (theo đợt)", "def": "Kiểu hoạt động thành burst ngắn, đồng bộ của nhân neuromodulator, gắn với sự kiện cụ thể.", "ch": "ch08"}, {"term": "tonic", "vi": "tonic (nền)", "def": "Mức hoạt động nền, chậm và đều của nhân neuromodulator, quy định nồng độ nền của chất điều biến.", "ch": "ch08"}, {"term": "adaptive gain theory", "vi": "lý thuyết gain thích nghi", "def": "Lý thuyết của Aston-Jones và Cohen (2005): chế độ phasic của locus coeruleus tối ưu hoá exploit, chế độ tonic cao thúc đẩy explore, chuyển chế độ theo utility của nhiệm vụ.", "ch": "ch08"}, {"term": "expected uncertainty", "vi": "bất định đã lường trước", "def": "Mức không đáng tin đã biết của các dự đoán trong một bối cảnh ổn định; theo Yu và Dayan được báo bởi acetylcholine.", "ch": "ch08"}, {"term": "unexpected uncertainty", "vi": "bất định ngoài dự kiến", "def": "Sai số dự đoán lớn vượt mức nhiễu quen thuộc, gợi ý bối cảnh đã đổi; theo Yu và Dayan được báo bởi noradrenaline.", "ch": "ch08"}, {"term": "meta-learning", "vi": "học cách học", "def": "Điều chỉnh chính các tham số của quá trình học (learning rate, temperature, discount); Doya (2002) giả thuyết các hệ neuromodulator thực hiện việc này trong não.", "ch": "ch08"}, {"term": "discount factor", "vi": "hệ số chiết khấu", "def": "Tham số γ trong RL quy định phần thưởng tương lai bị giảm giá bao nhiêu; Doya gán cho serotonin.", "ch": "ch08"}, {"term": "inverse temperature", "vi": "nghịch đảo nhiệt độ", "def": "Tham số β của softmax chọn hành động: cao → exploit quyết đoán, thấp → explore ngẫu nhiên; Doya gán cho noradrenaline.", "ch": "ch08"}, {"term": "FiLM", "vi": "feature-wise linear modulation", "def": "Lớp conditioning trong DL: một mạng phụ sinh hệ số nhân γ và cộng β cho từng channel từ tín hiệu ngữ cảnh.", "ch": "ch08"}, {"term": "cotransmission", "vi": "đồng phóng thích", "def": "Một neuron phóng nhiều hơn một chất dẫn truyền, ví dụ neuron dopamine đồng phóng glutamate hoặc GABA.", "ch": "ch08"}, {"term": "weight transport", "vi": "vận chuyển trọng số", "def": "Đòi hỏi của backprop rằng đường phản hồi phải dùng đúng trọng số của đường xuôi (Wᵀ); khó về sinh học vì synapse một chiều và hai synapse nằm trên hai tế bào khác nhau.", "ch": "ch09"}, {"term": "weight perturbation", "vi": "nhiễu loạn trọng số", "def": "Học bằng cách cộng nhiễu vào trọng số, đo thay đổi của loss rồi dịch trọng số theo hướng làm loss giảm; không chệch nhưng phương sai tăng theo số synapse.", "ch": "ch09"}, {"term": "node perturbation", "vi": "nhiễu loạn neuron", "def": "Học bằng cách rung hoạt động của neuron và tương quan nhiễu ấy với một tín hiệu đánh giá vô hướng toàn cục; là một luật ba yếu tố, chậm hơn gradient descent một thừa số cỡ số neuron.", "ch": "ch09"}, {"term": "REINFORCE", "vi": "REINFORCE", "def": "Thuật toán policy gradient của Williams (1992): cập nhật tỉ lệ với (reward − baseline) nhân với độ lệch ngẫu nhiên của đơn vị; tương đương node perturbation với reward làm tín hiệu toàn cục.", "ch": "ch09"}, {"term": "feedback alignment", "vi": "căn chỉnh phản hồi", "def": "Phát hiện của Lillicrap và cs.: thay Wᵀ trong backprop bằng ma trận ngẫu nhiên cố định B mà mạng vẫn học, vì trọng số xuôi tự xoay để tín hiệu dạy lệch gradient thật dưới 90°.", "ch": "ch09"}, {"term": "direct feedback alignment", "vi": "căn chỉnh phản hồi trực tiếp", "def": "Biến thể của Nøkland: lỗi ở output được chiếu thẳng tới từng lớp ẩn qua các ma trận ngẫu nhiên riêng, không đi qua các lớp trung gian.", "ch": "ch09"}, {"term": "sign symmetry", "vi": "đối xứng dấu", "def": "Biến thể trong đó trọng số phản hồi chỉ cần cùng dấu với trọng số xuôi tương ứng, độ lớn tuỳ ý; đủ để huấn luyện mạng sâu trên ImageNet gần ngang backprop.", "ch": "ch09"}, {"term": "Kolen–Pollack", "vi": "Kolen–Pollack", "def": "Cơ chế (1994) làm đường phản hồi hội tụ về Wᵀ: synapse xuôi và synapse ngược nhận cùng một lượng cập nhật cục bộ và cùng chịu weight decay, nên khác biệt ban đầu phân rã theo hàm mũ.", "ch": "ch09"}, {"term": "weight mirror", "vi": "gương trọng số", "def": "Phương pháp của Akrout và cs. (2019): trong một pha riêng, cho nhiễu chạy qua mạng và để synapse phản hồi học kiểu Hebb, kỳ vọng của cập nhật bằng Wᵀ.", "ch": "ch09"}, {"term": "target propagation", "vi": "lan truyền mục tiêu", "def": "Họ thuật toán truyền ngược các mẫu hoạt động đích thay vì gradient, nhờ các ánh xạ ngược học được như autoencoder; mỗi lớp học cục bộ để tiến về đích của mình.", "ch": "ch09"}, {"term": "contrastive Hebbian learning", "vi": "học Hebb tương phản", "def": "Luật học hai pha: Hebb khi output bị kẹp vào đáp án, anti-Hebb khi mạng chạy tự do; lỗi được mã hoá bằng hiệu của hai trạng thái hoạt động.", "ch": "ch09"}, {"term": "equilibrium propagation", "vi": "lan truyền cân bằng", "def": "Thuật toán của Scellier & Bengio (2017) cho mạng năng lượng đối xứng: hích nhẹ output về phía đáp án, hiệu hoạt động giữa hai trạng thái cân bằng cho đúng gradient khi cú hích tiến về 0.", "ch": "ch09"}, {"term": "NGRAD", "vi": "NGRAD", "def": "Neural gradient representation by activity differences: giả thuyết rằng não biểu diễn tín hiệu kiểu gradient bằng sự thay đổi hoạt động neuron (theo thời gian hoặc giữa hai trạng thái), không bằng một kênh lỗi riêng.", "ch": "ch09"}, {"term": "predictive coding", "vi": "mã hoá dự đoán", "def": "Kiến trúc trong đó mỗi lớp dự đoán hoạt động của lớp kề bên, neuron sai số mang phần chưa dự đoán được; hoạt động và synapse cùng cực tiểu hoá tổng bình phương sai số dự đoán bằng luật cục bộ.", "ch": "ch09"}, {"term": "error neuron", "vi": "neuron sai số", "def": "Trong predictive coding, quần thể neuron mang hiệu giữa hoạt động thật và dự đoán; tại cân bằng hoạt động của chúng đóng vai δ của backprop.", "ch": "ch09"}, {"term": "prospective configuration", "vi": "cấu hình hướng tới", "def": "Nguyên lý học (Song và cs. 2024) trong đó hoạt động neuron được thả lỏng trước về cấu hình nên có sau khi học, rồi synapse mới thay đổi để củng cố cấu hình đó; giảm giao thoa so với backprop.", "ch": "ch09"}, {"term": "burst-dependent plasticity", "vi": "plasticity phụ thuộc burst", "def": "Luật học trong đó synapse vừa hoạt động được LTP nếu neuron sau synapse phát burst và LTD nếu chỉ phát spike đơn, so với tỉ lệ burst trung bình gần đây.", "ch": "ch09"}, {"term": "SST interneuron", "vi": "interneuron SST", "def": "Interneuron ức chế biểu hiện somatostatin, nhắm vào dendrite xa của neuron pyramidal; trong mô hình Sacramento 2018 nó triệt tiêu phần feedback đã dự đoán được để lộ ra sai số.", "ch": "ch09"}, {"term": "three-factor rule", "vi": "luật ba yếu tố", "def": "Luật plasticity có dạng (hoạt động trước synapse) × (hoạt động sau synapse) × (tín hiệu thứ ba như neuromodulator hay tín hiệu dạy từ trên xuống).", "ch": "ch09"}, {"term": "backpropagation through time", "vi": "lan truyền ngược qua thời gian", "def": "BPTT: trải mạng hồi quy theo trục thời gian rồi backprop qua nó; đòi lưu toàn bộ lịch sử hoạt động và truyền lỗi ngược thời gian.", "ch": "ch09"}, {"term": "real-time recurrent learning", "vi": "học hồi quy thời gian thực", "def": "RTRL: tính đúng gradient của mạng hồi quy chỉ bằng cách đi xuôi thời gian, nhưng tốn bộ nhớ O(n³) và tính toán O(n⁴) mỗi bước.", "ch": "ch09"}, {"term": "e-prop", "vi": "e-prop", "def": "Eligibility propagation (Bellec và cs. 2020): xấp xỉ online của BPTT, viết gradient thành tổng theo thời gian của learning signal từng neuron nhân eligibility trace từng synapse.", "ch": "ch09"}, {"term": "forward-forward algorithm", "vi": "thuật toán forward-forward", "def": "Đề xuất của Hinton (2022): thay lượt xuôi–ngược bằng hai lượt xuôi trên dữ liệu thật và dữ liệu giả, mỗi lớp tối ưu một hàm goodness cục bộ, không truyền đạo hàm qua lớp.", "ch": "ch09"}, {"term": "local learning rule", "vi": "luật học cục bộ", "def": "Luật cập nhật synapse chỉ dùng thông tin có mặt tại synapse đó: hoạt động hai neuron mà nó nối và các tín hiệu hoá học lan tới.", "ch": "ch09"}, {"term": "climbing fiber", "vi": "sợi leo", "def": "Axon từ nhân olive dưới; mỗi tế bào Purkinje nhận đúng một sợi, mang tín hiệu sai số riêng cho neuron đó và gây LTD ở synapse parallel fiber vừa hoạt động.", "ch": "ch09"}, {"term": "neural manifold", "vi": "đa tạp thần kinh", "def": "Không gian con ít chiều mà hoạt động của một quần thể neuron thực sự chiếm; việc học ngắn hạn qua BCI dễ khi nằm trong đa tạp và khó khi nằm ngoài.", "ch": "ch09"}, {"term": "catastrophic interference", "vi": "giao thoa thảm hoạ", "def": "Hiện tượng học điều mới làm hỏng điều đã học vì các tham số dùng chung bị thay đổi; backprop đặc biệt dễ mắc khi học online.", "ch": "ch09"}, {"term": "neural coding", "vi": "mã hoá thần kinh", "def": "Lĩnh vực nghiên cứu quan hệ giữa kích thích/hành vi và các chuỗi spike: thông tin được biểu diễn thế nào và đọc ra thế nào.", "ch": "ch10"}, {"term": "rate code", "vi": "mã tần số", "def": "Giả thuyết rằng thông tin nằm ở số spike trong một cửa sổ thời gian, không ở thời điểm chính xác của từng spike (Adrian 1926).", "ch": "ch10"}, {"term": "tuning curve", "vi": "đường cong điều hưởng", "def": "Firing rate trung bình của một neuron như hàm của một tham số kích thích; đỉnh của nó là kích thích ưa thích.", "ch": "ch10"}, {"term": "encoding", "vi": "mã hoá", "def": "Ánh xạ từ kích thích sang đáp ứng thần kinh, P(r|s); góc nhìn của nhà thực nghiệm điều khiển kích thích.", "ch": "ch10"}, {"term": "decoding", "vi": "giải mã", "def": "Suy ngược kích thích từ đáp ứng thần kinh, P(s|r); bài toán mà hạ nguồn của não (và BCI) phải giải.", "ch": "ch10"}, {"term": "Fano factor", "vi": "hệ số Fano", "def": "Phương sai chia trung bình của số spike qua các trial; bằng 1 với Poisson, ≈1–1,5 ở vỏ não, gần 0 với neuron phát đều.", "ch": "ch10"}, {"term": "temporal code", "vi": "mã thời gian", "def": "Mã trong đó thời điểm spike mang thông tin ở thang thời gian mịn hơn thang biến thiên của chính kích thích.", "ch": "ch10"}, {"term": "latency code", "vi": "mã độ trễ", "def": "Cường độ kích thích được mã bằng thời gian tới spike đầu tiên: input mạnh thì phát sớm; thứ tự phát của dân số gọi là rank-order code.", "ch": "ch10"}, {"term": "phase code", "vi": "mã pha", "def": "Thông tin nằm ở pha của spike so với một dao động nền (vd. theta ở hippocampus), như trong phase precession.", "ch": "ch10"}, {"term": "population code", "vi": "mã dân số", "def": "Biến được biểu diễn bằng mẫu hoạt động trên nhiều neuron chứ không ở neuron riêng lẻ nào.", "ch": "ch10"}, {"term": "population vector", "vi": "vector dân số", "def": "Bộ giải mã của Georgopoulos: tổng các vector hướng ưa thích, mỗi vector nhân với mức phát (trừ nền) của neuron tương ứng.", "ch": "ch10"}, {"term": "maximum likelihood", "vi": "hợp lý cực đại", "def": "Ước lượng chọn giá trị kích thích làm xác suất của đáp ứng quan sát được lớn nhất; với dân số Poisson độc lập, log-likelihood tuyến tính theo số spike.", "ch": "ch10"}, {"term": "probabilistic population code", "vi": "mã dân số xác suất", "def": "Giả thuyết rằng hoạt động dân số biểu diễn cả một phân phối xác suất; với noise kiểu Poisson, biên độ hoạt động mã hoá độ chắc chắn (Ma và cs. 2006).", "ch": "ch10"}, {"term": "Fisher information", "vi": "thông tin Fisher", "def": "Độ cong trung bình của log-likelihood theo tham số; nghịch đảo của nó là cận dưới Cramér–Rao cho phương sai ước lượng. Với Poisson độc lập: J = T·Σ f'²/f.", "ch": "ch10"}, {"term": "noise correlation", "vi": "tương quan noise", "def": "Tương quan giữa dao động từ-trial-sang-trial của hai neuron khi kích thích giữ nguyên; khác signal correlation là độ giống nhau của tuning.", "ch": "ch10"}, {"term": "differential correlations", "vi": "tương quan vi sai", "def": "Thành phần hiệp phương sai noise tỉ lệ với f'f'ᵀ — dạng tương quan duy nhất giới hạn thông tin khi số neuron tiến tới vô hạn (Moreno-Bote 2014).", "ch": "ch10"}, {"term": "mutual information", "vi": "thông tin tương hỗ", "def": "I(S;R) = H(R) − H(R|S): lượng bất định về kích thích giảm đi khi biết đáp ứng, tính bằng bit.", "ch": "ch10"}, {"term": "efficient coding", "vi": "mã hoá hiệu quả", "def": "Giả thuyết (Barlow 1961) rằng mã cảm giác được tối ưu để truyền nhiều thông tin nhất về môi trường tự nhiên dưới ràng buộc sinh lý, bằng cách giảm dư thừa.", "ch": "ch10"}, {"term": "whitening", "vi": "làm trắng", "def": "Biến đổi làm phẳng phổ công suất/khử tương quan giữa các kênh; ở võng mạc tương ứng với receptive field center–surround.", "ch": "ch10"}, {"term": "Gabor filter", "vi": "bộ lọc Gabor", "def": "Sóng sin nhân với bao Gauss: bộ lọc cục bộ, có hướng và tần số không gian; mô tả tốt receptive field của simple cell ở V1.", "ch": "ch10"}, {"term": "grandmother cell", "vi": "tế bào bà ngoại", "def": "Ý tưởng (mang tính chế giễu, Lettvin ~1969) rằng mỗi đối tượng được biểu diễn bởi một neuron riêng — mã cục bộ kiểu one-hot.", "ch": "ch10"}, {"term": "concept cell", "vi": "tế bào khái niệm", "def": "Neuron ở thuỳ thái dương trong của người đáp ứng rất chọn lọc và bất biến với một người/vật/khái niệm (vd. 'neuron Jennifer Aniston'); thuộc một mã thưa phân tán.", "ch": "ch10"}, {"term": "mixed selectivity", "vi": "tính chọn lọc hỗn hợp", "def": "Neuron đáp ứng với tổ hợp (thường phi tuyến) của nhiều biến nhiệm vụ; làm tăng số chiều biểu diễn và sức mạnh của bộ đọc tuyến tính.", "ch": "ch10"}, {"term": "superposition", "vi": "chồng chập", "def": "Hiện tượng mạng biểu diễn nhiều feature thưa hơn số chiều bằng các hướng gần-trực-giao, khiến từng neuron trở nên đa nghĩa (Elhage và cs. 2022).", "ch": "ch10"}, {"term": "representational drift", "vi": "trôi biểu diễn", "def": "Tuning của từng neuron thay đổi dần qua ngày/tuần trong khi hành vi và hình học mức dân số tương đối ổn định.", "ch": "ch10"}, {"term": "signal correlation", "vi": "tương quan tín hiệu", "def": "Độ giống nhau giữa tuning curve của hai neuron, tức tương quan của đáp ứng trung bình qua các kích thích.", "ch": "ch10"}, {"term": "noise entropy", "vi": "entropy noise", "def": "H(R|S): độ đa dạng còn lại của đáp ứng khi kích thích được giữ nguyên; phần entropy không mang thông tin về kích thích.", "ch": "ch10"}, {"term": "phase precession", "vi": "tiến động pha", "def": "Place cell phát ở pha ngày càng sớm của nhịp theta khi con vật đi xuyên qua place field (O'Keefe & Recce 1993).", "ch": "ch10"}, {"term": "polysemantic neuron", "vi": "neuron đa nghĩa", "def": "Unit trong mạng nhân tạo đáp ứng với nhiều feature không liên quan; hệ quả của superposition và là họ hàng của mixed selectivity.", "ch": "ch10"}, {"term": "cortical layer", "vi": "lớp vỏ não", "def": "Một trong sáu dải ngang (L1–L6) của neocortex, khác nhau về loại tế bào và về địa chỉ vào–ra: L4 nhận từ thalamus, L2/3 nối sang vùng vỏ não khác, L5 xuất xuống dưới vỏ, L6 hồi tiếp về thalamus.", "ch": "ch11"}, {"term": "canonical microcircuit", "vi": "vi mạch chuẩn", "def": "Giả thuyết của Douglas & Martin: cùng một mô-típ mạch (quần thể E nông, E sâu, bể ức chế chung, recurrent excitation mạnh, input ngoài yếu) lặp lại trên khắp neocortex.", "ch": "ch11"}, {"term": "cortical column", "vi": "cột vỏ não", "def": "Nhóm neuron xếp dọc từ L2 đến L6, rộng khoảng 0,3–0,5 mm, có chung tính chất đáp ứng (Mountcastle 1957); việc nó có phải đơn vị tính toán hay không vẫn còn tranh cãi.", "ch": "ch11"}, {"term": "recurrent amplification", "vi": "khuếch đại hồi quy", "def": "Input yếu được thổi lên nhiều lần nhờ các neuron kích thích cùng sở thích kích thích lẫn nhau; gain ≈ 1/(1−w), nên càng mạnh càng gần bất ổn.", "ch": "ch11"}, {"term": "E/I balance", "vi": "cân bằng kích thích/ức chế", "def": "Trạng thái mà dòng kích thích và dòng ức chế vào mỗi neuron đều lớn nhưng gần triệt tiêu nhau, để điện thế màng nằm sát dưới ngưỡng và spike do dao động gây ra.", "ch": "ch11"}, {"term": "balanced network", "vi": "mạng cân bằng", "def": "Mô hình mạng recurrent (van Vreeswijk & Sompolinsky 1996) với synapse cỡ 1/√K, tự động đạt E/I balance, cho firing bất quy tắc, đáp ứng quần thể tuyến tính và chaos tất định.", "ch": "ch11"}, {"term": "asynchronous irregular state", "vi": "trạng thái bất đồng bộ, bất quy tắc", "def": "Chế độ hoạt động nền của vỏ não tỉnh: mỗi neuron bắn thưa, bất quy tắc (CV ≈ 1) và gần như không tương quan với neuron khác, tốc độ quần thể ổn định.", "ch": "ch11"}, {"term": "inhibition-stabilized network", "vi": "mạng được ức chế giữ ổn định (ISN)", "def": "Mạng mà recurrent excitation đủ mạnh để tự nó bất ổn (w_EE > 1) và chỉ ổn định nhờ hồi tiếp ức chế nhanh; vỏ não dường như hoạt động ở chế độ này.", "ch": "ch11"}, {"term": "paradoxical effect", "vi": "hiệu ứng nghịch lý", "def": "Chữ ký của ISN: bơm thêm kích thích vào quần thể ức chế làm firing rate ổn định của chính quần thể đó giảm, vì quần thể E nuôi nó sụp mạnh hơn.", "ch": "ch11"}, {"term": "Wilson–Cowan model", "vi": "mô hình Wilson–Cowan", "def": "Mô hình rate hai quần thể E và I (1972) với các phương trình vi phân ghép cặp; khung chuẩn để phân tích ổn định, dao động và ISN.", "ch": "ch11"}, {"term": "PV interneuron", "vi": "interneuron parvalbumin", "def": "Interneuron fast-spiking (basket, chandelier) nhắm vào soma và AIS của pyramidal; điều khiển gain, thời điểm spike, ổn định mạng và sinh nhịp gamma.", "ch": "ch11"}, {"term": "VIP interneuron", "vi": "interneuron VIP", "def": "Interneuron chủ yếu ức chế SST cell, được lái bởi feedback xa và neuromodulator; khi hoạt động nó giải ức chế dendrite của pyramidal.", "ch": "ch11"}, {"term": "basket cell", "vi": "tế bào rổ", "def": "Interneuron PV có các đầu axon ôm quanh soma của neuron pyramidal như chiếc rổ, tạo inhibition nhanh và mạnh quanh thân tế bào.", "ch": "ch11"}, {"term": "chandelier cell", "vi": "tế bào đèn chùm", "def": "Interneuron axo-axonic đặt toàn bộ synapse lên axon initial segment của pyramidal — đúng nơi spike khởi phát.", "ch": "ch11"}, {"term": "Martinotti cell", "vi": "tế bào Martinotti", "def": "Interneuron SST có axon leo lên L1 và ức chế apical tuft của neuron pyramidal.", "ch": "ch11"}, {"term": "disinhibition", "vi": "giải ức chế", "def": "Motif mạch trong đó một interneuron ức chế một interneuron khác (VIP → SST), làm neuron đích cuối cùng được giải phóng khỏi ức chế; hoạt động như một cổng mở theo ngữ cảnh.", "ch": "ch11"}, {"term": "divisive normalization", "vi": "chuẩn hoá bằng phép chia", "def": "Phép tính trong đó đáp ứng của mỗi neuron bằng drive của nó chia cho (hằng số + tổng hoạt động của một pool neuron lân cận); giải thích bão hoà contrast, suppression và bất biến tuning.", "ch": "ch11"}, {"term": "normalization pool", "vi": "pool chuẩn hoá", "def": "Tập các neuron mà tổng hoạt động của chúng xuất hiện ở mẫu số của divisive normalization; thường rộng và ít chọn lọc hơn receptive field của neuron.", "ch": "ch11"}, {"term": "cross-orientation suppression", "vi": "ức chế chéo hướng", "def": "Đáp ứng của neuron V1 với grating ưa thích giảm khi chồng thêm grating vuông góc mà bản thân neuron không đáp ứng.", "ch": "ch11"}, {"term": "surround suppression", "vi": "ức chế vùng bao quanh", "def": "Đáp ứng của neuron giảm khi kích thích lan ra ngoài receptive field cổ điển của nó; ở vỏ não đi kèm sự giảm của cả excitation lẫn inhibition (chữ ký ISN).", "ch": "ch11"}, {"term": "stabilized supralinear network", "vi": "mạng siêu tuyến tính được ổn định (SSN)", "def": "Mô hình của Miller và cộng sự: f–I curve siêu tuyến tính cộng kết nối E–I recurrent khiến mạng cộng gần tuyến tính với input yếu và chuẩn hoá (dưới tuyến tính) với input mạnh.", "ch": "ch11"}, {"term": "lateral inhibition", "vi": "ức chế bên", "def": "Các neuron lân cận ức chế lẫn nhau, làm nổi bật chỗ input thay đổi và khử dư thừa; phát hiện ở mắt sam Limulus (Hartline).", "ch": "ch11"}, {"term": "Mach bands", "vi": "dải Mach", "def": "Ảo giác thấy vệt tối/sáng tại chỗ một ramp độ sáng gặp vùng phẳng; hệ quả tri giác của lateral inhibition trong retina.", "ch": "ch11"}, {"term": "winner-take-all", "vi": "kẻ thắng lấy tất (WTA)", "def": "Mạch cạnh tranh qua inhibition chung trong đó chỉ unit có input mạnh nhất (hoặc k unit mạnh nhất) còn hoạt động; phiên bản động của argmax/top-k.", "ch": "ch11"}, {"term": "local field potential", "vi": "điện thế trường cục bộ (LFP)", "def": "Tín hiệu điện tần số thấp ghi được trong mô não, chủ yếu phản ánh tổng dòng synapse của hàng nghìn neuron quanh điện cực chứ không phải spike.", "ch": "ch11"}, {"term": "neural oscillation", "vi": "dao động thần kinh", "def": "Sự lên xuống nhịp nhàng của hoạt động quần thể neuron, chia theo dải tần: delta, theta, alpha, beta, gamma.", "ch": "ch11"}, {"term": "gamma oscillation", "vi": "dao động gamma", "def": "Nhịp 30–80 Hz sinh ra cục bộ từ vòng pyramidal–PV; gắn với xử lý tích cực và với chiều feedforward.", "ch": "ch11"}, {"term": "PING", "vi": "pyramidal–interneuron network gamma", "def": "Cơ chế sinh gamma: loạt spike E kích loạt spike PV, inhibition GABA-A bịt E rồi tắt dần sau ~2–3 thời hằng, mở cửa sổ cho loạt E kế tiếp.", "ch": "ch11"}, {"term": "communication through coherence", "vi": "truyền thông qua đồng pha (CTC)", "def": "Giả thuyết của Fries: hai vùng trao đổi thông tin hiệu quả khi dao động của chúng khớp pha, nên quan hệ pha có thể định tuyến luồng tin; còn tranh cãi.", "ch": "ch11"}, {"term": "traveling wave", "vi": "sóng lan", "def": "Dao động có pha thay đổi đều theo vị trí nên trông như sóng chạy trên mặt vỏ não, tốc độ 0,1–10 m/s tuỳ thang.", "ch": "ch11"}, {"term": "feedforward", "vi": "truyền xuôi", "def": "Kết nối từ vùng bậc thấp lên vùng bậc cao: xuất phát từ L2/3, kết thúc ở L4, có tính 'lái' neuron đích.", "ch": "ch11"}, {"term": "feedback", "vi": "hồi tiếp (top-down)", "def": "Kết nối từ vùng bậc cao xuống vùng bậc thấp: xuất phát từ L5/6, kết thúc ở L1 và L6, có tính điều biến hơn là lái.", "ch": "ch11"}, {"term": "dynamical system", "vi": "hệ động lực", "def": "Hệ mà trạng thái tiến hoá theo thời gian theo một quy luật xác định dx/dt = F(x); khung toán dùng để mô tả hoạt động tập thể của quần thể neuron.", "ch": "ch12"}, {"term": "state space", "vi": "không gian trạng thái", "def": "Không gian mà mỗi trục là hoạt động (firing rate) của một neuron; trạng thái của cả quần thể tại một thời điểm là một điểm trong đó.", "ch": "ch12"}, {"term": "trajectory", "vi": "quỹ đạo", "def": "Đường cong mà trạng thái quần thể vẽ ra trong state space khi thời gian trôi.", "ch": "ch12"}, {"term": "rate network", "vi": "mạng firing-rate", "def": "Mô hình mạng recurrent trong đó mỗi unit là firing rate trung bình: τ dx/dt = −x + Wφ(x) + I; tương đương một leaky RNN thời gian liên tục.", "ch": "ch12"}, {"term": "saddle point", "vi": "điểm yên ngựa", "def": "Fixed point ổn định theo một số hướng và không ổn định theo các hướng còn lại; thường đóng vai đường phân thuỷ giữa các basin, ví dụ giữa hai lựa chọn.", "ch": "ch12"}, {"term": "attractor", "vi": "tập hút", "def": "Tập trạng thái mà các quỹ đạo lân cận bị hút về và ở lại: điểm, đường, vòng, chu trình hoặc tập hỗn loạn.", "ch": "ch12"}, {"term": "basin of attraction", "vi": "lưu vực hút", "def": "Tập mọi điều kiện đầu dẫn về cùng một attractor; mọi gợi ý rơi trong basin của một ký ức đều được sửa về ký ức đó.", "ch": "ch12"}, {"term": "Lyapunov function", "vi": "hàm Lyapunov", "def": "Hàm vô hướng chỉ giảm (hoặc không tăng) dọc mọi quỹ đạo của hệ; sự tồn tại của nó đảm bảo hệ hội tụ về cực tiểu. Hàm năng lượng Hopfield là một ví dụ.", "ch": "ch12"}, {"term": "energy function", "vi": "hàm năng lượng", "def": "Đại lượng E = −½ Σ W_ij s_i s_j của mạng Hopfield; mỗi bước cập nhật làm E giảm nên hồi tưởng là lăn xuống dốc trên energy landscape.", "ch": "ch12"}, {"term": "content-addressable memory", "vi": "bộ nhớ định địa chỉ bằng nội dung", "def": "Bộ nhớ truy xuất bằng một phần nội dung (có thể nhiễu) thay vì bằng địa chỉ; còn gọi associative memory.", "ch": "ch12"}, {"term": "pattern completion", "vi": "hoàn thiện mẫu", "def": "Khôi phục toàn bộ một pattern đã lưu từ một gợi ý thiếu hoặc nhiễu; chức năng được gán cho mạng recurrent CA3 của hippocampus.", "ch": "ch12"}, {"term": "spurious state", "vi": "trạng thái giả", "def": "Cực tiểu năng lượng không ứng với pattern nào đã lưu (âm bản, hỗn hợp của số lẻ pattern, trạng thái spin-glass), sinh ra do crosstalk giữa các ký ức.", "ch": "ch12"}, {"term": "storage capacity", "vi": "dung lượng lưu trữ", "def": "Số pattern tối đa một mạng liên tưởng hồi tưởng được; với Hopfield cổ điển và pattern ngẫu nhiên là ≈ 0,138N, vượt ngưỡng thì mọi ký ức sụp đổ đồng loạt.", "ch": "ch12"}, {"term": "dense associative memory", "vi": "bộ nhớ liên tưởng dày đặc", "def": "Mở rộng của Hopfield (Krotov & Hopfield 2016) dùng hàm tương tác phi tuyến dốc hơn bình phương, cho dung lượng siêu tuyến tính đến hàm mũ; còn gọi modern Hopfield network.", "ch": "ch12"}, {"term": "modern Hopfield network", "vi": "mạng Hopfield hiện đại", "def": "Phiên bản trạng thái liên tục với năng lượng log-sum-exp (Ramsauer 2020); quy tắc cập nhật ξ ← X softmax(βXᵀξ) trùng với phép attention của transformer.", "ch": "ch12"}, {"term": "continuous attractor", "vi": "attractor liên tục", "def": "Một continuum các fixed point (đường, vòng, mặt xuyến) ổn định biên: bị hút về tập attractor nhưng trượt tự do dọc theo nó, cho phép nhớ một biến liên tục.", "ch": "ch12"}, {"term": "line attractor", "vi": "attractor đường", "def": "Dải fixed point một chiều có một eigenvalue bằng 0 dọc đường; hoạt động như bộ tích phân và bộ nhớ analog cho một số thực (vd. vị trí mắt, bằng chứng tích luỹ).", "ch": "ch12"}, {"term": "ring attractor", "vi": "attractor vòng", "def": "Continuous attractor có topology vòng tròn, sinh bởi kết nối kích thích gần–ức chế xa trên một vòng neuron; mã hoá biến góc như hướng đầu.", "ch": "ch12"}, {"term": "bump attractor", "vi": "attractor dạng bump", "def": "Một đốm hoạt động cục bộ tự duy trì trên một mạng có kết nối kiểu Mexican hat; vị trí của bump là biến được nhớ (hướng đầu, vị trí trong working memory).", "ch": "ch12"}, {"term": "head-direction cell", "vi": "tế bào hướng đầu", "def": "Neuron phát spike mạnh khi đầu con vật hướng về một phương nhất định trong môi trường, độc lập với vị trí; vẫn hoạt động trong bóng tối nhờ tích phân vận tốc quay.", "ch": "ch12"}, {"term": "path integration", "vi": "tích phân đường đi", "def": "Cập nhật ước lượng vị trí hay hướng bằng cách cộng dồn tín hiệu vận tốc của chính mình, không cần mốc bên ngoài; sai số tích luỹ theo thời gian.", "ch": "ch12"}, {"term": "neural integrator", "vi": "bộ tích phân thần kinh", "def": "Mạch biến tín hiệu thoáng qua thành hoạt động dai dẳng tỉ lệ với tích phân theo thời gian của input; ví dụ kinh điển là oculomotor integrator giữ vị trí mắt.", "ch": "ch12"}, {"term": "chaos", "vi": "hỗn loạn tất định", "def": "Dynamics tất định, bị chặn, không tuần hoàn và nhạy theo hàm mũ với điều kiện đầu; xuất hiện trong mạng recurrent ngẫu nhiên khi gain g > 1.", "ch": "ch12"}, {"term": "Lyapunov exponent", "vi": "số mũ Lyapunov", "def": "Tốc độ tách (hoặc hội tụ) theo hàm mũ của hai quỹ đạo gần nhau; số mũ lớn nhất dương là định nghĩa của chaos.", "ch": "ch12"}, {"term": "dimensionality reduction", "vi": "giảm chiều", "def": "Các phương pháp (PCA, factor analysis, GPFA, dPCA, jPCA, LFADS…) tìm một biểu diễn ít chiều của hoạt động nhiều neuron.", "ch": "ch12"}, {"term": "participation ratio", "vi": "tỉ số tham gia", "def": "Thước đo số chiều hiệu dụng của dữ liệu: (Σλ)² / Σλ², với λ là các eigenvalue của ma trận hiệp phương sai.", "ch": "ch12"}, {"term": "jPCA", "vi": "jPCA", "def": "Phương pháp giảm chiều tìm mặt phẳng trong đó dynamics quần thể được khớp tốt nhất bởi một hệ tuyến tính thuần xoay (Churchland 2012).", "ch": "ch12"}, {"term": "rotational dynamics", "vi": "dynamics xoay", "def": "Hiện tượng quỹ đạo quần thể ở motor cortex xoay cùng chiều, cùng tần số trong lúc với tay, với pha và biên độ do trạng thái chuẩn bị quy định.", "ch": "ch12"}, {"term": "output-null space", "vi": "không gian output-null", "def": "Các chiều của hoạt động quần thể nằm trong null space của ánh xạ readout xuống cơ; hoạt động chuẩn bị diễn ra ở đó nên không gây cử động.", "ch": "ch12"}, {"term": "slow point", "vi": "điểm chậm", "def": "Vùng của state space nơi tốc độ |F(x)| rất nhỏ nhưng khác 0; trong thang thời gian của task nó hành xử như một fixed point xấp xỉ.", "ch": "ch12"}, {"term": "reservoir computing", "vi": "tính toán bằng hồ chứa", "def": "Dùng một mạng recurrent ngẫu nhiên cố định làm bộ chiếu phi tuyến giàu của lịch sử input và chỉ huấn luyện readout tuyến tính; gồm echo state network và liquid state machine.", "ch": "ch12"}, {"term": "edge of chaos", "vi": "bờ vực hỗn loạn", "def": "Vùng tham số sát chuyển pha trật tự–hỗn loạn (g ≈ 1), nơi mạng có bộ nhớ dài nhất và tín hiệu/gradient lan truyền tốt nhất.", "ch": "ch12"}, {"term": "criticality", "vi": "tính tới hạn", "def": "Giả thuyết rằng não tự tổ chức quanh một điểm chuyển pha (branching ratio ≈ 1), nơi dải động và dung lượng thông tin cực đại; còn đang tranh cãi.", "ch": "ch12"}, {"term": "neuronal avalanche", "vi": "thác neuron", "def": "Chuỗi hoạt động lan truyền liên tiếp kẹp giữa hai khoảng im lặng; phân bố kích thước theo luật luỹ thừa số mũ −3/2 (Beggs & Plenz 2003).", "ch": "ch12"}, {"term": "genomic bottleneck", "vi": "nút cổ chai genome", "def": "Lập luận của Zador: genome (~0,8 GB) nhỏ hơn connectome nhiều bậc độ lớn nên chỉ có thể di truyền quy tắc sinh ra mạng (kiến trúc, quy tắc đi dây, luật học), không phải từng trọng số; cái cổ chai này hoạt động như một regularizer.", "ch": "ch13"}, {"term": "rostral", "vi": "phía mỏ (trước)", "def": "Hướng về phía trước của trục thần kinh; ở đại não người là phía trán.", "ch": "ch13"}, {"term": "caudal", "vi": "phía đuôi (sau)", "def": "Hướng về phía đuôi của trục thần kinh; ở đại não người là phía gáy, ở thân não là phía tuỷ sống.", "ch": "ch13"}, {"term": "dorsal", "vi": "phía lưng", "def": "Hướng về phía lưng của trục thần kinh: ở đại não người là phía đỉnh đầu, ở tuỷ sống là phía sau lưng (vì trục gập ~90° ở midbrain).", "ch": "ch13"}, {"term": "ventral", "vi": "phía bụng", "def": "Ngược với dorsal: ở đại não người là phía đáy sọ; 'ventral stream' của thị giác chạy xuống thuỳ thái dương.", "ch": "ch13"}, {"term": "gray matter", "vi": "chất xám", "def": "Mô thần kinh chứa soma, dendrite và synapse — nơi diễn ra tính toán; tồn tại dạng tấm (cortex) hoặc cục (nucleus).", "ch": "ch13"}, {"term": "white matter", "vi": "chất trắng", "def": "Các bó axon bọc myelin nối các vùng gray matter; chiếm khoảng 40% thể tích đại não người và tăng nhanh hơn gray matter khi não to lên.", "ch": "ch13"}, {"term": "cortex", "vi": "vỏ (não)", "def": "Gray matter tổ chức thành tấm phân lớp phủ bề mặt: neocortex 6 lớp, hippocampus 3 lớp, vỏ cerebellum 3 lớp.", "ch": "ch13"}, {"term": "nucleus", "vi": "nhân (thần kinh)", "def": "Một cụm thân neuron nằm sâu trong não có chung kết nối và chức năng (khác nhân tế bào); ví dụ LGN, nhân raphe.", "ch": "ch13"}, {"term": "contralateral", "vi": "đối bên", "def": "Ở phía bên kia của cơ thể; phần lớn đường cảm giác và vận động bắt chéo nên mỗi bán cầu phụ trách nửa người đối bên.", "ch": "ch13"}, {"term": "neural tube", "vi": "ống thần kinh", "def": "Cấu trúc hình ống hình thành ở tuần 3–4 của phôi khi tấm thần kinh cuộn lại; thành ống phát triển thành toàn bộ não và tuỷ sống, lòng ống thành hệ não thất.", "ch": "ch13"}, {"term": "forebrain", "vi": "não trước", "def": "Túi phồng trước nhất của ống thần kinh (prosencephalon), sinh ra telencephalon (neocortex, hippocampus, amygdala, basal ganglia) và diencephalon (thalamus, hypothalamus, võng mạc).", "ch": "ch13"}, {"term": "midbrain", "vi": "não giữa", "def": "Khoang giữa (mesencephalon): superior/inferior colliculus, VTA và substantia nigra — nguồn dopamine chính.", "ch": "ch13"}, {"term": "hindbrain", "vi": "não sau", "def": "Khoang sau (rhombencephalon) gồm pons, cerebellum và medulla.", "ch": "ch13"}, {"term": "brainstem", "vi": "thân não", "def": "Midbrain + pons + medulla: điều khiển hô hấp, tim mạch, phản xạ, thức–ngủ; chứa các nhân neuromodulator và là cổ chai của mọi đường nối não–cơ thể.", "ch": "ch13"}, {"term": "hypothalamus", "vi": "vùng dưới đồi", "def": "Cấu trúc ~4 g giữ các setpoint nội môi (nhiệt, đói, khát, hormone, nhịp ngày đêm) và biến sai lệch thành drive hành vi; điều khiển tuyến yên.", "ch": "ch13"}, {"term": "thalamus", "vi": "đồi thị", "def": "Khối nhân ở trung tâm não, cổng vào của neocortex cho mọi giác quan trừ khứu giác và trạm trên các đường cortex–cortex; hoạt động như bảng chuyển mạch có điều khiển hơn là trạm lặp.", "ch": "ch13"}, {"term": "thalamic reticular nucleus", "vi": "nhân lưới đồi thị (TRN)", "def": "Lớp vỏ mỏng toàn neuron GABA bọc quanh thalamus; nhận nhánh bên của mọi sợi thalamus↔cortex và ức chế chọn lọc các relay neuron, đóng mở từng kênh.", "ch": "ch13"}, {"term": "basal ganglia", "vi": "hạch nền", "def": "Nhóm nhân dưới vỏ (striatum, globus pallidus, subthalamic nucleus, substantia nigra) tạo vòng lặp cortex→BG→thalamus→cortex; chọn hành động bằng cách nhả ức chế và học theo dopamine.", "ch": "ch13"}, {"term": "amygdala", "vi": "hạch hạnh nhân", "def": "Cụm ~13 nhân ở thuỳ thái dương trước; học liên kết kích thích với hệ quả có ý nghĩa sinh tồn (fear conditioning) và gắn nhãn giá trị cho biểu diễn giác quan.", "ch": "ch13"}, {"term": "cytoarchitecture", "vi": "kiến trúc tế bào", "def": "Kiểu sắp xếp, mật độ và kích thước tế bào qua các lớp vỏ não; tiêu chí Brodmann dùng để chia vùng.", "ch": "ch13"}, {"term": "Brodmann area", "vi": "vùng Brodmann", "def": "Vùng vỏ não được Brodmann (1909) phân định theo cytoarchitecture và đánh số 1–52; ví dụ vùng 17 = V1, vùng 4 = M1.", "ch": "ch13"}, {"term": "association cortex", "vi": "vỏ liên hợp", "def": "Phần neocortex nằm ngoài các vùng sensory và motor sơ cấp (khoảng 3/4 ở người); tích hợp nhiều nguồn, thang thời gian dài, trưởng thành muộn.", "ch": "ch13"}, {"term": "default-mode network", "vi": "mạng mặc định", "def": "Nhóm vùng association (PFC mặt trong, cingulate sau, angular gyrus) hoạt động mạnh khi không làm tác vụ hướng ngoại; nằm ở đầu xa nhất của gradient sensory→association.", "ch": "ch13"}, {"term": "corpus callosum", "vi": "thể chai", "def": "Bó sợi commissural lớn nhất não, ~200 triệu axon nối hai bán cầu.", "ch": "ch13"}, {"term": "split-brain", "vi": "não tách đôi", "def": "Tình trạng sau phẫu thuật cắt corpus callosum: mỗi bán cầu xử lý thông tin riêng, lộ ra khi đưa kích thích khác nhau cho từng nửa thị trường.", "ch": "ch13"}, {"term": "lateralization", "vi": "sự phân bên chức năng", "def": "Việc một số chức năng dựa nhiều hơn vào một bán cầu, ví dụ ngôn ngữ ở bán cầu trái ở ~95% người thuận tay phải.", "ch": "ch13"}, {"term": "small-world network", "vi": "mạng thế giới nhỏ", "def": "Mạng có clustering cao như mạng đều nhưng path length ngắn như mạng ngẫu nhiên nhờ một số ít kết nối dài (Watts & Strogatz 1998).", "ch": "ch13"}, {"term": "rich club", "vi": "câu lạc bộ nhà giàu", "def": "Hiện tượng các hub bậc cao nối với nhau dày hơn mức ngẫu nhiên, tạo xương sống cho liên lạc toàn cục; đắt và dễ tổn thương.", "ch": "ch13"}, {"term": "radial glia", "vi": "tế bào đệm hướng tâm", "def": "Tế bào gốc thần kinh có sợi vươn từ lòng ống thần kinh ra bề mặt não; vừa sinh neuron vừa làm dây leo cho neuron non di cư.", "ch": "ch13"}, {"term": "growth cone", "vi": "nón tăng trưởng", "def": "Đầu mút di động của axon đang mọc, dò các tín hiệu hút/đẩy (netrin, Slit, semaphorin, ephrin) để tìm đường tới đích.", "ch": "ch13"}, {"term": "chemoaffinity hypothesis", "vi": "giả thuyết ái lực hoá học", "def": "Đề xuất của Sperry (1963): axon tìm đích nhờ nhãn phân tử khớp nhau, và vài gradient nồng độ là đủ mã hoá một bản đồ; được xác nhận bởi hệ Eph/ephrin.", "ch": "ch13"}, {"term": "retinal waves", "vi": "sóng võng mạc", "def": "Các đợt hoạt động tự phát lan qua võng mạc trước khi mắt nhìn được; tương quan không gian của chúng cho luật Hebb dữ liệu để làm nét bản đồ retinotopic và tách input hai mắt.", "ch": "ch13"}, {"term": "myelination", "vi": "myelin hoá", "def": "Quá trình oligodendrocyte quấn myelin quanh axon; diễn ra từ cuối thai kỳ tới khoảng 30 tuổi, vùng sensory–motor trước, PFC sau cùng; tăng tốc độ dẫn nhưng hạn chế tính dẻo.", "ch": "ch13"}, {"term": "retina", "vi": "võng mạc", "def": "Lớp mô thần kinh dày ~0,25 mm ở đáy mắt, về mặt phôi thai là một phần của não; chuyển ánh sáng thành tín hiệu thần kinh và tiền xử lý (trừ nền, chuẩn hoá, nén) trước khi gửi về não.", "ch": "ch14"}, {"term": "photoreceptor", "vi": "tế bào cảm quang", "def": "Tế bào ở retina hấp thụ photon và đổi thành tín hiệu điện graded; tăng phân cực và nhả ít glutamate hơn khi có ánh sáng. Gồm rod và cone.", "ch": "ch14"}, {"term": "rod", "vi": "tế bào que", "def": "Photoreceptor cực nhạy (phản ứng được với một photon), lo thị giác ban đêm, không phân biệt màu; ~90–120 triệu ở mắt người, vắng mặt ở fovea.", "ch": "ch14"}, {"term": "cone", "vi": "tế bào nón", "def": "Photoreceptor cho thị giác ban ngày và màu sắc, ba loại S/M/L; ~5–6 triệu ở mắt người, tập trung dày đặc ở fovea.", "ch": "ch14"}, {"term": "fovea", "vi": "hố trung tâm", "def": "Vùng trung tâm retina rộng ~1–2° thị giác, mật độ cone cao nhất và thị lực sắc nhất; mắt liên tục saccade để đưa fovea tới chỗ cần xem.", "ch": "ch14"}, {"term": "bipolar cell", "vi": "tế bào lưỡng cực", "def": "Neuron trung gian của retina nối photoreceptor với ganglion cell, tính toán bằng điện thế graded; loại ON và OFF đáp ứng trái dấu với cùng glutamate nhờ receptor khác nhau (mGluR6 vs AMPA/kainate).", "ch": "ch14"}, {"term": "horizontal cell", "vi": "tế bào ngang", "def": "Interneuron ức chế ở tầng synapse ngoài của retina, gom tín hiệu nhiều photoreceptor trên vùng rộng rồi ức chế ngược, tạo vùng bao (surround) của receptive field.", "ch": "ch14"}, {"term": "amacrine cell", "vi": "tế bào amacrine", "def": "Họ interneuron đa dạng (hàng chục loại) ở tầng synapse trong của retina, điều biến tín hiệu bipolar → ganglion, tham gia các phép tính theo thời gian và chuyển động.", "ch": "ch14"}, {"term": "retinal ganglion cell", "vi": "tế bào hạch võng mạc (RGC)", "def": "Neuron đầu ra của retina và là neuron đầu tiên trong đường thị giác phát spike; ~1 triệu axon của chúng tạo thành optic nerve. Có ~20 loại song song ở linh trưởng (midget, parasol…).", "ch": "ch14"}, {"term": "center-surround", "vi": "tâm – vùng bao", "def": "Cấu trúc RF đồng tâm của RGC và neuron LGN: vùng tâm và vành bao quanh đáp ứng trái dấu (ON-center hoặc OFF-center), khiến tế bào đo độ tương phản cục bộ thay vì độ sáng tuyệt đối.", "ch": "ch14"}, {"term": "difference of Gaussians", "vi": "hiệu hai hàm Gauss (DoG)", "def": "Mô hình toán của RF center-surround: một Gauss hẹp (tâm) trừ một Gauss rộng (vùng bao); là bộ lọc band-pass xấp xỉ Laplacian-of-Gaussian và xấp xỉ bộ lọc whitening cho ảnh tự nhiên.", "ch": "ch14"}, {"term": "optic chiasm", "vi": "giao thoa thị giác", "def": "Nơi các sợi từ nửa retina phía mũi của hai mắt bắt chéo, sao cho mỗi bán cầu não nhận nửa thị trường đối bên từ cả hai mắt.", "ch": "ch14"}, {"term": "LGN", "vi": "nhân gối ngoài", "def": "Lateral geniculate nucleus: nhân của thalamus nhận ~90% axon RGC và chuyển tiếp tới V1; sáu lớp (magno-, parvo-, xen kẽ koniocellular); phần lớn synapse đến lại là feedback từ vỏ não và tín hiệu điều biến.", "ch": "ch14"}, {"term": "V1", "vi": "vỏ não thị giác sơ cấp", "def": "Primary visual cortex (striate cortex, Brodmann 17) ở thuỳ chẩm; trạm vỏ não đầu tiên của thị giác, nơi xuất hiện chọn lọc hướng, tổ chức retinotopic và các cột định hướng/ưu thế mắt.", "ch": "ch14"}, {"term": "retinotopy", "vi": "bản đồ võng mạc", "def": "Tổ chức không gian trong đó các điểm lân cận của thị trường được biểu diễn bởi các neuron lân cận trên vỏ não (hay LGN, colliculus).", "ch": "ch14"}, {"term": "cortical magnification", "vi": "độ phóng đại vỏ não", "def": "Số mm vỏ não dành cho mỗi độ thị giác; giảm gần như hyperbol theo độ lệch tâm (M ≈ 17,3/(E+0,75) mm/độ ở V1 người), khiến fovea chiếm phần V1 lớn không tương xứng.", "ch": "ch14"}, {"term": "orientation selectivity", "vi": "tính chọn lọc hướng", "def": "Tính chất neuron đáp ứng mạnh nhất với cạnh/vạch ở một góc nghiêng nhất định và yếu dần khi lệch khỏi góc đó; xuất hiện lần đầu ở V1.", "ch": "ch14"}, {"term": "energy model", "vi": "mô hình năng lượng", "def": "Mô hình complex cell của Adelson & Bergen (1985): tổng bình phương đầu ra hai bộ lọc Gabor lệch pha 90°, cho đáp ứng bất biến với pha.", "ch": "ch14"}, {"term": "orientation column", "vi": "cột định hướng", "def": "Cột neuron xuyên qua các lớp V1 có cùng hướng ưa thích; hướng thay đổi trơn dọc bề mặt vỏ não, xoáy quanh các điểm pinwheel. Có ở mèo và linh trưởng, không có ở chuột.", "ch": "ch14"}, {"term": "ocular dominance column", "vi": "cột ưu thế mắt", "def": "Các dải vỏ não V1 rộng ~0,5 mm xen kẽ, nhận đầu vào chủ yếu từ mắt trái hoặc mắt phải.", "ch": "ch14"}, {"term": "hypercolumn", "vi": "siêu cột", "def": "Khối vỏ não V1 ~1 mm² chứa đủ mọi hướng ưa thích cho cả hai mắt — bộ máy hoàn chỉnh để phân tích một điểm của thị trường.", "ch": "ch14"}, {"term": "ventral stream", "vi": "dòng bụng", "def": "Đường xử lý V1 → V2 → V4 → inferior temporal cortex, phục vụ nhận dạng vật thể (\"what\"); RF lớn dần, đặc trưng phức tạp dần, bất biến tăng dần.", "ch": "ch14"}, {"term": "dorsal stream", "vi": "dòng lưng", "def": "Đường xử lý V1 → V2 → MT → thuỳ đỉnh, phục vụ không gian, chuyển động và dẫn đường thị giác cho hành động (\"where/how\").", "ch": "ch14"}, {"term": "inferior temporal cortex", "vi": "vỏ thái dương dưới (IT)", "def": "Trạm cuối của ventral stream; neuron có RF lớn, chọn lọc với vật thể phức tạp (mặt, cơ thể, đồ vật) và khá bất biến với vị trí, kích cỡ; biểu diễn ở đây tách tuyến tính được theo danh tính vật thể.", "ch": "ch14"}, {"term": "untangling", "vi": "gỡ rối đa tạp", "def": "Khung lý thuyết của DiCarlo & Cox: ventral stream biến đổi dần biểu diễn sao cho các đa tạp của từng vật thể (tập mọi ảnh của vật dưới các phép biến đổi) trở nên phẳng và tách tuyến tính được.", "ch": "ch14"}, {"term": "face patch", "vi": "mảng mặt", "def": "Các vùng nhỏ trong vỏ thái dương linh trưởng (sáu mảng mỗi bên ở macaque) mà hầu hết neuron chọn lọc với khuôn mặt, nối với nhau thành một mạng; mã danh tính khuôn mặt bằng axis code gần tuyến tính.", "ch": "ch14"}, {"term": "feedforward sweep", "vi": "lượt quét feedforward", "def": "Làn sóng hoạt động đầu tiên lan từ retina lên IT trong ~100 ms sau khi ảnh xuất hiện, mỗi neuron góp 0–2 spike; đủ cho nhận dạng vật thể lõi trước khi recurrence và feedback kịp tác động.", "ch": "ch14"}, {"term": "Brain-Score", "vi": "Brain-Score", "def": "Bộ benchmark mở chấm điểm các mô hình ANN theo khả năng dự đoán đáp ứng neuron ở V1/V2/V4/IT và hành vi nhận dạng của linh trưởng.", "ch": "ch14"}, {"term": "saccade", "vi": "chuyển động liếc mắt", "def": "Cú nhảy mắt nhanh (20–80 ms, tới ~900°/s), 3–4 lần mỗi giây, đưa fovea tới điểm nhìn mới; xen giữa là các fixation 200–300 ms.", "ch": "ch14"}, {"term": "noise ceiling", "vi": "trần nhiễu", "def": "Mức dự đoán tối đa có thể đạt với một neuron do tính biến thiên giữa các lần lặp; điểm của mô hình thường được chia cho giá trị này.", "ch": "ch14"}, {"term": "cochlea", "vi": "ốc tai", "def": "Ống xương xoắn chứa dịch ở tai trong, nơi rung động âm thanh được phân tích theo tần số dọc basilar membrane và chuyển thành tín hiệu thần kinh.", "ch": "ch15"}, {"term": "basilar membrane", "vi": "màng đáy", "def": "Dải màng đàn hồi dài ~35 mm trong cochlea, hẹp và cứng ở base, rộng và mềm ở apex; mỗi vị trí cộng hưởng với một tần số riêng.", "ch": "ch15"}, {"term": "tonotopy", "vi": "bản đồ tần số", "def": "Cách tổ chức trong đó tần số âm được sắp theo vị trí, từ cochlea qua các trạm brainstem tới vỏ não thính giác.", "ch": "ch15"}, {"term": "characteristic frequency", "vi": "tần số đặc trưng", "def": "Tần số mà một vị trí trên basilar membrane, một sợi thần kinh hay một neuron thính giác nhạy nhất (ngưỡng thấp nhất).", "ch": "ch15"}, {"term": "gammatone", "vi": "bộ lọc gammatone", "def": "Hàm đáp ứng xung dạng t^(n-1)·e^(-bt)·cos(2πft), xấp xỉ tốt bộ lọc thông dải của một điểm trên cochlea; dùng phổ biến trong mô hình thính giác.", "ch": "ch15"}, {"term": "hair cell", "vi": "tế bào lông", "def": "Tế bào cảm giác của tai trong và hệ tiền đình, có bó stereocilia trên đỉnh; biến độ lệch cơ học cỡ nanomet thành thay đổi điện thế.", "ch": "ch15"}, {"term": "inner hair cell", "vi": "tế bào lông trong", "def": "Hàng hair cell (~3.500 mỗi tai) đảm nhiệm việc gửi tín hiệu âm thanh lên não; nối với ~95% sợi thần kinh thính giác hướng tâm.", "ch": "ch15"}, {"term": "outer hair cell", "vi": "tế bào lông ngoài", "def": "Ba hàng hair cell (~12.000 mỗi tai) co giãn theo điện thế nhờ protein prestin, bơm năng lượng vào sóng chạy để khuếch đại và làm nhọn đáp ứng tần số.", "ch": "ch15"}, {"term": "tip link", "vi": "dây nối đỉnh", "def": "Sợi protein mảnh nối đỉnh một stereocilium với sườn stereocilium cao hơn bên cạnh; khi căng, nó kéo mở trực tiếp kênh ion chuyển đổi cơ–điện.", "ch": "ch15"}, {"term": "cochlear amplifier", "vi": "bộ khuếch đại ốc tai", "def": "Cơ chế hồi tiếp dương chủ động do outer hair cell tạo ra, tăng độ nhạy 40–60 dB với âm nhỏ và nén dải động của âm lớn.", "ch": "ch15"}, {"term": "phase locking", "vi": "khoá pha", "def": "Hiện tượng spike của sợi thần kinh thính giác dồn vào một pha cố định của sóng âm, giữ lại thông tin thời gian tinh; tốt tới ~1–2 kHz, mất dần trên 4–5 kHz ở thú có vú.", "ch": "ch15"}, {"term": "interaural time difference", "vi": "chênh lệch thời gian giữa hai tai (ITD)", "def": "Khoảng thời gian âm tới tai này sớm hơn tai kia, tối đa ~650 µs ở người; manh mối chính để định vị nguồn âm tần số thấp.", "ch": "ch15"}, {"term": "interaural level difference", "vi": "chênh lệch cường độ giữa hai tai (ILD)", "def": "Độ chênh mức âm giữa hai tai do đầu che chắn, đáng kể ở tần số cao (trên ~1,5 kHz); được tính ở lateral superior olive.", "ch": "ch15"}, {"term": "delay line", "vi": "đường trễ", "def": "Axon có chiều dài (hoặc tốc độ dẫn) thay đổi có hệ thống, tạo ra các độ trễ dẫn truyền khác nhau; thành phần của mạch Jeffress.", "ch": "ch15"}, {"term": "coincidence detector", "vi": "bộ dò trùng hợp", "def": "Neuron chỉ bắn mạnh khi các đầu vào tới gần như đồng thời; ở MSO và nucleus laminaris, cửa sổ trùng hợp hẹp tới dưới một mili giây.", "ch": "ch15"}, {"term": "spectro-temporal receptive field", "vi": "receptive field phổ–thời gian (STRF)", "def": "Kernel trên mặt phẳng tần số × thời gian mô tả mẫu spectrogram nào làm một neuron thính giác bắn mạnh nhất; tương tự một kernel conv2D.", "ch": "ch15"}, {"term": "cocktail party problem", "vi": "bài toán bữa tiệc cocktail", "def": "Bài toán tách và theo dõi một nguồn âm (một giọng nói) giữa nhiều nguồn chồng lấn; do Colin Cherry nêu năm 1953.", "ch": "ch15"}, {"term": "somatosensory system", "vi": "hệ cảm giác thân thể", "def": "Hệ thống cảm nhận xúc giác, tư thế (proprioception), nhiệt và đau từ da, cơ, khớp và nội tạng.", "ch": "ch15"}, {"term": "mechanoreceptor", "vi": "thụ thể cơ học", "def": "Tận cùng thần kinh chuyển biến dạng cơ học thành spike; ở da không lông gồm bốn kiểu sợi SA1 (Merkel), RA1 (Meissner), SA2 (Ruffini) và PC (Pacinian).", "ch": "ch15"}, {"term": "Piezo2", "vi": "kênh Piezo2", "def": "Kênh ion mở bằng lực căng màng, là bộ chuyển đổi chính của xúc giác nhẹ và proprioception; phát hiện năm 2010 (Patapoutian, Nobel 2021).", "ch": "ch15"}, {"term": "adaptation", "vi": "thích nghi", "def": "Sự giảm đáp ứng của receptor hay neuron khi kích thích giữ nguyên, khiến hệ cảm giác nhấn mạnh thay đổi hơn là giá trị tuyệt đối.", "ch": "ch15"}, {"term": "barrel cortex", "vi": "vỏ não barrel", "def": "Phần S1 của loài gặm nhấm, nơi mỗi sợi ria mép ứng với một cụm neuron riêng (barrel) ở lớp 4; hệ mẫu để nghiên cứu vi mạch vỏ não.", "ch": "ch15"}, {"term": "homunculus", "vi": "người tí hon (bản đồ cơ thể)", "def": "Bản đồ có thứ tự của bề mặt cơ thể trên vỏ não cảm giác (và vận động), méo theo mật độ receptor: tay và môi rất lớn, thân và chân nhỏ.", "ch": "ch15"}, {"term": "nociceptor", "vi": "thụ thể tổn thương", "def": "Neuron cảm giác ngưỡng cao với tận cùng thần kinh trần (sợi Aδ và C), bắn khi kích thích đe doạ tổn thương mô; tín hiệu của nó chưa phải là 'đau'.", "ch": "ch15"}, {"term": "gate control theory", "vi": "thuyết cổng kiểm soát", "def": "Đề xuất của Melzack và Wall (1965): tín hiệu đau bị điều biến ngay ở sừng sau tuỷ sống bởi đầu vào xúc giác và bởi đường đi xuống từ não.", "ch": "ch15"}, {"term": "odorant receptor", "vi": "thụ thể mùi", "def": "Họ GPCR lớn (~400 gene hoạt động ở người, ~1.100 ở chuột) trên olfactory sensory neuron; mỗi neuron chỉ biểu hiện một loại.", "ch": "ch15"}, {"term": "glomerulus", "vi": "tiểu cầu khứu", "def": "Cấu trúc hình cầu ở olfactory bulb (hay antennal lobe của côn trùng) nơi axon của mọi receptor neuron cùng loại hội tụ; số nhiều: glomeruli.", "ch": "ch15"}, {"term": "combinatorial code", "vi": "mã tổ hợp", "def": "Cách mã hoá trong đó danh tính kích thích nằm ở tổ hợp các bộ dò được kích hoạt, mỗi bộ dò đáp ứng với nhiều kích thích.", "ch": "ch15"}, {"term": "piriform cortex", "vi": "vỏ não piriform", "def": "Vỏ khứu giác sơ cấp ba lớp, nhận đầu vào trực tiếp từ olfactory bulb không qua thalamus; biểu diễn mùi bằng tập neuron thưa, rải rác, không có bản đồ.", "ch": "ch15"}, {"term": "mushroom body", "vi": "thể nấm", "def": "Trung tâm học liên kết của não côn trùng; ở ruồi giấm gồm ~2.000 Kenyon cell mỗi bên nhận đầu vào khứu giác gần như ngẫu nhiên.", "ch": "ch15"}, {"term": "Kenyon cell", "vi": "tế bào Kenyon", "def": "Neuron nội tại của mushroom body; mỗi tế bào lấy mẫu ~6–7 projection neuron và chỉ vài phần trăm bắn với mỗi mùi nhờ ức chế toàn cục của neuron APL.", "ch": "ch15"}, {"term": "locality-sensitive hashing", "vi": "băm nhạy vị trí (LSH)", "def": "Họ hàm băm gán mã giống nhau cho các input gần nhau, dùng cho tìm kiếm láng giềng gần; mạch khứu giác ruồi thực hiện một biến thể nở rộng và thưa (FlyHash).", "ch": "ch15"}, {"term": "labeled line", "vi": "đường dây gắn nhãn", "def": "Kiểu mã trong đó mỗi chất lượng cảm giác có kênh tế bào riêng, và ý nghĩa do đường dây quyết định chứ không do kích thích; điển hình ở vị giác.", "ch": "ch15"}, {"term": "cue combination", "vi": "kết hợp manh mối", "def": "Việc hợp nhất nhiều ước lượng cảm giác về cùng một đại lượng; lời giải tối ưu là trung bình với trọng số tỉ lệ nghịch phương sai.", "ch": "ch15"}, {"term": "inverse effectiveness", "vi": "hiệu quả nghịch đảo", "def": "Luật ở neuron đa giác quan: lợi ích tương đối của việc gộp các giác quan lớn nhất khi từng tín hiệu riêng lẻ yếu nhất.", "ch": "ch15"}, {"term": "motor unit", "vi": "đơn vị vận động", "def": "Một motor neuron alpha cùng toàn bộ các sợi cơ nó chi phối; lượng tử nhỏ nhất của lực mà hệ thần kinh điều khiển được.", "ch": "ch16"}, {"term": "motor neuron", "vi": "neuron vận động", "def": "Neuron ở sừng trước tuỷ sống hoặc brainstem gửi sợi trục tới cơ; là 'con đường chung cuối cùng' của mọi hành vi.", "ch": "ch16"}, {"term": "size principle", "vi": "nguyên lý kích thước", "def": "Quy luật Henneman: khi lệnh chung tăng, motor neuron nhỏ (điện trở vào lớn, ít sợi cơ) được gọi trước, neuron lớn sau; cho độ phân giải lực kiểu logarit.", "ch": "ch16"}, {"term": "muscle spindle", "vi": "thoi cơ", "def": "Cảm biến nằm song song với sợi cơ, đo chiều dài và tốc độ giãn của cơ, gửi tín hiệu qua sợi Ia; độ nhạy do motor neuron gamma điều chỉnh.", "ch": "ch16"}, {"term": "stretch reflex", "vi": "phản xạ kéo giãn", "def": "Vòng feedback một synapse: cơ bị giãn → sợi Ia → motor neuron của chính cơ đó → cơ co lại; trễ khoảng 25–40 ms ở người.", "ch": "ch16"}, {"term": "muscle synergy", "vi": "hiệp đồng cơ", "def": "Một mẫu phối hợp hoạt động cố định của nhiều cơ, được coi như vector cơ sở mà hệ thần kinh tổ hợp để tạo cử động, giảm số chiều điều khiển.", "ch": "ch16"}, {"term": "central pattern generator", "vi": "bộ phát mẫu trung ương (CPG)", "def": "Mạch neuron (thường ở tuỷ sống hay brainstem) sinh ra output có nhịp như bước đi, bơi, thở mà không cần input có nhịp hay feedback cảm giác.", "ch": "ch16"}, {"term": "half-center oscillator", "vi": "bộ dao động hai nửa trung tâm", "def": "Mô hình CPG của Graham Brown: hai quần thể ức chế lẫn nhau cộng với một quá trình mỏi chậm, tạo hoạt động luân phiên gập–duỗi.", "ch": "ch16"}, {"term": "degrees-of-freedom problem", "vi": "bài toán bậc tự do", "def": "Vấn đề Bernstein nêu: cơ thể có nhiều khớp và cơ hơn số chiều của tác vụ, nên có vô số cách thực hiện cùng một cử động; hệ thần kinh chọn theo tiêu chí nào?", "ch": "ch16"}, {"term": "primary motor cortex", "vi": "vỏ vận động sơ cấp (M1)", "def": "Vùng vỏ não trước rãnh trung tâm, nguồn chính của bó vỏ–tuỷ; có bản đồ cơ thể thô và hoạt động như một hệ động lực phát lệnh vận động theo thời gian.", "ch": "ch16"}, {"term": "corticospinal tract", "vi": "bó vỏ–tuỷ", "def": "Bó khoảng một triệu sợi trục từ vỏ não (chủ yếu M1) xuống tuỷ sống, bắt chéo ở hành não; ở linh trưởng một phần nối thẳng lên motor neuron của bàn tay.", "ch": "ch16"}, {"term": "signal-dependent noise", "vi": "nhiễu phụ thuộc tín hiệu", "def": "Nhiễu vận động có độ lệch chuẩn tỉ lệ với độ lớn của lệnh; nguồn gốc của đánh đổi tốc độ–chính xác và của độ trơn cử động theo Harris & Wolpert.", "ch": "ch16"}, {"term": "Fitts's law", "vi": "định luật Fitts", "def": "Thời gian cử động tới đích tăng tuyến tính theo log2(2D/W), với D là khoảng cách và W là bề rộng đích.", "ch": "ch16"}, {"term": "optimal feedback control", "vi": "điều khiển feedback tối ưu (OFC)", "def": "Lý thuyết cho rằng hệ vận động chọn luật feedback tối thiểu hoá sai số tác vụ cộng nỗ lực; hệ quả là nguyên lý minimal intervention: chỉ sửa độ lệch làm hỏng mục tiêu.", "ch": "ch16"}, {"term": "minimal intervention principle", "vi": "nguyên lý can thiệp tối thiểu", "def": "Hệ quả của OFC: độ lệch trong các chiều không ảnh hưởng tới tác vụ được để mặc, nên biến thiên dồn vào các chiều dư thừa (uncontrolled manifold).", "ch": "ch16"}, {"term": "efference copy", "vi": "bản sao lệnh vận động", "def": "Bản sao của lệnh vận động gửi ngược về các mạch cảm giác/dự đoán để tiên đoán hậu quả cảm giác của chính cử động ấy; còn gọi corollary discharge.", "ch": "ch16"}, {"term": "forward model", "vi": "mô hình xuôi", "def": "Mô hình nội tại dự đoán trạng thái và cảm giác kế tiếp từ trạng thái hiện tại và lệnh vận động; dùng để bù trễ, triệt tiêu cảm giác tự gây ra, và tập dượt offline.", "ch": "ch16"}, {"term": "inverse model", "vi": "mô hình ngược", "def": "Ánh xạ từ trạng thái mong muốn sang lệnh vận động cần phát; tương ứng với policy/controller.", "ch": "ch16"}, {"term": "sensory prediction error", "vi": "sai số dự đoán cảm giác", "def": "Hiệu giữa cảm giác thật và cảm giác do forward model dự đoán; tín hiệu dạy của thích nghi vận động ngầm, khác với task error hay reward.", "ch": "ch16"}, {"term": "mossy fiber", "vi": "sợi rêu", "def": "Input chính của tiểu não, mang thông tin cảm giác và bản sao lệnh từ vỏ não (qua nhân cầu) tới các tế bào hạt.", "ch": "ch16"}, {"term": "parallel fiber", "vi": "sợi song song", "def": "Sợi trục chẻ chữ T của tế bào hạt, chạy vuông góc với các cây dendrite Purkinje; synapse của nó lên Purkinje cell là nơi học chính (LTD).", "ch": "ch16"}, {"term": "complex spike", "vi": "complex spike", "def": "Đáp ứng điện lớn, nhiều đỉnh, kèm sóng Ca2+ toàn dendrite của Purkinje cell khi climbing fibre phát xung; khác với simple spike thông thường 50–100 Hz.", "ch": "ch16"}, {"term": "motor adaptation", "vi": "thích nghi vận động", "def": "Việc hiệu chỉnh dần ánh xạ cảm giác–vận động theo sai số qua từng lần thử (kính lăng trụ, trường lực, xoay con trỏ); phụ thuộc cerebellum, để lại hậu hiệu ứng.", "ch": "ch16"}, {"term": "striatum", "vi": "thể vân", "def": "Cửa vào của basal ganglia (caudate, putamen, nucleus accumbens); ~95% là medium spiny neuron ức chế, chia hai quần thể mang thụ thể D1 và D2.", "ch": "ch16"}, {"term": "direct pathway", "vi": "đường trực tiếp", "def": "Vỏ não → neuron striatum D1 → GPi/SNr; làm giảm ức chế lên thalamus, cho phép hành động ('Go'). Dopamine tăng cường đường này.", "ch": "ch16"}, {"term": "indirect pathway", "vi": "đường gián tiếp", "def": "Vỏ não → neuron striatum D2 → GPe → STN → GPi/SNr; làm tăng ức chế lên thalamus ('NoGo'). Dopamine làm yếu đường này.", "ch": "ch16"}, {"term": "hyperdirect pathway", "vi": "đường siêu trực tiếp", "def": "Vỏ não trán → STN → GPi, bỏ qua striatum; nhanh và toả rộng, đóng vai phanh toàn cục khi cần dừng hoặc khi có xung đột lựa chọn.", "ch": "ch16"}, {"term": "subthalamic nucleus", "vi": "nhân dưới đồi thị (STN)", "def": "Nhân kích thích (glutamate) duy nhất trong basal ganglia, chiếu toả rộng tới GPi; đích phổ biến của kích thích não sâu trong Parkinson.", "ch": "ch16"}, {"term": "vigor", "vi": "độ hăng của cử động", "def": "Tốc độ và biên độ mà cử động được thực hiện; giả thuyết cho rằng basal ganglia và dopamine nền điều chỉnh vigor theo cân đối giữa phần thưởng và chi phí nỗ lực.", "ch": "ch16"}, {"term": "entorhinal cortex", "vi": "vỏ não nội khứu", "def": "Cổng giao tiếp chính giữa neocortex và hippocampus; phần medial (MEC) chứa grid cell, phần lateral (LEC) mang thông tin về vật thể, nội dung.", "ch": "ch17"}, {"term": "dentate gyrus", "vi": "hồi răng", "def": "Trạm đầu của mạch hippocampus: khoảng một triệu granule cell (ở chuột) với hoạt động cực thưa, thực hiện pattern separation.", "ch": "ch17"}, {"term": "CA3", "vi": "vùng CA3", "def": "Vùng hippocampus có kết nối hồi quy dày đặc giữa các tế bào pyramidal, được coi là bộ nhớ tự liên kết thực hiện pattern completion.", "ch": "ch17"}, {"term": "CA1", "vi": "vùng CA1", "def": "Cổng ra của hippocampus, nhận input từ CA3 (ký ức được dựng lại) và trực tiếp từ entorhinal cortex (hiện thực đang diễn ra); nơi ghi place cell kinh điển.", "ch": "ch17"}, {"term": "perforant path", "vi": "đường xuyên", "def": "Bó sợi trục từ entorhinal cortex đi vào dentate gyrus, CA3 và CA1; nơi LTP được phát hiện lần đầu.", "ch": "ch17"}, {"term": "Schaffer collateral", "vi": "nhánh Schaffer", "def": "Nhánh sợi trục của tế bào pyramidal CA3 chiếu tới CA1; synapse CA3→CA1 là nơi nghiên cứu LTP nhiều nhất.", "ch": "ch17"}, {"term": "recurrent collateral", "vi": "nhánh hồi quy", "def": "Nhánh sợi trục của tế bào CA3 quay lại nối với các tế bào CA3 khác, tạo nên mạng hồi quy kiểu Hopfield.", "ch": "ch17"}, {"term": "trisynaptic circuit", "vi": "mạch ba synapse", "def": "Đường truyền chính EC → dentate gyrus → CA3 → CA1 của hippocampus.", "ch": "ch17"}, {"term": "declarative memory", "vi": "trí nhớ tường thuật", "def": "Trí nhớ dài hạn có thể gọi lại có ý thức và diễn đạt bằng lời, gồm episodic và semantic; việc ghi mới phụ thuộc hippocampus.", "ch": "ch17"}, {"term": "episodic memory", "vi": "trí nhớ tình tiết", "def": "Ký ức về các sự kiện cụ thể gắn với nơi chốn và thời điểm ('cái gì, ở đâu, khi nào'), cho phép 'sống lại' quá khứ.", "ch": "ch17"}, {"term": "semantic memory", "vi": "trí nhớ ngữ nghĩa", "def": "Tri thức chung về sự thật và khái niệm, đã tách khỏi hoàn cảnh học ban đầu; lưu chủ yếu ở neocortex.", "ch": "ch17"}, {"term": "procedural memory", "vi": "trí nhớ thủ tục", "def": "Trí nhớ về kỹ năng và thói quen, học dần qua lặp lại, không cần ý thức và không cần hippocampus; dựa vào striatum, cerebellum, motor cortex.", "ch": "ch17"}, {"term": "anterograde amnesia", "vi": "mất trí nhớ thuận chiều", "def": "Mất khả năng hình thành ký ức mới sau thời điểm tổn thương não, như ở bệnh nhân H.M.", "ch": "ch17"}, {"term": "retrograde amnesia", "vi": "mất trí nhớ ngược chiều", "def": "Mất các ký ức hình thành trước tổn thương; thường có gradient: ký ức gần mất nhiều hơn ký ức xa (định luật Ribot).", "ch": "ch17"}, {"term": "pattern separation", "vi": "tách mẫu", "def": "Phép biến đổi làm các pattern đầu vào giống nhau trở nên ít chồng lấn hơn ở đầu ra, giảm nhiễu chéo khi lưu; gán cho dentate gyrus.", "ch": "ch17"}, {"term": "autoassociative memory", "vi": "bộ nhớ tự liên kết", "def": "Mạng hồi quy lưu các pattern bằng luật Hebb và truy xuất chúng theo nội dung từ một phần của chính pattern đó; mạng Hopfield là ví dụ kinh điển.", "ch": "ch17"}, {"term": "place cell", "vi": "tế bào vị trí", "def": "Neuron hippocampus chỉ bắn khi con vật ở một vùng nhất định của môi trường (place field); phát hiện bởi O'Keefe và Dostrovsky năm 1971.", "ch": "ch17"}, {"term": "place field", "vi": "trường vị trí", "def": "Vùng không gian trong đó một place cell bắn mạnh.", "ch": "ch17"}, {"term": "remapping", "vi": "tái ánh xạ", "def": "Hiện tượng bản đồ place cell bị xáo lại (global) hoặc đổi tần số bắn (rate) khi môi trường hay bối cảnh thay đổi.", "ch": "ch17"}, {"term": "grid cell", "vi": "tế bào lưới", "def": "Neuron ở medial entorhinal cortex có nhiều vùng bắn xếp thành lưới tam giác đều phủ kín môi trường; cung cấp hệ toạ độ cho path integration.", "ch": "ch17"}, {"term": "grid module", "vi": "module lưới", "def": "Nhóm grid cell có cùng chu kỳ và hướng lưới, chỉ khác pha; các module có chu kỳ tăng theo cấp số nhân với tỉ số khoảng 1,4.", "ch": "ch17"}, {"term": "theta rhythm", "vi": "nhịp theta", "def": "Dao động 6–10 Hz trong hippocampus khi con vật di chuyển, khám phá hoặc ngủ REM; làm đồng hồ cho phase precession và theta sequence.", "ch": "ch17"}, {"term": "time cell", "vi": "tế bào thời gian", "def": "Neuron hippocampus bắn ở những thời điểm nhất định trong một khoảng chờ, lát kín trục thời gian như place cell lát kín không gian.", "ch": "ch17"}, {"term": "cognitive map", "vi": "bản đồ nhận thức", "def": "Mô hình nội tại về cấu trúc quan hệ của môi trường (Tolman 1948), cho phép suy ra đường tắt và quan hệ chưa trải nghiệm; mở rộng từ không gian sang khái niệm.", "ch": "ch17"}, {"term": "successor representation", "vi": "biểu diễn kế nhiệm", "def": "Ma trận M(s,s') = số lần kỳ vọng có chiết khấu sẽ ghé s' khi xuất phát từ s; tách hàm giá trị thành V = M·r. Giả thuyết: place cell mã hoá các cột của M.", "ch": "ch17"}, {"term": "Tolman-Eichenbaum Machine", "vi": "cỗ máy Tolman–Eichenbaum", "def": "Mô hình của Whittington và cộng sự (2020) tách cấu trúc (grid code ở MEC) khỏi nội dung cảm giác (LEC) và gắn chúng lại trong hippocampus; bước truy xuất tương đương self-attention.", "ch": "ch17"}, {"term": "systems consolidation", "vi": "củng cố cấp hệ thống", "def": "Quá trình kéo dài nhiều tuần đến nhiều năm trong đó ký ức từ chỗ phụ thuộc hippocampus trở nên dựa vào neocortex.", "ch": "ch17"}, {"term": "replay", "vi": "phát lại", "def": "Sự tái kích hoạt lúc nghỉ hoặc ngủ các trình tự neuron đã bắn trong trải nghiệm, nén thời gian khoảng 20 lần, xuôi hoặc ngược chiều.", "ch": "ch17"}, {"term": "sharp-wave ripple", "vi": "sóng nhọn–gợn", "def": "Sự kiện điện 30–100 ms ở hippocampus lúc nghỉ và ngủ sóng chậm: một sóng nhọn từ CA3 kèm dao động 110–200 Hz ở CA1; là phương tiện chuyên chở replay.", "ch": "ch17"}, {"term": "engram", "vi": "vết nhớ", "def": "Vết tích vật lý của một ký ức: tập neuron (engram cell) hoạt động lúc học, bị biến đổi bền vững, và khi được kích hoạt lại thì gây ra sự nhớ lại.", "ch": "ch17"}, {"term": "reconsolidation", "vi": "tái củng cố", "def": "Quá trình một ký ức đã ổn định, khi được gọi lại, trở nên dễ biến đổi và cần tổng hợp protein mới để ổn định trở lại.", "ch": "ch17"}, {"term": "law of effect", "vi": "định luật hiệu quả", "def": "Nguyên lý của Thorndike (1911): hành vi được theo sau bởi kết cục dễ chịu sẽ gắn chặt hơn với tình huống, hành vi theo sau bởi kết cục khó chịu sẽ lỏng đi — tiền thân của policy gradient.", "ch": "ch18"}, {"term": "classical conditioning", "vi": "điều kiện hoá cổ điển", "def": "Học kiểu Pavlov: một kích thích trung tính đi trước kết cục quan trọng nhiều lần sẽ tự gây phản ứng dự đoán. Là bài toán 'prediction' trong RL.", "ch": "ch18"}, {"term": "instrumental conditioning", "vi": "điều kiện hoá công cụ", "def": "Học kiểu Thorndike: hành động của con vật quyết định kết cục, và kết cục thay đổi xác suất hành động. Là bài toán 'control' trong RL.", "ch": "ch18"}, {"term": "temporal credit assignment", "vi": "quy công theo thời gian", "def": "Bài toán xác định hành động hoặc sự kiện nào trong quá khứ chịu trách nhiệm cho một kết cục đến trễ; TD learning và eligibility trace là các lời giải.", "ch": "ch18"}, {"term": "blocking", "vi": "hiện tượng chặn", "def": "Thí nghiệm Kamin (1968): một cue mới không được học nếu kết cục đã được cue cũ dự đoán trọn vẹn — bằng chứng rằng học được dẫn dắt bởi sai số dự đoán, không phải đồng xuất hiện.", "ch": "ch18"}, {"term": "Rescorla–Wagner model", "vi": "mô hình Rescorla–Wagner", "def": "Mô hình 1972: mọi cue có mặt được cập nhật theo cùng sai số giữa kết cục và tổng dự đoán; về toán là delta rule/LMS.", "ch": "ch18"}, {"term": "value function", "vi": "hàm giá trị", "def": "V(s): kỳ vọng của tổng phần thưởng chiết khấu kể từ trạng thái s. Thoả phương trình Bellman V(s) = E[r + γV(s')].", "ch": "ch18"}, {"term": "TD error", "vi": "sai số sai phân thời gian", "def": "δ = r + γV(s') − V(s): độ lệch giữa hai ước lượng kề nhau của giá trị. Dương khi tốt hơn dự đoán, âm khi tệ hơn, bằng 0 khi đúng dự đoán.", "ch": "ch18"}, {"term": "temporal-difference learning", "vi": "học sai phân thời gian", "def": "Thuật toán của Sutton–Barto cập nhật V(s) theo TD error, dùng dự đoán ở bước sau làm mục tiêu cho bước trước (bootstrapping).", "ch": "ch18"}, {"term": "bootstrapping", "vi": "tự nâng bằng dây giày", "def": "Cập nhật một ước lượng bằng một ước lượng khác (dùng V(s') làm target cho V(s)); cho phép học từ sự kiện chưa mang phần thưởng nhưng có thể gây bất ổn.", "ch": "ch18"}, {"term": "complete serial compound", "vi": "hợp chất nối tiếp đầy đủ", "def": "Biểu diễn thời gian trong trial: mỗi khoảng thời gian sau cue là một state riêng (tapped delay line), cho phép TD tạo ra tín hiệu δ đúng thời điểm.", "ch": "ch18"}, {"term": "actor–critic", "vi": "diễn viên–phê bình", "def": "Kiến trúc RL với critic học giá trị V(s) và actor học policy π(a|s), cả hai cùng được cập nhật bởi một TD error. Giả thuyết chủ đạo gán critic cho ventral striatum, actor cho dorsal striatum.", "ch": "ch18"}, {"term": "Go/NoGo learning", "vi": "học Go/NoGo", "def": "Mô hình Frank/OpAL: neuron D1 tích luỹ bằng chứng 'nên làm' từ δ dương, neuron D2 tích luỹ 'không nên' từ δ âm; dopamine nền nghiêng cán cân giữa hai đường.", "ch": "ch18"}, {"term": "habit", "vi": "thói quen", "def": "Hành vi kích thích–đáp ứng không còn nhạy với giá trị hiện tại của kết cục (không đổi sau devaluation); tương ứng model-free RL ở dorsolateral striatum.", "ch": "ch18"}, {"term": "goal-directed", "vi": "hướng mục tiêu", "def": "Hành vi dựa trên tri thức về quan hệ hành động → kết cục và giá trị hiện tại của kết cục; nhạy với devaluation; tương ứng model-based RL ở prefrontal cortex và dorsomedial striatum.", "ch": "ch18"}, {"term": "model-free RL", "vi": "RL không mô hình", "def": "Học trực tiếp giá trị hoặc policy từ kinh nghiệm, không lưu mô hình chuyển tiếp của môi trường; rẻ, nhanh, nhưng không thích nghi ngay khi phần thưởng đổi.", "ch": "ch18"}, {"term": "model-based RL", "vi": "RL dựa mô hình", "def": "Học mô hình P(s'|s,a) và R, rồi lập kế hoạch bằng mô phỏng; mềm dẻo nhưng tốn tính toán; liên minh hippocampus, OFC, prefrontal cortex trong não.", "ch": "ch18"}, {"term": "two-step task", "vi": "bài hai bước", "def": "Bài của Daw 2011 với chuyển tiếp thường/hiếm giữa hai bước lựa chọn; mẫu 'chọn lại' theo thưởng × chuyển tiếp cho phép ước lượng tỉ trọng model-based vs model-free.", "ch": "ch18"}, {"term": "devaluation", "vi": "giảm giá kết cục", "def": "Thủ thuật làm kết cục mất giá (cho ăn no, gây buồn nôn) rồi kiểm tra hành vi; hành vi hướng mục tiêu giảm ngay, thói quen thì không.", "ch": "ch18"}, {"term": "distributional RL", "vi": "RL phân phối", "def": "Học toàn bộ phân phối của return thay vì kỳ vọng; một cách hiện thực là nhiều bộ dự đoán với learning rate bất đối xứng hội tụ về các expectile khác nhau — khớp với quần thể dopamine (Dabney 2020).", "ch": "ch18"}, {"term": "expectile", "vi": "expectile", "def": "Tổng quát hoá của trung bình theo loss bình phương bất đối xứng với tham số τ; τ = 0,5 là trung bình, τ cao là ước lượng 'lạc quan', τ thấp là 'bi quan'.", "ch": "ch18"}, {"term": "meta-reinforcement learning", "vi": "học tăng cường meta", "def": "Huấn luyện chậm một mạng hồi quy (bằng RL) trên nhiều task để nó tự thực hiện một thuật toán RL nhanh trong hoạt động của mình; đề xuất cho prefrontal cortex (Wang 2018); cùng nguyên lý với in-context learning.", "ch": "ch18"}, {"term": "dopamine ramp", "vi": "dopamine tăng dần", "def": "Nồng độ dopamine tăng dần khi con vật tới gần phần thưởng; được giải thích là δ của một V lồi, hoặc tín hiệu động lực, hoặc bằng mô hình ANCCR — vẫn tranh cãi.", "ch": "ch18"}, {"term": "ANCCR", "vi": "ANCCR", "def": "Adjusted net contingency for causal relations (Jeong 2022): mô hình cho rằng dopamine báo sự kiện nào trong quá khứ là nguyên nhân của kết cục hiện tại (học ngược), thay vì sai số dự đoán hướng tới tương lai.", "ch": "ch18"}, {"term": "explore–exploit dilemma", "vi": "thế lưỡng nan thăm dò–khai thác", "def": "Chọn hành động tốt nhất đã biết hay thử hành động chưa biết; người dùng cả thăm dò có hướng (kiểu UCB) và thăm dò ngẫu nhiên (kiểu softmax).", "ch": "ch18"}, {"term": "wanting vs liking", "vi": "muốn và thích", "def": "Phân biệt của Berridge: dopamine gắn với động lực 'muốn' (incentive salience), còn khoái cảm 'thích' do hệ opioid nội sinh; hai thứ có thể tách rời, đặc biệt trong nghiện.", "ch": "ch18"}, {"term": "reward hacking", "vi": "hack phần thưởng", "def": "Agent tìm cách làm tăng tín hiệu reward proxy mà không đạt mục tiêu thật; về cấu trúc giống nghiện, nơi chất gây nghiện tác động thẳng vào tín hiệu dopamine.", "ch": "ch18"}, {"term": "attention", "vi": "chú ý", "def": "Họ các cơ chế chọn lọc cho phép một phần input hoặc một phần biểu diễn được xử lý ưu tiên, còn phần khác bị suy giảm; ở mức neuron thể hiện như gain nhân đặt trước normalization.", "ch": "ch19"}, {"term": "covert attention", "vi": "chú ý ngầm", "def": "Chú ý đến một vị trí hoặc đặc trưng mà không di chuyển mắt; tiêu điểm chú ý tách khỏi tiêu điểm nhìn (Helmholtz 1894, Posner 1980).", "ch": "ch19"}, {"term": "spotlight", "vi": "đèn pha chú ý", "def": "Ẩn dụ cho spatial attention: một vùng của trường nhìn được xử lý ưu tiên, có thể di chuyển và co giãn như ống kính zoom.", "ch": "ch19"}, {"term": "feature-based attention", "vi": "chú ý theo đặc trưng", "def": "Chọn lọc theo một đặc trưng (màu, hướng chuyển động) bất kể vị trí; nhân gain của mọi neuron ưa đặc trưng ấy trên toàn trường nhìn (Treue & Martínez-Trujillo 1999).", "ch": "ch19"}, {"term": "object-based attention", "vi": "chú ý theo vật thể", "def": "Lợi ích của chú ý lan theo toàn bộ một vật thể đã được nhóm, chứ không chỉ theo vị trí không gian (Egly, Driver & Rafal 1994).", "ch": "ch19"}, {"term": "biased competition", "vi": "cạnh tranh có thiên vị", "def": "Khung lý thuyết của Desimone & Duncan (1995): các kích thích cạnh tranh nhau qua ức chế lẫn nhau ở mọi tầng; tín hiệu bottom-up và top-down nghiêng cuộc cạnh tranh; attention là hệ quả của sự nghiêng ấy.", "ch": "ch19"}, {"term": "normalization model of attention", "vi": "mô hình chuẩn hoá của attention", "def": "Mô hình Reynolds & Heeger (2009): R = A·E/(σ + pool(A·E)); trường attention A nhân vào drive trước khi chia cho pool; giải thích contrast gain và response gain bằng hình học của attention field so với kích thích.", "ch": "ch19"}, {"term": "contrast gain", "vi": "độ lợi tương phản", "def": "Dạng hiệu ứng attention trong đó đường contrast–response dịch sang trái như thể tương phản tăng, đáp ứng bão hoà không đổi.", "ch": "ch19"}, {"term": "response gain", "vi": "độ lợi đáp ứng", "def": "Dạng hiệu ứng attention trong đó toàn bộ đường contrast–response được nhân lên một hệ số, kể cả phần bão hoà.", "ch": "ch19"}, {"term": "frontal eye field", "vi": "vùng mắt trán (FEF)", "def": "Vùng của prefrontal cortex điều khiển saccade; kích thích dưới ngưỡng ở FEF làm tăng đáp ứng V4 tại vị trí tương ứng, cho thấy FEF là nguồn tín hiệu attention top-down (Moore & Armstrong 2003).", "ch": "ch19"}, {"term": "lateral intraparietal area", "vi": "vùng nội đỉnh bên (LIP)", "def": "Vùng parietal cortex của khỉ chứa priority map: mỗi vị trí trường nhìn có giá trị ưu tiên kết hợp saliency và mục tiêu, dùng cho cả attention lẫn saccade.", "ch": "ch19"}, {"term": "priority map", "vi": "bản đồ ưu tiên", "def": "Bản đồ không gian trong đó mỗi vị trí có giá trị bằng tổng độ nổi bật bottom-up và giá trị top-down; attention đi tới đỉnh của bản đồ (Bisley & Goldberg).", "ch": "ch19"}, {"term": "saliency map", "vi": "bản đồ độ nổi bật", "def": "Bản đồ tính từ hiệu center-surround của các bản đồ đặc trưng (cường độ, màu, hướng) ở nhiều tỉ lệ, cộng lại và chọn đỉnh bằng winner-take-all (Koch & Ullman 1985; Itti & Koch 1998).", "ch": "ch19"}, {"term": "pulvinar", "vi": "nhân gối (thalamus)", "def": "Nhân lớn nhất của thalamus ở linh trưởng, nối hai chiều với vỏ thị giác và parietal; điều phối đồng bộ và luồng thông tin giữa các vùng cortex theo yêu cầu attention (Saalmann 2012).", "ch": "ch19"}, {"term": "attentional blink", "vi": "cái chớp của chú ý", "def": "Hiện tượng mục tiêu thứ hai trong chuỗi RSVP bị bỏ lỡ khi xuất hiện 200–500 ms sau mục tiêu thứ nhất, dù vẫn được xử lý đến mức ngữ nghĩa (Raymond, Shapiro & Arnell 1992).", "ch": "ch19"}, {"term": "inattentional blindness", "vi": "mù do không chú ý", "def": "Không nhận thấy một kích thích rõ ràng khi attention đang bận với việc khác (thí nghiệm khỉ đột vô hình).", "ch": "ch19"}, {"term": "hemispatial neglect", "vi": "bỏ rơi nửa không gian", "def": "Hội chứng sau tổn thương parietal (thường bên phải): bệnh nhân không để ý nửa không gian đối bên dù thị giác nguyên vẹn; priority map cho nửa ấy bị hỏng.", "ch": "ch19"}, {"term": "working memory", "vi": "trí nhớ làm việc", "def": "Hệ thống giữ và thao tác một lượng nhỏ thông tin (~3–4 item) trong vài giây mà không cần input; chất nền là persistent activity và/hoặc thay đổi synapse ngắn hạn trong PFC và các vùng liên quan.", "ch": "ch19"}, {"term": "delayed-response task", "vi": "nhiệm vụ đáp ứng trì hoãn", "def": "Nhiệm vụ trong đó gợi ý được đưa ra, rồi có khoảng trì hoãn không có gợi ý, rồi phải đáp ứng dựa trên gợi ý đã mất; công cụ chuẩn để nghiên cứu working memory từ Jacobsen (1936).", "ch": "ch19"}, {"term": "persistent activity", "vi": "hoạt động dai dẳng", "def": "Neuron tiếp tục bắn ở mức cao suốt khoảng trì hoãn sau khi kích thích đã biến mất (Fuster & Alexander 1971; Funahashi 1989); được coi là chất nền cổ điển của working memory.", "ch": "ch19"}, {"term": "memory field", "vi": "trường trí nhớ", "def": "Vùng không gian mà một neuron PFC bắn trong lúc trì hoãn khi gợi ý đã xuất hiện ở đó — tương tự receptive field nhưng cho thứ không còn hiện diện.", "ch": "ch19"}, {"term": "activity-silent working memory", "vi": "trí nhớ làm việc im lặng về hoạt động", "def": "Ký ức được giữ trong trạng thái tạm thời của synapse (short-term facilitation) chứ không trong spike; đọc ra được bằng input không đặc hiệu (Mongillo 2008; Stokes 2015; Wolff 2017).", "ch": "ch19"}, {"term": "short-term facilitation", "vi": "tăng cường ngắn hạn", "def": "Tăng tạm thời xác suất giải phóng chất truyền tin sau các spike gần đây, do Ca2+ dư trong bouton; thời hằng ~1–1,5 s ở synapse PFC, nền tảng của activity-silent working memory.", "ch": "ch19"}, {"term": "proactive interference", "vi": "giao thoa tiến", "def": "Ký ức đã có trước cạnh tranh và làm giảm khả năng truy xuất ký ức mới hơn; nguồn chính của giới hạn working memory và cũng xuất hiện trong LLM (Wang & Sun 2025).", "ch": "ch19"}, {"term": "gating", "vi": "cổng / điều khiển cổng", "def": "Tín hiệu riêng quyết định khi nào bộ nhớ được phép ghi (input gate) hoặc được phép ảnh hưởng đến output (output gate); trong não do basal ganglia và thalamus thực hiện, trong LSTM do các cổng sigmoid.", "ch": "ch19"}, {"term": "PBWM", "vi": "mô hình PFC–basal ganglia working memory", "def": "Mô hình của O'Reilly & Frank (2006): PFC giữ nội dung trong các stripe, basal ganglia mở/đóng cổng cập nhật qua disinhibition của thalamus, và cổng được học bằng dopamine reward prediction error.", "ch": "ch19"}, {"term": "cognitive control", "vi": "kiểm soát nhận thức", "def": "Khả năng dùng mục tiêu và quy tắc đang giữ để định hướng xử lý và hành vi, đặc biệt khi phải thắng thói quen (Stroop); được gán chủ yếu cho PFC (Miller & Cohen 2001).", "ch": "ch19"}, {"term": "task set", "vi": "cấu hình nhiệm vụ", "def": "Biểu diễn của quy tắc/mục tiêu hiện tại trong PFC, làm nhiệm vụ bias các vùng khác để cùng phần cứng thực hiện các nhiệm vụ khác nhau; chuyển task set tốn thời gian và gây lỗi (switch cost).", "ch": "ch19"}, {"term": "premotor theory of attention", "vi": "lý thuyết tiền vận động của chú ý", "def": "Đề xuất của Rizzolatti (1987): covert attention là một saccade được lên kế hoạch nhưng bị giữ lại; attention và điều khiển mắt dùng chung mạch (FEF, LIP, superior colliculus).", "ch": "ch19"}, {"term": "early vs late selection", "vi": "chọn lọc sớm và muộn", "def": "Tranh luận về việc bộ lọc attention đặt trước (Broadbent) hay sau (Deutsch, Treisman) giai đoạn xử lý ngữ nghĩa; câu trả lời hiện đại: tuỳ tải xử lý (Lavie).", "ch": "ch19"}, {"term": "aphasia", "vi": "mất ngôn ngữ", "def": "Rối loạn ngôn ngữ mắc phải do tổn thương não (thường bán cầu trái), ảnh hưởng tới nói, hiểu, đọc hoặc viết mà không do liệt cơ hay mất trí; các kiểu kinh điển gồm Broca, Wernicke, conduction và global aphasia.", "ch": "ch20"}, {"term": "Broca's area", "vi": "vùng Broca", "def": "Phần sau hồi trán dưới bên trái (Brodmann 44–45), do Paul Broca gắn với sản xuất lời nói năm 1861; ngày nay được xem là một nút của dòng lưng và mạng ngôn ngữ chứ không phải trung tâm nói duy nhất.", "ch": "ch20"}, {"term": "Wernicke's area", "vi": "vùng Wernicke", "def": "Phần sau hồi thái dương trên bên trái, do Carl Wernicke gắn với hiểu lời nói năm 1874; định vị chính xác của nó gây tranh cãi và tổn thương gây mất hiểu bền vững thường lan rộng hơn.", "ch": "ch20"}, {"term": "arcuate fasciculus", "vi": "bó cung", "def": "Bó chất trắng nối thuỳ thái dương với thuỳ trán, là trục của dòng lưng trong xử lý lời nói; trong mô hình cổ điển được coi là dây nối Wernicke–Broca.", "ch": "ch20"}, {"term": "dual-stream model", "vi": "mô hình hai dòng", "def": "Mô hình của Hickok và Poeppel (2007): từ vỏ thính giác, dòng bụng (hai bên) ánh xạ âm thanh sang nghĩa, dòng lưng (trái) ánh xạ âm thanh sang chương trình phát âm qua vùng Spt.", "ch": "ch20"}, {"term": "Spt", "vi": "vùng Sylvian đỉnh–thái dương", "def": "Vùng ở đáy rãnh Sylvius, giao diện cảm giác–vận động của dòng lưng; hoạt động cả khi nghe lẫn khi thầm nói; tổn thương gây conduction aphasia.", "ch": "ch20"}, {"term": "superior temporal gyrus", "vi": "hồi thái dương trên", "def": "Hồi vỏ não nằm ngay dưới rãnh Sylvius, chứa vỏ thính giác và vùng xử lý âm vị của lời nói (STG); mã hoá các đặc trưng phát âm, ngữ điệu, trọng âm và khởi đầu câu nói.", "ch": "ch20"}, {"term": "ECoG", "vi": "điện vỏ não", "def": "Electrocorticography: ghi điện thế bằng lưới điện cực đặt trực tiếp trên bề mặt vỏ não (thường ở bệnh nhân động kinh chờ phẫu thuật); dải high-gamma 70–150 Hz phản ánh hoạt động quần thể neuron với độ phân giải mili-giây.", "ch": "ch20"}, {"term": "high-gamma", "vi": "dải gamma cao", "def": "Dải tần 70–150 Hz của tín hiệu ECoG/LFP, có công suất tương quan với tốc độ phát spike của quần thể neuron dưới điện cực; là chỉ số hoạt động cục bộ ưa dùng trong nghiên cứu lời nói.", "ch": "ch20"}, {"term": "phonetic feature", "vi": "đặc trưng âm vị/phát âm", "def": "Thuộc tính phát âm (tắc, xát, hữu thanh, vị trí lưỡi…) mà tổ hợp của chúng xác định một âm vị; STG mã hoá lời nói theo các trục đặc trưng này thay vì theo từng âm vị.", "ch": "ch20"}, {"term": "language network", "vi": "mạng ngôn ngữ", "def": "Tập vùng vỏ não (chủ yếu trán dưới và thái dương bên trái) được định vị riêng từng người bằng localizer câu vs chuỗi vô nghĩa; chọn lọc cho ngôn ngữ ở mọi dạng và gần như không đáp ứng với toán, nhạc, code hay suy luận.", "ch": "ch20"}, {"term": "functional localizer", "vi": "bài định vị chức năng", "def": "Nhiệm vụ fMRI ngắn dùng để xác định trong từng người các voxel chọn lọc cho một chức năng (ví dụ đọc câu trừ đọc chuỗi vô nghĩa cho ngôn ngữ), tránh mất tính chọn lọc khi trung bình hoá giữa người.", "ch": "ch20"}, {"term": "multiple demand network", "vi": "mạng đa nhu cầu", "def": "Hệ thống vỏ trán–đỉnh hoạt động trong hầu hết nhiệm vụ nhận thức khó (toán, suy luận, hiểu code, điều khiển chú ý), tách biệt với mạng ngôn ngữ.", "ch": "ch20"}, {"term": "N400", "vi": "sóng N400", "def": "Thành phần ERP âm, đỉnh khoảng 400 ms sau khi một từ xuất hiện, biên độ tăng khi từ ít được kỳ vọng trong ngữ cảnh; tỉ lệ gần tuyến tính với surprisal của từ.", "ch": "ch20"}, {"term": "P600", "vi": "sóng P600", "def": "Thành phần ERP dương, đỉnh khoảng 600 ms, xuất hiện khi gặp vi phạm hoặc bất thường cú pháp đòi hỏi tái phân tích câu; có thể là họ hàng của P300.", "ch": "ch20"}, {"term": "event-related potential", "vi": "điện thế liên quan sự kiện", "def": "Tín hiệu EEG/MEG được lấy trung bình theo thời điểm xuất hiện của một kích thích lặp lại nhiều lần, làm nổi các thành phần như N1, P2, N400, P600.", "ch": "ch20"}, {"term": "cloze probability", "vi": "xác suất cloze", "def": "Tỉ lệ người điền đúng một từ khi được cho câu bỏ trống; thước đo hành vi của mức kỳ vọng, tiền thân của surprisal tính từ mô hình ngôn ngữ.", "ch": "ch20"}, {"term": "surprisal", "vi": "độ bất ngờ", "def": "−log P(từ | ngữ cảnh), tính bằng bit; theo Hale (2001) và Levy (2008), chi phí xử lý một từ (thời gian đọc, N400) tỉ lệ với surprisal; trùng với cross-entropy loss của một mô hình ngôn ngữ trên token đó.", "ch": "ch20"}, {"term": "temporal receptive window", "vi": "cửa sổ tiếp nhận thời gian", "def": "Khoảng thời gian quá khứ mà đáp ứng của một vùng não phụ thuộc vào (Hasson); tăng dần từ vài trăm ms ở vỏ thính giác tới hàng chục giây ở vùng đỉnh/trán cao.", "ch": "ch20"}, {"term": "inter-subject correlation", "vi": "tương quan liên chủ thể", "def": "Tương quan theo thời gian giữa đáp ứng não của những người khác nhau nghe/xem cùng một kích thích tự nhiên; dùng để đo độ tin cậy của đáp ứng và ước lượng noise ceiling.", "ch": "ch20"}, {"term": "encoding model", "vi": "mô hình mã hoá", "def": "Mô hình dự đoán tín hiệu não từ đặc trưng của kích thích (ví dụ activation của LLM) bằng hồi quy tuyến tính, đánh giá trên dữ liệu held-out và chuẩn hoá theo noise ceiling.", "ch": "ch20"}, {"term": "brain score", "vi": "điểm giống não", "def": "Chỉ số tổng hợp mức độ activation của một mô hình dự đoán được tín hiệu não trên một hay nhiều bộ dữ liệu; nhạy với cách chia dữ liệu, mô hình đối chứng và noise ceiling.", "ch": "ch20"}, {"term": "temporal autocorrelation", "vi": "tự tương quan thời gian", "def": "Tính chất tín hiệu não trôi chậm khiến các mẫu gần nhau trong thời gian giống nhau bất kể nội dung; nếu chia train/test xáo trộn, mô hình có thể đạt điểm cao mà không hiểu kích thích.", "ch": "ch20"}, {"term": "BOLD", "vi": "tín hiệu BOLD", "def": "Blood-oxygen-level-dependent: tín hiệu fMRI phản ánh thay đổi oxy máu theo hoạt động thần kinh, chậm và nhoè khoảng 5–10 giây, nên không phân giải được từng từ.", "ch": "ch20"}, {"term": "BabyLM", "vi": "thử thách BabyLM", "def": "Cuộc thi từ 2023 huấn luyện mô hình ngôn ngữ trên kho dữ liệu cỡ trẻ em (10 triệu hoặc 100 triệu từ) để nghiên cứu học hiệu quả về dữ liệu và so sánh với việc trẻ học ngôn ngữ.", "ch": "ch20"}, {"term": "formal competence", "vi": "năng lực hình thức", "def": "Kiến thức về quy tắc và mẫu thống kê của ngôn ngữ (ngữ pháp, hình thái, nghĩa từ); trong não do mạng ngôn ngữ đảm nhiệm; LLM đã đạt gần hoàn hảo.", "ch": "ch20"}, {"term": "functional competence", "vi": "năng lực chức năng", "def": "Khả năng dùng ngôn ngữ để suy luận, vận dụng kiến thức thế giới, mô hình hoá tình huống và tâm trí người khác; trong não do các hệ thống ngoài mạng ngôn ngữ đảm nhiệm; LLM đạt không đồng đều.", "ch": "ch20"}, {"term": "grounding", "vi": "nối đất biểu tượng", "def": "Việc nối biểu diễn ngôn ngữ với trải nghiệm cảm giác–vận động và thế giới; LLM văn bản thuần thiếu grounding, dù bằng chứng thần kinh cho thấy nghĩa từ không nằm hoàn toàn ở vùng cảm giác–vận động.", "ch": "ch20"}, {"term": "compositionality", "vi": "tính tổ hợp", "def": "Nguyên lý nghĩa của biểu thức được xây từ nghĩa các phần và cách ghép chúng; LLM tổ hợp tốt với mẫu quen nhưng khái quát hoá tổ hợp có hệ thống vẫn là thách thức.", "ch": "ch20"}, {"term": "vocal learning", "vi": "học phát âm", "def": "Khả năng học tạo ra âm thanh mới bằng bắt chước (người, chim biết hót, vẹt, cá voi…); đòi hỏi mẫu trong trí nhớ, giai đoạn bập bẹ và phản hồi thính giác từ chính mình.", "ch": "ch20"}, {"term": "HVC", "vi": "nhân HVC", "def": "Nhân não trước của chim biết hót đóng vai đồng hồ bài hát: mỗi neuron chiếu phát một chùm spike ở một thời điểm cố định (~10 ms) trong bài hát, tạo mã chuỗi cực thưa.", "ch": "ch20"}, {"term": "LMAN", "vi": "nhân LMAN", "def": "Nhân đầu ra của đường trước não trước ở chim biết hót, bơm biến thiên vào lệnh vận động ở RA; cần cho thăm dò khi học hót và cho biến thiên có kiểm soát ở chim trưởng thành.", "ch": "ch20"}, {"term": "Area X", "vi": "vùng X", "def": "Cấu trúc homolog của basal ganglia trong đường trước não trước của chim biết hót, nhận dopamine từ VTA mã hoá sai số hiệu suất của bài hát.", "ch": "ch20"}, {"term": "inverse problem", "vi": "bài toán ngược", "def": "Bài toán suy ra nguyên nhân (thế giới 3D) từ hệ quả (ảnh võng mạc 2D); thường không có nghiệm duy nhất nên cần giả định bổ sung (prior).", "ch": "ch21"}, {"term": "unconscious inference", "vi": "suy luận vô thức", "def": "Khái niệm của Helmholtz (1867): tri giác là kết luận của một lập luận xác suất mà ta không ý thức được tiền đề.", "ch": "ch21"}, {"term": "prior", "vi": "tiên nghiệm", "def": "Phân phối xác suất về trạng thái thế giới trước khi có dữ liệu, học từ tiến hoá và kinh nghiệm (vd. ánh sáng từ trên, vật thể chuyển động chậm).", "ch": "ch21"}, {"term": "likelihood", "vi": "hàm hợp lý", "def": "Xác suất quan sát được dữ liệu nếu thế giới ở một trạng thái cho trước, p(o|s); mô tả 'giác quan nói gì' và độ nhiễu của nó.", "ch": "ch21"}, {"term": "posterior", "vi": "hậu nghiệm", "def": "Niềm tin về trạng thái thế giới sau khi kết hợp prior với dữ liệu: p(s|o) ∝ p(o|s)p(s).", "ch": "ch21"}, {"term": "precision", "vi": "độ chính xác (nghịch đảo phương sai)", "def": "π = 1/σ². Trong kết hợp Bayes, mỗi nguồn được cân theo precision; trong predictive coding, precision là gain nhân vào neuron sai số và được coi là cơ chế của attention.", "ch": "ch21"}, {"term": "Bayesian brain", "vi": "bộ não Bayes", "def": "Giả thuyết ở tầng computational rằng não biểu diễn bất định và kết hợp thông tin gần với suy luận Bayes; được ủng hộ bởi thí nghiệm cue combination và học prior.", "ch": "ch21"}, {"term": "hollow-mask illusion", "vi": "ảo giác mặt nạ rỗng", "def": "Mặt trong lõm của mặt nạ được thấy là lồi vì prior 'mặt người lồi' lấn át bằng chứng bóng đổ và stereo; yếu hơn ở bệnh nhân schizophrenia.", "ch": "ch21"}, {"term": "prediction error", "vi": "sai số dự đoán", "def": "Hiệu giữa quan sát thực tế và quan sát mà mô hình nội tại dự đoán; đơn vị tiền tệ chung của Kalman filter, TD learning, predictive coding.", "ch": "ch21"}, {"term": "Kalman gain", "vi": "hệ số Kalman", "def": "Trọng số K gán cho sai số dự đoán khi cập nhật niềm tin; bằng precision tương đối của quan sát so với dự đoán và tự thay đổi theo bất định.", "ch": "ch21"}, {"term": "representation unit", "vi": "neuron biểu diễn", "def": "Trong predictive coding, quần thể giữ ước lượng hiện tại về nguyên nhân ẩn ở một tầng; bị đẩy bởi sai số từ dưới và kéo về dự đoán từ trên.", "ch": "ch21"}, {"term": "error unit", "vi": "neuron sai số", "def": "Quần thể tính hiệu giữa input của tầng và dự đoán từ tầng trên; hoạt động của nó được gửi lên feedforward và dùng cho học Hebb.", "ch": "ch21"}, {"term": "end-stopping", "vi": "ức chế theo chiều dài", "def": "Tính chất của nhiều neuron V1: đáp ứng giảm khi thanh kích thích kéo dài ra ngoài receptive field cổ điển; được Rao & Ballard giải thích là neuron sai số im khi ngữ cảnh dự đoán được.", "ch": "ch21"}, {"term": "mismatch negativity", "vi": "sóng âm bất khớp (MMN)", "def": "Thành phần EEG/MEG âm ở ~100–250 ms sau một kích thích vi phạm quy luật của chuỗi (Näätänen 1978); xuất hiện cả khi không chú ý và với quy luật trừu tượng.", "ch": "ch21"}, {"term": "omission response", "vi": "đáp ứng với sự vắng mặt", "def": "Hoạt động thần kinh khi một kích thích được kỳ vọng không xảy ra; không giải thích được bằng adaptation, là bằng chứng mạnh cho dự đoán.", "ch": "ch21"}, {"term": "stimulus-specific adaptation", "vi": "thích nghi đặc hiệu kích thích", "def": "Giảm đáp ứng của neuron với kích thích lặp lại do cơ chế cục bộ (mệt synapse, adaptation); lời giải thích cạnh tranh với predictive coding cho nhiều hiện tượng bất ngờ.", "ch": "ch21"}, {"term": "variational free energy", "vi": "năng lượng tự do biến phân", "def": "F = E_q[log q − log p(o,s)] = KL(q‖p(s|o)) − log p(o): cận trên của bất ngờ; tối thiểu hoá theo q cho suy luận xấp xỉ. Bằng −ELBO.", "ch": "ch21"}, {"term": "ELBO", "vi": "cận dưới bằng chứng", "def": "Evidence lower bound = −F: hàm mục tiêu của VAE gồm reconstruction trừ KL; tối đa hoá nó tương đương tối thiểu hoá free energy.", "ch": "ch21"}, {"term": "active inference", "vi": "suy luận chủ động", "def": "Mở rộng của free energy principle: hành động cũng giảm free energy bằng cách làm cảm giác khớp dự đoán; mục tiêu được mã hoá như prior về trạng thái ưa thích.", "ch": "ch21"}, {"term": "free energy principle", "vi": "nguyên lý năng lượng tự do", "def": "Tuyên bố của Friston rằng mọi hệ tự duy trì phải trông như đang tối thiểu hoá free energy biến phân; thống nhất Bayes, predictive coding và VAE về mặt toán, nhưng bị phê bình là không kiểm chứng được như tuyên bố phổ quát.", "ch": "ch21"}, {"term": "neural sampling", "vi": "lấy mẫu thần kinh", "def": "Giả thuyết rằng hoạt động neuron tại mỗi thời điểm là một mẫu từ posterior; biến thiên trial-to-trial biểu diễn bất định và hoạt động tự phát biểu diễn prior.", "ch": "ch21"}, {"term": "Helmholtz machine", "vi": "máy Helmholtz", "def": "Mô hình của Dayan, Hinton, Neal, Zemel (1995) với mạng sinh top-down và mạng nhận dạng bottom-up, học bằng thuật toán wake–sleep; tổ tiên của VAE.", "ch": "ch21"}, {"term": "predictive routing", "vi": "định tuyến dự đoán", "def": "Đề xuất của Bastos và cộng sự (2020): dự đoán chuẩn bị ức chế (alpha/beta lớp sâu) cho input kỳ vọng, còn input bất ngờ đi qua với gamma ở lớp nông.", "ch": "ch21"}, {"term": "aberrant salience", "vi": "nổi bật bất thường", "def": "Giả thuyết (Kapur 2003) rằng dopamine lệch gán tầm quan trọng cho sự kiện tầm thường; trong ngôn ngữ predictive coding là precision sai số tầng thấp tăng bất thường.", "ch": "ch21"}, {"term": "sequential probability ratio test", "vi": "kiểm định tỉ số xác suất tuần tự (SPRT)", "def": "Thủ tục của Wald (1945): cộng dồn log-likelihood ratio của các quan sát và dừng khi chạm một trong hai ngưỡng. Tối ưu về số quan sát trung bình với tỉ lệ lỗi cho trước.", "ch": "ch22"}, {"term": "drift-diffusion model", "vi": "mô hình trôi-khuếch tán (DDM)", "def": "Mô hình quyết định hai lựa chọn: bằng chứng tích luỹ theo một quá trình Wiener có drift v và nhiễu σ, kết thúc khi chạm ngưỡng a hoặc 0. Giải thích đồng thời độ chính xác và phân phối thời gian phản ứng.", "ch": "ch22"}, {"term": "LIP", "vi": "vùng đỉnh trong bên (lateral intraparietal area)", "def": "Vùng vỏ đỉnh của khỉ liên quan tới kế hoạch liếc mắt; firing rate của nó tăng dần như một bộ tích luỹ bằng chứng trong nhiệm vụ chấm chuyển động (Shadlen).", "ch": "ch22"}, {"term": "urgency signal", "vi": "tín hiệu khẩn cấp", "def": "Thành phần tăng dần theo thời gian, không phụ thuộc bằng chứng, cộng vào biến quyết định; tương đương ngưỡng sụp dần, bảo đảm quyết định kết thúc khi thời gian có chi phí.", "ch": "ch22"}, {"term": "speed–accuracy trade-off", "vi": "đánh đổi tốc độ–chính xác", "def": "Quyết định nhanh hơn thì sai nhiều hơn; trong DDM được điều khiển chủ yếu bởi khoảng cách ngưỡng a.", "ch": "ch22"}, {"term": "confidence", "vi": "độ tự tin (trong quyết định)", "def": "Ước lượng xác suất lựa chọn là đúng; trong não có thể đọc từ mức bằng chứng tích luỹ kết hợp với thời gian đã trôi qua (Kiani & Shadlen 2009).", "ch": "ch22"}, {"term": "neuroeconomics", "vi": "kinh tế học thần kinh", "def": "Ngành nghiên cứu cách não biểu diễn giá trị chủ quan và ra quyết định kinh tế, kết hợp kinh tế học, tâm lý học và thần kinh học.", "ch": "ch22"}, {"term": "orbitofrontal cortex", "vi": "vỏ ổ mắt (OFC)", "def": "Phần vỏ trước trán nằm trên hốc mắt; neuron ở đây mã hoá giá trị kinh tế của các phương án theo thang chung, bất biến với menu (Padoa-Schioppa & Assad 2006).", "ch": "ch22"}, {"term": "ventromedial prefrontal cortex", "vi": "vỏ trước trán bụng giữa (vmPFC)", "def": "Vùng vỏ trước trán mà tín hiệu fMRI tăng theo giá trị chủ quan của mọi loại phần thưởng; cũng chứa ký ức an toàn trong extinction và tổn thương gây rối loạn quyết định.", "ch": "ch22"}, {"term": "prospect theory", "vi": "lý thuyết triển vọng", "def": "Kahneman & Tversky (1979): giá trị được đánh giá so với điểm tham chiếu, mất mát nặng hơn được, độ nhạy giảm dần, và xác suất bị cân trọng số phi tuyến.", "ch": "ch22"}, {"term": "loss aversion", "vi": "ghét mất mát", "def": "Mất một khoản gây giảm giá trị chủ quan lớn hơn khoảng hai lần so với được cùng khoản đó (λ ≈ 2). Ở não tương ứng với độ dốc giảm mạnh hơn độ dốc tăng của vmPFC/striatum.", "ch": "ch22"}, {"term": "fear conditioning", "vi": "điều kiện hoá sợ hãi", "def": "Ghép một kích thích trung tính (CS) với một kích thích khó chịu (US); sau đó CS một mình gây đáp ứng sợ. Cơ chế: LTP ở synapse CS→amygdala bên.", "ch": "ch22"}, {"term": "extinction", "vi": "dập tắt", "def": "Trình bày CS nhiều lần không có US làm đáp ứng giảm; không phải xoá mà là học một ký ức ức chế mới, gắn bối cảnh, do vmPFC/infralimbic điều khiển.", "ch": "ch22"}, {"term": "infralimbic cortex", "vi": "vỏ infralimbic (IL)", "def": "Phần bụng của vỏ trước trán giữa ở gặm nhấm; neuron ở đây lưu ký ức extinction và ức chế output amygdala qua các tế bào intercalated (Milad & Quirk 2002).", "ch": "ch22"}, {"term": "somatic marker", "vi": "dấu hiệu cơ thể", "def": "Giả thuyết của Damasio: các trạng thái cơ thể gắn với hậu quả trước đây được gọi lại khi cân nhắc và thiên vị quyết định qua vmPFC.", "ch": "ch22"}, {"term": "interoception", "vi": "nội cảm", "def": "Cảm nhận trạng thái bên trong cơ thể (tim, hô hấp, tiêu hoá, viêm), đi qua dây phế vị và tuỷ sống lên insula; nền tảng của cảm xúc theo nhiều lý thuyết.", "ch": "ch22"}, {"term": "insula", "vi": "vỏ đảo", "def": "Vùng vỏ não nằm sâu trong rãnh Sylvius, tích hợp tín hiệu nội cảm thành cảm nhận về trạng thái cơ thể và cảm xúc.", "ch": "ch22"}, {"term": "HPA axis", "vi": "trục hạ đồi–tuyến yên–thượng thận", "def": "Chuỗi nội tiết của đáp ứng stress: CRH từ hypothalamus → ACTH từ tuyến yên → cortisol từ vỏ thượng thận, đỉnh sau ~20–30 phút, tác động lên biểu hiện gene.", "ch": "ch22"}, {"term": "REM sleep", "vi": "giấc ngủ chuyển động mắt nhanh", "def": "Pha ngủ với EEG giống thức, mắt đảo nhanh, cơ tê liệt, acetylcholine cao và noradrenaline/serotonin gần bằng không; giấc mơ sống động thường xảy ra ở đây.", "ch": "ch22"}, {"term": "slow-wave sleep", "vi": "giấc ngủ sóng chậm (N3)", "def": "Pha ngủ sâu với EEG bị thống trị bởi slow oscillation dưới 1 Hz; công suất sóng chậm là chỉ số của áp lực ngủ và đây là pha chính của consolidation hệ thống.", "ch": "ch22"}, {"term": "slow oscillation", "vi": "dao động chậm", "def": "Dao động <1 Hz của toàn vỏ não giữa up-state (neuron hoạt động) và down-state (im lặng) trong giấc ngủ sâu; đặt nhịp cho spindle và ripple.", "ch": "ch22"}, {"term": "sleep spindle", "vi": "thoi ngủ", "def": "Chùm dao động 11–16 Hz kéo dài 0,5–2 s do mạch thalamus–vỏ não sinh ra trong N2/N3; đưa Ca²⁺ vào dendrite vỏ não và được cho là mở cửa plasticity cho consolidation.", "ch": "ch22"}, {"term": "two-process model", "vi": "mô hình hai quá trình", "def": "Borbély (1982): giấc ngủ được điều tiết bởi quá trình S (áp lực ngủ homeostatic, tăng khi thức) và quá trình C (nhịp sinh học ~24 h).", "ch": "ch22"}, {"term": "adenosine", "vi": "adenosine", "def": "Sản phẩm phân huỷ ATP tích tụ ngoại bào khi thức; ức chế hệ thức tỉnh và là ứng viên phân tử của áp lực ngủ. Caffeine là chất đối kháng thụ thể adenosine.", "ch": "ch22"}, {"term": "synaptic homeostasis hypothesis", "vi": "giả thuyết cân bằng nội môi synapse (SHY)", "def": "Tononi & Cirelli: thức chủ yếu tăng độ mạnh synapse; giấc ngủ giảm tổng thể có chọn lọc để tiết kiệm năng lượng, không gian và tăng tỉ số tín hiệu/nhiễu.", "ch": "ch22"}, {"term": "glymphatic system", "vi": "hệ glymphatic", "def": "Hệ thống dòng dịch quanh mạch máu đi qua nhu mô não nhờ aquaporin-4 trên astrocyte, được cho là thải chất thải; mức tăng khi ngủ đang bị tranh cãi (Xie 2013 vs. Miao 2024).", "ch": "ch22"}, {"term": "overfitted brain hypothesis", "vi": "giả thuyết bộ não quá khớp", "def": "Hoel (2021): giấc mơ sinh ra các mẫu bị làm méo có cấu trúc để chống overfit vào dữ liệu hẹp hằng ngày, tương tự data augmentation trong deep learning.", "ch": "ch22"}, {"term": "generative replay", "vi": "replay sinh", "def": "Trong continual learning: dùng một mô hình sinh tạo mẫu giả của nhiệm vụ cũ để trộn với dữ liệu mới thay cho buffer thật; tương tự hippocampus 'mơ' lại quá khứ cho neocortex.", "ch": "ch22"}, {"term": "hard problem", "vi": "bài toán khó (của ý thức)", "def": "Câu hỏi của Chalmers (1995): vì sao và bằng cách nào việc thực hiện các chức năng nhận thức lại đi kèm với trải nghiệm chủ quan. Khác với các bài toán dễ, ta chưa biết một lời giải sẽ trông thế nào.", "ch": "ch23"}, {"term": "easy problem", "vi": "bài toán dễ (của ý thức)", "def": "Các câu hỏi về chức năng: phân biệt, tích hợp, báo cáo, chú ý, điều khiển hành vi, thức/ngủ. 'Dễ' vì ta biết lời giải là một cơ chế hay thuật toán, dù có thể mất hàng thập kỷ.", "ch": "ch23"}, {"term": "phenomenal consciousness", "vi": "ý thức hiện tượng", "def": "Bản thân trải nghiệm chủ quan — cái 'nó giống như thế nào' (Block 1995). Phân biệt với access consciousness.", "ch": "ch23"}, {"term": "access consciousness", "vi": "ý thức truy cập", "def": "Thông tin sẵn sàng cho báo cáo, suy luận và điều khiển hành vi. Trong thực nghiệm ta hầu như luôn đo cái này, qua nút bấm hay lời nói của người tham gia.", "ch": "ch23"}, {"term": "neural correlates of consciousness", "vi": "tương quan thần kinh của ý thức (NCC)", "def": "Tập cơ chế thần kinh tối thiểu cùng đủ cho một trải nghiệm nhất định (Crick & Koch 1990). Chiến lược: giữ input cố định, đổi trải nghiệm, xem cái gì trong não khác đi.", "ch": "ch23"}, {"term": "blindsight", "vi": "thị giác mù", "def": "Khả năng định vị, phân biệt và phản ứng với kích thích thị giác mà không có trải nghiệm thấy, ở bệnh nhân mất V1 (Weiskrantz 1974). Cho thấy xử lý thông tin và trải nghiệm tách rời được.", "ch": "ch23"}, {"term": "binocular rivalry", "vi": "cạnh tranh hai mắt", "def": "Khi hai mắt nhận hai hình khác nhau, trải nghiệm luân phiên giữa hai hình thay vì trộn. Input cố định, trải nghiệm đổi — dụng cụ NCC kinh điển (Logothetis).", "ch": "ch23"}, {"term": "backward masking", "vi": "che ngược", "def": "Một kích thích ngắn bị làm cho không thấy bởi một hình 'mặt nạ' xuất hiện ngay sau nó (SOA ~50 ms trở xuống). Kích thích bị che vẫn được xử lý cục bộ nhưng không lan rộng.", "ch": "ch23"}, {"term": "global workspace", "vi": "không gian làm việc toàn cục", "def": "Lý thuyết của Baars (1988): nhiều module vô thức chạy song song; nội dung thắng cạnh tranh được phát sóng cho toàn hệ thống — và đó là ý thức. Ẩn dụ từ kiến trúc blackboard của AI.", "ch": "ch23"}, {"term": "global neuronal workspace", "vi": "không gian làm việc thần kinh toàn cục (GNW)", "def": "Phiên bản thần kinh của global workspace (Dehaene, Changeux, Naccache): lõi neuron pyramidal L2/3 tầm xa ở PFC–đỉnh; ý thức tương ứng với ignition all-or-none lan rộng ~300 ms sau kích thích.", "ch": "ch23"}, {"term": "ignition", "vi": "bắt lửa", "def": "Chuyển pha đột ngột, tự duy trì và lan rộng của hoạt động trong workspace khi input vượt ngưỡng; nổi lên từ recurrent gain đủ mạnh (bistability). Chữ ký EEG là P3b muộn.", "ch": "ch23"}, {"term": "recurrent processing theory", "vi": "lý thuyết xử lý hồi quy", "def": "Lamme: feedforward sweep là vô thức; trải nghiệm xuất hiện khi feedback mở các vòng recurrent cục bộ trong vỏ cảm giác (~100–200 ms), không cần tới PFC hay báo cáo.", "ch": "ch23"}, {"term": "integrated information theory", "vi": "lý thuyết thông tin tích hợp (IIT)", "def": "Tononi: xuất phát từ 5 tiên đề về trải nghiệm, suy ra ý thức là cấu trúc nhân–quả không thể quy giản của một hệ vật lý, đo bằng Φ. Dự đoán posterior hot zone; feedforward và máy tính số có Φ ≈ 0.", "ch": "ch23"}, {"term": "phi", "vi": "Φ, thông tin tích hợp", "def": "Lượng thông tin nhân–quả mà một hệ mất đi khi bị cắt ở vết cắt yếu nhất (minimum information partition). Φ = 0 nếu hệ tách được thành các phần độc lập. Tính đầy đủ bất khả thi với hệ lớn.", "ch": "ch23"}, {"term": "posterior hot zone", "vi": "vùng nóng phía sau", "def": "Lưới các vùng vỏ đỉnh–chẩm–thái dương phía sau mà IIT (và một số dữ liệu tổn thương, ngủ) cho là nền vật lý trực tiếp của trải nghiệm, đối lập với PFC của GNW.", "ch": "ch23"}, {"term": "higher-order theory", "vi": "lý thuyết bậc cao (HOT)", "def": "Một trạng thái cảm giác chỉ được trải nghiệm khi có một biểu diễn bậc cao về nó ('tôi đang thấy X'), thường gắn với PFC bên và metacognition. Phiên bản của Lau: perceptual reality monitoring.", "ch": "ch23"}, {"term": "attention schema theory", "vi": "lý thuyết lược đồ chú ý (AST)", "def": "Graziano: não giữ một mô hình nội bộ đơn giản hoá về attention của chính nó để điều khiển attention; 'trải nghiệm chủ quan' là nội dung của mô hình ấy. Hard problem theo đó là ảo ảnh.", "ch": "ch23"}, {"term": "predictive processing", "vi": "xử lý dự đoán", "def": "Khung coi tri giác là suy luận từ trên xuống được hiệu chỉnh bởi sai số dự đoán. Seth mở rộng sang interoception: cảm giác là chính mình bắt nguồn từ dự đoán về cơ thể sống.", "ch": "ch23"}, {"term": "adversarial collaboration", "vi": "hợp tác đối kháng", "def": "Hai phe lý thuyết cùng thiết kế thí nghiệm, cam kết dự đoán và tiêu chí đậu/rớt trước, đăng ký trước, và để bên thứ ba thu–phân tích dữ liệu. Cogitate (2019–2025) là ví dụ lớn nhất trong khoa học ý thức.", "ch": "ch23"}, {"term": "no-report paradigm", "vi": "mô thức không báo cáo", "def": "Thí nghiệm suy ra trải nghiệm từ dấu hiệu gián tiếp (đồng tử, chuyển động mắt, kích thích không liên quan nhiệm vụ) để tách NCC khỏi các quá trình báo cáo; hoạt động PFC thường co lại khi không cần báo cáo.", "ch": "ch23"}, {"term": "cognitive motor dissociation", "vi": "tách rời nhận thức–vận động", "def": "Bệnh nhân không đáp ứng hành vi nhưng làm theo lệnh trong fMRI/EEG (Owen 2006). Nghiên cứu đa trung tâm 2024 thấy ở khoảng 1/4 bệnh nhân không đáp ứng.", "ch": "ch23"}, {"term": "perturbational complexity index", "vi": "chỉ số phức tạp nhiễu loạn (PCI)", "def": "Gõ xung TMS, ghi EEG đáp ứng, nhị phân hoá và nén Lempel–Ziv; PCI cao khi đáp ứng vừa lan rộng vừa đa dạng. Ngưỡng lâm sàng ~0,31 tách thức/ngủ sâu/gây mê (Casali 2013, Casarotto 2016).", "ch": "ch23"}, {"term": "Lempel-Ziv complexity", "vi": "độ phức tạp Lempel–Ziv", "def": "Số cụm mới mà thuật toán LZ76 cần để mô tả một chuỗi; chuỗi lặp cho giá trị thấp, chuỗi ngẫu nhiên cho giá trị cao. Cốt lõi của các thuật toán nén zip và của PCI.", "ch": "ch23"}, {"term": "unresponsive wakefulness syndrome", "vi": "hội chứng thức không đáp ứng (UWS)", "def": "Tên hiện đại của 'trạng thái thực vật': bệnh nhân có chu kỳ thức–ngủ nhưng không có dấu hiệu hành vi của ý thức. Một tỷ lệ đáng kể có PCI cao hoặc cognitive motor dissociation.", "ch": "ch23"}, {"term": "general anesthesia", "vi": "gây mê toàn thân", "def": "Tắt ý thức có hồi phục bằng thuốc; các cơ chế phân tử khác nhau (GABA-A, NMDA, α2) hội tụ ở tầng mạch: sóng chậm bistable, mất kết nối feedback, ngắt ghép nối apical–soma. Ketamine là ngoại lệ: ngắt kết nối nhưng vẫn mơ.", "ch": "ch23"}, {"term": "computational functionalism", "vi": "chức năng luận tính toán", "def": "Lập trường cho rằng ý thức phụ thuộc vào tổ chức tính toán chứ không vào chất liệu vật lý; là giả định làm việc của Butlin, Long và cộng sự (2023) và bị IIT cùng Seth phản đối.", "ch": "ch23"}, {"term": "indicator property", "vi": "thuộc tính chỉ báo", "def": "Đặc điểm kiến trúc rút ra từ một lý thuyết ý thức (recurrence, workspace, giám sát bậc cao, attention schema, agency, embodiment) mà càng có nhiều thì càng có lý do xem xét khả năng có ý thức của một hệ AI — không phải điều kiện cần hay đủ.", "ch": "ch23"}, {"term": "readiness potential", "vi": "điện thế sẵn sàng (RP)", "def": "Điện thế EEG âm chậm trên vùng vận động bắt đầu ~0,5–1 s trước cử động tự phát (Kornhuber & Deecke 1965; Libet 1983). Schurger (2012) giải thích nó là ảo ảnh của việc căn theo ngưỡng một accumulator nhiễu.", "ch": "ch23"}, {"term": "Libet experiment", "vi": "thí nghiệm Libet", "def": "1983: RP bắt đầu ~550 ms trước cử động trong khi 'ý muốn' được báo cáo (W) chỉ ~200 ms trước. Thường được diễn giải là não quyết định trước ý thức; cách diễn giải này bị mô hình accumulator thách thức.", "ch": "ch23"}, {"term": "dendritic integration theory", "vi": "lý thuyết tích hợp dendrite", "def": "Aru, Suzuki & Larkum (2020): ý thức đòi hỏi ghép nối giữa vùng apical (nhận feedback) và soma/basal (nhận feedforward) của neuron pyramidal L5; thuốc gây mê ngắt ghép nối này ở chuột.", "ch": "ch23"}, {"term": "gigaseal", "vi": "điểm nối gigaohm", "def": "Điểm nối điện trở >10 GΩ giữa đầu pipette và màng tế bào; đẩy nhiễu nhiệt xuống dưới 1 pA, cho phép thấy dòng của từng kênh ion.", "ch": "ch24"}, {"term": "whole-cell recording", "vi": "ghi toàn tế bào", "def": "Cấu hình patch clamp trong đó mảnh màng dưới pipette bị phá, pipette thông với bào tương và ghi/kẹp điện thế của cả tế bào.", "ch": "ch24"}, {"term": "extracellular recording", "vi": "ghi ngoại bào", "def": "Đặt điện cực ngoài tế bào để nghe các dòng điện trong dịch ngoại bào; thấy spike (50–500 µV, ~1 ms) của neuron trong bán kính ~50–150 µm và LFP.", "ch": "ch24"}, {"term": "spike sorting", "vi": "phân loại spike theo nguồn", "def": "Bài toán gán từng spike ghi ngoại bào cho neuron phát ra nó, dựa vào dạng sóng và phân bố biên độ trên nhiều kênh; bước lọc–ngưỡng–cắt–phân cụm.", "ch": "ch24"}, {"term": "tetrode", "vi": "điện cực bốn dây", "def": "Bốn sợi dây xoắn lại; cùng một spike xuất hiện với bốn biên độ khác nhau tuỳ vị trí neuron, tạo dấu vân tay để tách nguồn (Wilson & McNaughton 1993).", "ch": "ch24"}, {"term": "Utah array", "vi": "mảng điện cực Utah", "def": "Mảng 10×10 kim silicon dài ~1–1,5 mm cách nhau 400 µm cắm vào vỏ não, ghi ~100 neuron; thiết bị chuẩn của BCI xâm lấn ở người.", "ch": "ch24"}, {"term": "Neuropixels", "vi": "đầu dò Neuropixels", "def": "Đầu dò silicon mật độ cao (Jun 2017): mũi 10 mm với 960 điểm ghi, 384 kênh đọc cùng lúc, điện tử trên chip; bản 2.0 (2021) 5.120 điểm, ổn định nhiều tuần.", "ch": "ch24"}, {"term": "EEG", "vi": "điện não đồ", "def": "Ghi điện thế trên da đầu (Berger 1924–1929) sinh ra bởi các lưỡng cực của neuron pyramidal xếp song song nhận input đồng bộ; độ phân giải ms nhưng cm, bài toán ngược không có nghiệm duy nhất.", "ch": "ch24"}, {"term": "MEG", "vi": "từ não đồ", "def": "Đo từ trường (femtotesla) của cùng các dòng điện tạo EEG bằng SQUID hoặc OPM; ít bị sọ làm mờ nhưng chỉ thấy lưỡng cực tiếp tuyến.", "ch": "ch24"}, {"term": "hemodynamic response function", "vi": "hàm đáp ứng huyết động", "def": "Đáp ứng BOLD với một sự kiện thần kinh ngắn: trễ ~2 s, đỉnh 5–6 s, về nền sau ~12 s rồi lõm; kernel thông thấp mà hoạt động thần kinh bị chập với.", "ch": "ch24"}, {"term": "neurovascular coupling", "vi": "ghép nối thần kinh–mạch máu", "def": "Chuỗi cơ chế (astrocyte, NO, K⁺…) khiến tiểu động mạch giãn sau khi neuron hoạt động; nền tảng sinh lý của fMRI và fNIRS.", "ch": "ch24"}, {"term": "PET", "vi": "chụp cắt lớp positron", "def": "Tiêm chất đánh dấu phóng xạ (glucose, phối tử receptor, amyloid) và đếm cặp photon huỷ; độ phân giải mm–cm, phút; cách duy nhất nhìn hoá học trong não người sống.", "ch": "ch24"}, {"term": "fNIRS", "vi": "quang phổ cận hồng ngoại chức năng", "def": "Chiếu ánh sáng cận hồng ngoại qua da đầu để đo oxy-/deoxy-hemoglobin ở vỏ não nông; rẻ, di động, độ phân giải cm.", "ch": "ch24"}, {"term": "GCaMP", "vi": "chỉ thị calcium mã hoá gen", "def": "Protein huỳnh quang (GFP vòng + calmodulin + M13) sáng lên khi Ca²⁺ gắn vào; Ca²⁺ tăng theo spike nên GCaMP là proxy chậm (τ ~0,5–1,5 s) của hoạt động.", "ch": "ch24"}, {"term": "calcium imaging", "vi": "chụp ảnh calcium", "def": "Ghi hoạt động của hàng nghìn đến hàng triệu neuron bằng chỉ thị calcium và kính hiển vi (hai photon, light-sheet, miniscope); có danh tính tế bào nhưng độ phân giải thời gian ~30–100 ms và phi tuyến.", "ch": "ch24"}, {"term": "two-photon microscopy", "vi": "hiển vi hai photon", "def": "Kích thích huỳnh quang bằng hai photon hồng ngoại đến cùng lúc, chỉ xảy ra tại tiêu điểm laser; cho ảnh từng tế bào ở độ sâu đến ~1 mm trong mô tán xạ (Denk 1990).", "ch": "ch24"}, {"term": "voltage imaging", "vi": "chụp ảnh điện áp", "def": "Dùng chỉ thị điện áp mã hoá gen (ASAP, Voltron, JEDI) để thấy điện thế màng ở ~1 ms, kể cả dưới ngưỡng; tín hiệu yếu, tẩy màu nhanh, ít tế bào.", "ch": "ch24"}, {"term": "optogenetics", "vi": "quang di truyền", "def": "Đưa gen opsin (channelrhodopsin, halorhodopsin…) vào loại tế bào chọn trước rồi bật/tắt chúng bằng ánh sáng với độ chính xác mili giây, thuận nghịch (Boyden & Deisseroth 2005).", "ch": "ch24"}, {"term": "channelrhodopsin", "vi": "kênh rhodopsin", "def": "Kênh cation từ tảo lục mở khi có ánh sáng xanh (~470 nm); khi biểu hiện ở neuron, mỗi xung sáng vài ms gây một spike.", "ch": "ch24"}, {"term": "DREADD", "vi": "receptor thiết kế kích hoạt bằng thuốc thiết kế", "def": "Receptor GPCR đột biến chỉ đáp ứng với phân tử nhân tạo (CNO); cho phép kích thích/ức chế một quần thể tế bào trong hàng giờ bằng cách tiêm thuốc (Armbruster & Roth 2007).", "ch": "ch24"}, {"term": "TMS", "vi": "kích thích từ xuyên sọ", "def": "Xung từ trường ~2 T từ cuộn dây trên da đầu cảm ứng dòng điện trong vỏ não nông, gây spike hoặc 'lesion ảo' vài chục ms; không xâm lấn, độ phân giải cm.", "ch": "ch24"}, {"term": "deep brain stimulation", "vi": "kích thích não sâu", "def": "Điện cực cấy sâu (nhân dưới đồi, globus pallidus) phát xung ~130 Hz liên tục; điều trị Parkinson và các bệnh khác, cơ chế còn tranh luận.", "ch": "ch24"}, {"term": "lesion", "vi": "tổn thương", "def": "Phá huỷ một vùng não (bệnh lý hoặc thí nghiệm) để suy ra chức năng; phương pháp nhân quả lâu đời nhất, bị nhiễu bởi bù trừ theo thời gian.", "ch": "ch24"}, {"term": "electron microscopy", "vi": "hiển vi điện tử", "def": "Kỹ thuật hình ảnh độ phân giải vài nanomet, đủ thấy khe synapse (20 nm) và vesicle; nền tảng của connectomics cấp synapse, đòi hỏi mô cố định và cắt lát 30–40 nm.", "ch": "ch24"}, {"term": "expansion microscopy", "vi": "hiển vi phóng đại mô", "def": "Gắn mô vào polymer hút nước rồi cho nở 4–20 lần đều đặn để kính hiển vi quang học thường thấy được chi tiết dưới giới hạn nhiễu xạ (Boyden 2015).", "ch": "ch24"}, {"term": "tissue clearing", "vi": "làm trong mô", "def": "Thay lipid bằng hydrogel (CLARITY) hoặc dung môi (iDISCO) để ánh sáng xuyên qua cả bộ não, cho phép chụp toàn não bằng light-sheet.", "ch": "ch24"}, {"term": "FlyWire", "vi": "connectome não ruồi FlyWire", "def": "Connectome hoàn chỉnh của não ruồi giấm cái trưởng thành, công bố 10/2024: 139.255 neuron, ~54,5 triệu synapse, ~8.400 loại tế bào; hiệu đính bởi cộng đồng.", "ch": "ch24"}, {"term": "MICrONS", "vi": "dự án MICrONS", "def": "Dự án tái dựng 1 mm³ vỏ thị giác chuột (4/2025): >200.000 tế bào, ~523 triệu synapse, 1,6 PB ảnh EM, kết hợp với calcium imaging của 75.909 neuron trước khi cố định.", "ch": "ch24"}, {"term": "H01", "vi": "bộ dữ liệu H01", "def": "1 mm³ vỏ thái dương người (mô phẫu thuật động kinh) tái dựng bằng EM (Shapson-Coe, Lichtman, Google, 2024): ~57.000 tế bào, 150 triệu synapse, 1,4 PB.", "ch": "ch24"}, {"term": "Patch-seq", "vi": "patch clamp kết hợp giải trình tự", "def": "Ghi điện bằng patch clamp, chụp hình thái, rồi hút bào tương ra giải trình tự RNA của cùng một tế bào; nối điện sinh lý, hình thái và gen.", "ch": "ch24"}, {"term": "NWB", "vi": "Neurodata Without Borders", "def": "Định dạng dữ liệu chuẩn cho điện sinh lý và quang học thần kinh, dùng bởi Allen, IBL, DANDI; tương đương BIDS cho MRI.", "ch": "ch24"}, {"term": "3R", "vi": "thay thế, giảm, tinh chỉnh", "def": "Khung đạo đức nghiên cứu động vật: Replace (thay thế khi có thể), Reduce (giảm số lượng), Refine (giảm đau khổ).", "ch": "ch24"}, {"term": "Kilosort", "vi": "Kilosort", "def": "Thuật toán spike sorting của Pachitariu và cộng sự (2016–2024) dùng template matching trên GPU và hiệu chỉnh drift của mô não so với điện cực.", "ch": "ch25"}, {"term": "raster plot", "vi": "biểu đồ raster", "def": "Hình vẽ mỗi trial một hàng, mỗi spike một chấm theo thời gian; cách xem thô nhất dữ liệu spike.", "ch": "ch25"}, {"term": "PSTH", "vi": "biểu đồ tần số quanh kích thích", "def": "Peri-stimulus time histogram: ước lượng firing rate theo thời gian bằng cách trung bình số spike qua các trial trong từng bin hoặc làm trơn bằng kernel.", "ch": "ch25"}, {"term": "neural decoding", "vi": "giải mã thần kinh", "def": "Dự đoán kích thích hay hành vi từ hoạt động thần kinh; chứng minh thông tin tồn tại trong vùng não nhưng không chứng minh não sử dụng nó.", "ch": "ch25"}, {"term": "linear discriminant analysis", "vi": "phân tích phân biệt tuyến tính", "def": "Classifier giả định các lớp Gaussian có cùng hiệp phương sai; với shrinkage, là decoder mặc định tốt khi số trial nhỏ so với số neuron.", "ch": "ch25"}, {"term": "Kalman filter", "vi": "bộ lọc Kalman", "def": "Bộ ước lượng Bayes đệ quy cho hệ tuyến tính Gaussian; trong BCI, giải mã vị trí/vận tốc từ spike bằng cách kết hợp mô hình động lực trơn với quan sát nhiễu.", "ch": "ch25"}, {"term": "dPCA", "vi": "PCA tách nhân tố", "def": "Demixed PCA (Kobak 2016): giảm chiều tách phương sai của quần thể theo từng nhân tố thí nghiệm (thời gian, kích thích, quyết định) thành các trục riêng.", "ch": "ch25"}, {"term": "UMAP", "vi": "UMAP", "def": "Phương pháp nhúng phi tuyến bảo toàn lân cận cục bộ; hữu ích để hiển thị nhưng không bảo toàn khoảng cách toàn cục hay hình dạng, nên không dùng để kết luận.", "ch": "ch25"}, {"term": "LFADS", "vi": "LFADS", "def": "Latent Factor Analysis via Dynamical Systems (Pandarinath 2018): sequential VAE với generator RNN suy ra rate và dynamics tiềm ẩn từ spike của từng trial.", "ch": "ch25"}, {"term": "CEBRA", "vi": "CEBRA", "def": "Phương pháp contrastive learning (Schneider, Lee & Mathis 2023) học embedding của hoạt động thần kinh nhất quán giữa các phiên ghi, có thể dùng nhãn thời gian hoặc hành vi.", "ch": "ch25"}, {"term": "POYO", "vi": "POYO", "def": "Foundation model cho spike (Azabou 2023, POYO+ 2025) coi mỗi spike là một token với embedding riêng cho từng unit, dùng cross-attention để giải mã hành vi xuyên phiên ghi.", "ch": "ch25"}, {"term": "representational similarity analysis", "vi": "phân tích tương đồng biểu diễn", "def": "RSA (Kriegeskorte 2008): so sánh hai hệ thống qua ma trận khác biệt giữa các cặp kích thích (RDM) thay vì khớp từng neuron với từng unit.", "ch": "ch25"}, {"term": "CKA", "vi": "căn chỉnh kernel căn tâm", "def": "Centered kernel alignment (Kornblith 2019): số đo tương đồng giữa hai ma trận biểu diễn, bất biến với xoay trực giao và tỉ lệ; có sàn phụ thuộc kích thước dữ liệu.", "ch": "ch25"}, {"term": "linear predictivity", "vi": "khả năng dự đoán tuyến tính", "def": "Số đo tương đồng não–mô hình bằng cách hồi quy tuyến tính từ activation mô hình sang đáp ứng từng neuron và đo tương quan trên kích thích mới.", "ch": "ch25"}, {"term": "double dipping", "vi": "phân tích vòng", "def": "Sai lầm thống kê khi dùng cùng dữ liệu để chọn (neuron, voxel, cửa sổ) và để kiểm định, làm nhiễu trông như tín hiệu (Kriegeskorte 2009).", "ch": "ch25"}, {"term": "GPFA", "vi": "phân tích nhân tố Gaussian process", "def": "Gaussian-process factor analysis (Yu 2009): suy ra quỹ đạo latent trơn theo thời gian trên từng trial bằng EM.", "ch": "ch25"}, {"term": "surrogate data", "vi": "dữ liệu giả kiểm soát", "def": "Dữ liệu sinh nhân tạo giữ một số thống kê của dữ liệu thật (như TME của Elsayed & Cunningham 2017) để kiểm tra cấu trúc quan sát được có nổi bật trên mức nhàm chán hay không.", "ch": "ch25"}, {"term": "spiking neural network", "vi": "mạng neuron xung", "def": "Mạng neural mà các đơn vị là neuron có trạng thái (điện thế màng) và chỉ truyền tín hiệu nhị phân rời rạc (spike) khi vượt ngưỡng; về toán là một RNN với activation Heaviside.", "ch": "ch26"}, {"term": "event-driven", "vi": "hướng sự kiện", "def": "Kiểu tính toán chỉ thực hiện phép toán khi có sự kiện (spike) đến, nên năng lượng tỉ lệ với số sự kiện chứ không với kích thước mạng.", "ch": "ch26"}, {"term": "neuromorphic engineering", "vi": "kỹ thuật mô phỏng thần kinh", "def": "Thuật ngữ do Carver Mead đặt (1990): thiết kế mạch điện tử (analog hoặc số) bắt chước tổ chức và nguyên lý vật lý của hệ thần kinh — thưa, tại chỗ, hướng sự kiện.", "ch": "ch26"}, {"term": "surrogate gradient", "vi": "gradient thay thế", "def": "Kỹ thuật huấn luyện SNN: giữ hàm bước Heaviside ở lượt xuôi nhưng thay đạo hàm (delta Dirac) bằng một hàm trơn có bướu quanh ngưỡng ở lượt ngược, cho phép dùng BPTT.", "ch": "ch26"}, {"term": "ANN-to-SNN conversion", "vi": "chuyển đổi ANN sang SNN", "def": "Huấn luyện mạng ANN với ReLU rồi thay mỗi đơn vị bằng neuron integrate-and-fire, dựa trên việc tần số spike của IF xấp xỉ ReLU với độ phân giải 1/T; cần nhiều bước thời gian T để chính xác.", "ch": "ch26"}, {"term": "rate coding", "vi": "mã tần số", "def": "Cách mã hoá thông tin bằng số spike trong một cửa sổ thời gian; đơn giản, bền nhiễu, nhưng tốn nhiều bước thời gian để đạt độ phân giải cao.", "ch": "ch26"}, {"term": "time-to-first-spike", "vi": "thời điểm spike đầu tiên", "def": "Mã latency: mỗi neuron phát đúng một spike, sớm nếu đầu vào mạnh, muộn nếu yếu; cực thưa và nhanh nhưng nhạy với nhiễu thời gian.", "ch": "ch26"}, {"term": "delta coding", "vi": "mã sai phân", "def": "Chỉ phát spike (dương/âm) khi tín hiệu thay đổi vượt ngưỡng so với mức tham chiếu; không có thay đổi thì không có spike. Nguyên lý của retina ON/OFF và camera sự kiện.", "ch": "ch26"}, {"term": "graded spike", "vi": "spike có mức", "def": "Spike mang theo một giá trị số nguyên (tới 32 bit trên Loihi 2) thay vì chỉ 1 bit, cho phép mỗi sự kiện chở nhiều thông tin hơn — thoả hiệp giữa thưa theo sự kiện và giàu thông tin.", "ch": "ch26"}, {"term": "TrueNorth", "vi": "chip TrueNorth (IBM)", "def": "Chip số neuromorphic của IBM (2014): 4.096 lõi, 1 triệu neuron, 256 triệu synapse, tiêu thụ ~65–70 mW nhờ thiết kế hoàn toàn hướng sự kiện; không học on-chip.", "ch": "ch26"}, {"term": "Loihi", "vi": "chip Loihi (Intel)", "def": "Dòng chip neuromorphic số của Intel: Loihi 1 (2018, 128k neuron, học STDP on-chip) và Loihi 2 (2021, 1 triệu neuron/chip, neuron lập trình bằng microcode, graded spike). 1.152 Loihi 2 tạo thành Hala Point (2024).", "ch": "ch26"}, {"term": "Hala Point", "vi": "hệ thống Hala Point", "def": "Hệ neuromorphic lớn nhất thế giới tính đến 2024 (Intel, đặt tại Sandia): 1.152 Loihi 2, 1,15 tỷ neuron, 128 tỷ synapse, tối đa 2,6 kW.", "ch": "ch26"}, {"term": "SpiNNaker", "vi": "máy SpiNNaker", "def": "Kiến trúc của Steve Furber (Manchester) rồi TU Dresden: hàng triệu lõi ARM tổng quát nối bằng mạng gói tin tối ưu cho spike; mô phỏng mọi mô hình neuron bằng phần mềm. SpiNNaker2 (2024) dùng chip 152 lõi Cortex-M4F.", "ch": "ch26"}, {"term": "BrainScaleS", "vi": "hệ BrainScaleS", "def": "Chip mixed-signal của Heidelberg: neuron AdEx analog trên tụ và transistor thật, chạy nhanh hơn thời gian sinh học 1.000 lần, với synapse số 6 bit và lõi học on-chip.", "ch": "ch26"}, {"term": "memristor", "vi": "điện trở có nhớ", "def": "Linh kiện hai cực có điện trở thay đổi theo lịch sử dòng chạy qua và giữ nguyên khi tắt điện; xếp thành lưới crossbar để thực hiện nhân ma trận–vector bằng định luật Ohm và Kirchhoff ngay tại nơi lưu trọng số.", "ch": "ch26"}, {"term": "in-memory computing", "vi": "tính toán trong bộ nhớ", "def": "Nguyên lý thực hiện phép tính ngay tại nơi lưu dữ liệu (như synapse trong não) để tránh chi phí di chuyển dữ liệu, vốn lớn hơn chi phí phép tính hàng chục đến hàng trăm lần.", "ch": "ch26"}, {"term": "dynamic vision sensor", "vi": "cảm biến thị giác động", "def": "Camera sự kiện (DVS): mỗi pixel độc lập theo dõi log cường độ sáng và chỉ phát sự kiện ON/OFF khi thay đổi vượt ngưỡng, với độ trễ microgiây, dải động ~120 dB, không có khung hình.", "ch": "ch26"}, {"term": "event camera", "vi": "camera sự kiện", "def": "Tên gọi chung cho cảm biến hình ảnh kiểu DVS: đầu ra là dòng sự kiện (x, y, t, ±1) thay vì khung hình; băng thông và năng lượng tỉ lệ với lượng chuyển động.", "ch": "ch26"}, {"term": "Speck", "vi": "chip Speck (SynSense)", "def": "SoC thị giác neuromorphic tích hợp DVS và 9 lớp SNN tích chập số, ~328k neuron, tiêu thụ cỡ 5 mW (dưới 1 mW khi tĩnh), dùng cho thiết bị luôn-bật.", "ch": "ch26"}, {"term": "sparsity", "vi": "độ thưa", "def": "Tỉ lệ neuron/phần tử không hoạt động (bằng 0) tại một thời điểm. Lợi thế năng lượng của SNN chỉ xuất hiện khi sparsity rất cao (thường trên ~93–97%) và số bước thời gian nhỏ.", "ch": "ch26"}, {"term": "state-space model", "vi": "mô hình không gian trạng thái", "def": "Lớp mô hình sequence (S4, Mamba) với trạng thái ẩn tuyến tính h[t]=Ah[t−1]+Bx[t], tính song song như tích chập. Neuron LIF bỏ ngưỡng chính là một SSM bậc nhất.", "ch": "ch26"}, {"term": "Spikformer", "vi": "transformer spiking", "def": "Kiến trúc của Zhou et al. (ICLR 2023) đưa self-attention vào SNN với Q, K, V nhị phân: QKᵀ là đếm trùng khớp, không cần softmax; đạt ~74,8% ImageNet với T=4.", "ch": "ch26"}, {"term": "SpikeGPT", "vi": "mô hình ngôn ngữ spiking", "def": "Mô hình ngôn ngữ sinh dựa trên spike của Zhu, Zhao, Li & Eshraghian (2023/TMLR 2024), kiến trúc RWKV, 45M và 216M tham số, cạnh tranh với mô hình không-spike cùng cỡ trên perplexity.", "ch": "ch26"}, {"term": "snnTorch", "vi": "thư viện snnTorch", "def": "Thư viện Python trên PyTorch (Eshraghian) để xây và huấn luyện SNN bằng surrogate gradient; cùng họ có Norse, SpikingJelly và Lava (Intel).", "ch": "ch26"}, {"term": "NeuroBench", "vi": "bộ chuẩn NeuroBench", "def": "Khung benchmark cộng đồng (2025) cho thuật toán và hệ thống neuromorphic, đo mật độ hoạt động, số phép toán đồng bộ/không đồng bộ, độ trễ và năng lượng thay vì chỉ độ chính xác.", "ch": "ch26"}, {"term": "parametric LIF", "vi": "LIF có tham số học được", "def": "Biến thể LIF (Fang et al. 2021) trong đó hệ số rò β (tức hằng số thời gian màng) là tham số học được theo lớp; tương ứng với bước rời rạc hoá Δ học được trong SSM.", "ch": "ch26"}, {"term": "continual learning", "vi": "học liên tục", "def": "Chế độ học trong đó dữ liệu/task đến tuần tự và mô hình phải học cái mới mà không làm hỏng cái cũ, không được xem lại toàn bộ dữ liệu quá khứ.", "ch": "ch27"}, {"term": "stability–plasticity dilemma", "vi": "thế lưỡng nan ổn định–mềm dẻo", "def": "Mâu thuẫn giữa việc giữ ký ức cũ ổn định và việc học nhanh cái mới; một hệ chỉ có một learning rate toàn cục không thể tối ưu cả hai.", "ch": "ch27"}, {"term": "synaptic consolidation", "vi": "củng cố synapse", "def": "Quá trình synapse chuyển từ thay đổi tạm thời (early-LTP) sang thay đổi bền (late-LTP, cấu trúc), sau đó trở nên khó bị cập nhật mới ghi đè.", "ch": "ch27"}, {"term": "cascade model", "vi": "mô hình thác synapse", "def": "Mô hình của Fusi, Drew & Abbott (2005): mỗi synapse có chuỗi trạng thái siêu ổn định với xác suất cập nhật giảm dần, tạo phổ thời hằng rộng và đường cong quên luỹ thừa.", "ch": "ch27"}, {"term": "elastic weight consolidation", "vi": "củng cố trọng số đàn hồi (EWC)", "def": "Phương pháp continual learning (Kirkpatrick 2017) thêm phạt bậc hai kéo mỗi tham số về giá trị cũ với độ cứng tỉ lệ thông tin Fisher của task cũ.", "ch": "ch27"}, {"term": "synaptic intelligence", "vi": "trí thông minh synapse (SI)", "def": "Phương pháp của Zenke, Poole & Ganguli (2017): mỗi tham số tự tích luỹ online đóng góp của mình vào việc giảm loss dọc đường huấn luyện, rồi dùng làm độ cứng khi học task mới.", "ch": "ch27"}, {"term": "context-dependent gating", "vi": "gating theo ngữ cảnh", "def": "Tắt/mở các tập neuron khác nhau cho từng task hay bối cảnh để các task ít dùng chung trọng số, giảm giao thoa (Masse 2018, XdG).", "ch": "ch27"}, {"term": "loss of plasticity", "vi": "mất khả năng học", "def": "Hiện tượng mạng huấn luyện liên tục trên nhiều task dần học cái mới kém đi (neuron chết, rank co lại); Dohare & Sutton (2024) đề xuất tái khởi tạo unit ít hữu dụng.", "ch": "ch27"}, {"term": "sample efficiency", "vi": "hiệu quả mẫu", "def": "Lượng dữ liệu hoặc số lần tương tác cần để đạt một mức hiệu năng; não (đặc biệt trẻ em) cần ít ví dụ có nhãn hơn deep learning nhiều bậc.", "ch": "ch27"}, {"term": "core knowledge", "vi": "kiến thức lõi", "def": "Theo Spelke, các hệ thống tri thức có rất sớm ở trẻ sơ sinh về vật thể, tác nhân, số và không gian; Lake và cs. (2017) coi đó là prior mà AI thiếu.", "ch": "ch27"}, {"term": "hypernetwork", "vi": "siêu mạng", "def": "Mạng nhỏ sinh ra trọng số của mạng lớn; Koulakov–Zador dùng nó để mô phỏng genome nén connectome.", "ch": "ch27"}, {"term": "in-context learning", "vi": "học trong ngữ cảnh", "def": "Khả năng của LLM thích nghi với task mới chỉ từ ví dụ trong prompt mà không đổi trọng số; là 'vòng trong' không cần gradient.", "ch": "ch27"}, {"term": "differentiable plasticity", "vi": "plasticity khả vi", "def": "Cách của Miconi, Stanley & Clune (2018): mỗi kết nối có hệ số plasticity học bằng backprop, còn dấu vết Hebb cập nhật cục bộ lúc chạy.", "ch": "ch27"}, {"term": "mixture of experts", "vi": "hỗn hợp chuyên gia (MoE)", "def": "Kiến trúc có nhiều mạng con (expert) nhưng mỗi input chỉ kích hoạt vài expert qua bộ định tuyến; nhiều tham số, ít FLOP mỗi token — tương tự mã thưa của não.", "ch": "ch27"}, {"term": "quantization", "vi": "lượng tử hoá", "def": "Biểu diễn trọng số/hoạt động bằng ít bit hơn (8, 4, 1,58 bit) để giảm bộ nhớ và năng lượng; synapse sinh học chỉ có ~4–5 bit.", "ch": "ch27"}, {"term": "curiosity", "vi": "tò mò", "def": "Động lực nội tại tìm kiếm thông tin mới hoặc giảm bất định; trong RL được mô hình hoá bằng phần thưởng nội tại theo novelty, sai số dự đoán hoặc learning progress.", "ch": "ch27"}, {"term": "intrinsic reward", "vi": "phần thưởng nội tại", "def": "Tín hiệu thưởng do chính agent tạo ra (không từ môi trường) để khuyến khích khám phá; ví dụ 1/√n(s), sai số forward model (ICM), RND.", "ch": "ch27"}, {"term": "world model", "vi": "mô hình thế giới", "def": "Mô hình nội tại dự đoán trạng thái/quan sát tiếp theo từ trạng thái và hành động; cho phép lập kế hoạch và học chính sách trong 'tưởng tượng' (Ha & Schmidhuber 2018, Dreamer, JEPA).", "ch": "ch27"}, {"term": "embodiment", "vi": "tính hiện thân", "def": "Quan điểm rằng nhận thức và học gắn với việc có thân thể tương tác với môi trường, tự chọn dữ liệu qua hành động.", "ch": "ch27"}, {"term": "hardware lottery", "vi": "xổ số phần cứng", "def": "Nhận xét của Sara Hooker (2021): một ý tưởng nghiên cứu thắng thường vì hợp với phần cứng đang có chứ không chỉ vì đúng; CNN phải chờ GPU.", "ch": "ch27"}, {"term": "Bitter Lesson", "vi": "Bài học cay đắng", "def": "Bài luận của Sutton (2019): phương pháp tổng quát tận dụng tính toán (tìm kiếm, học) cuối cùng luôn thắng phương pháp nhồi tri thức con người vào hệ thống.", "ch": "ch27"}, {"term": "multi-timescale plasticity", "vi": "plasticity nhiều thang thời gian", "def": "Việc một hệ có nhiều biến trạng thái cập nhật ở tốc độ khác nhau (từ giây tới năm), cho phép vừa học nhanh vừa nhớ lâu; xuất hiện ở synapse sinh học lẫn Nested Learning.", "ch": "ch27"}, {"term": "brain–computer interface", "vi": "giao diện não–máy (BCI)", "def": "Hệ thống ghi tín hiệu thần kinh, giải mã thành lệnh điều khiển một thiết bị (con trỏ, tay robot, bộ tổng hợp giọng nói) và/hoặc kích thích ngược vào não; luôn là một vòng lặp kín có phản hồi.", "ch": "ch28"}, {"term": "decoder", "vi": "bộ giải mã", "def": "Thuật toán ánh xạ đặc trưng thần kinh (số spike, công suất băng tần) sang biến điều khiển (vận tốc con trỏ, âm vị); từ population vector, Kalman filter tới RNN/transformer cộng language model.", "ch": "ch28"}, {"term": "effector", "vi": "bộ tác động", "def": "Thiết bị thực hiện lệnh giải mã: con trỏ, tay robot, bộ tổng hợp giọng nói, máy kích thích cơ hay tuỷ sống. Người dùng nhìn/cảm nhận effector để khép vòng lặp.", "ch": "ch28"}, {"term": "P300", "vi": "sóng P300", "def": "Điện thế dương ở EEG ~300 ms sau một kích thích hiếm và được chờ đợi; P300 speller (Farwell & Donchin 1988) dùng nó để chọn chữ trong ma trận nhấp nháy.", "ch": "ch28"}, {"term": "SSVEP", "vi": "điện thế gợi thị giác trạng thái ổn định", "def": "Dao động ở vỏ thị giác theo đúng tần số của một kích thích nhấp nháy đang được nhìn; cho phép chọn giữa nhiều mục tiêu bằng phổ EEG, thông lượng cao nhất trong nhóm không xâm lấn.", "ch": "ch28"}, {"term": "motor imagery", "vi": "tưởng tượng vận động", "def": "Tưởng tượng cử động một chi làm giảm nhịp mu/beta (event-related desynchronization) ở vỏ vận động đối bên; đặc trưng công suất băng tần này được phân loại để điều khiển BCI EEG.", "ch": "ch28"}, {"term": "Stentrode", "vi": "stent điện cực", "def": "Thiết bị của Synchron: stent 16 điện cực luồn qua tĩnh mạch lên xoang tĩnh mạch dọc trên, nằm trên vỏ vận động; ghi LFP qua thành mạch, không cần mở sọ, đủ cho các lệnh rời rạc.", "ch": "ch28"}, {"term": "ReFIT", "vi": "hiệu chỉnh lại bằng gán nhãn ý định", "def": "Recalibrated Feedback Intention-Trained Kalman filter (Gilja 2012): gán lại nhãn vận tốc là vector chỉ về đích (bằng 0 khi đã tới) rồi fit lại decoder; tăng gấp đôi thông lượng.", "ch": "ch28"}, {"term": "co-adaptation", "vi": "đồng thích nghi", "def": "Não và decoder cùng học trong vòng lặp kín: người dùng thay đổi hoạt động thần kinh theo lỗi nhìn thấy, decoder được cập nhật theo dữ liệu mới; nhịp cập nhật phải được chọn để cả hai kịp theo.", "ch": "ch28"}, {"term": "closed-loop decoder adaptation", "vi": "thích nghi decoder vòng kín", "def": "Cập nhật decoder ngay trong khi người dùng đang điều khiển, với tốc độ học chọn sao cho não kịp thích nghi (Orsborn & Carmena).", "ch": "ch28"}, {"term": "CTC", "vi": "connectionist temporal classification", "def": "Hàm mất mát cho bài toán chuỗi-sang-chuỗi không cần căn chỉnh thời gian, dùng ký hiệu 'blank'; mượn từ ASR để huấn luyện decoder âm vị của BCI lời nói.", "ch": "ch28"}, {"term": "language model", "vi": "mô hình ngôn ngữ", "def": "Prior P(w) trên chuỗi từ (n-gram hoặc LLM); trong BCI lời nói, beam search cực đại hoá P(spike|w)P(w), biến ~80% âm vị đúng thành ~97% từ đúng.", "ch": "ch28"}, {"term": "inner speech", "vi": "lời nói trong đầu", "def": "Lời nói tưởng tượng, không cố gắng phát âm; tạo hoạt động yếu hơn ở cùng vùng vận động miệng, giải mã được một phần (Kunz 2025) và có thể được decoder cố ý bỏ qua.", "ch": "ch28"}, {"term": "cochlear implant", "vi": "ốc tai điện tử", "def": "Thiết bị biến âm thanh thành 12–22 băng tần rồi kích thích điện dây thần kinh thính giác theo vị trí tonotopic trong ốc tai; BCI thành công nhất với hơn một triệu người dùng.", "ch": "ch28"}, {"term": "phosphene", "vi": "đốm sáng ảo", "def": "Cảm giác thấy một đốm sáng khi retina hoặc vỏ thị giác bị kích thích điện; đơn vị cơ bản của mọi thị giác nhân tạo hiện nay.", "ch": "ch28"}, {"term": "intracortical microstimulation", "vi": "vi kích thích trong vỏ não (ICMS)", "def": "Xung điện vài chục µA, 100–300 Hz qua vi điện cực trong vỏ não; ở S1 tạo cảm giác chạm/áp lực ở ngón tay, dùng làm phản hồi xúc giác cho tay robot (Flesher 2016, 2021).", "ch": "ch28"}, {"term": "information transfer rate", "vi": "tốc độ truyền thông tin (ITR)", "def": "Số bit hữu ích mỗi giây mà người dùng lấy ra qua BCI; tính theo Fitts (con trỏ) hoặc Wolpaw (lựa chọn rời rạc); EEG dưới 1 bit/s, spike xâm lấn 2–10 bit/s.", "ch": "ch28"}, {"term": "neural drift", "vi": "trôi thần kinh", "def": "Sự thay đổi từng ngày của tập neuron được ghi và tuning của chúng (điện cực dịch, sẹo, trạng thái), khiến decoder cố định mất hiệu năng; tương đương covariate shift trong ML.", "ch": "ch28"}, {"term": "latent alignment", "vi": "căn chỉnh không gian ẩn", "def": "Tìm phép biến đổi đưa hoạt động latent của phiên mới về không gian latent tham chiếu mà không cần nhãn, dựa trên giả định cấu trúc thấp chiều ổn định (Degenhart 2020; NoMAD).", "ch": "ch28"}, {"term": "neurorights", "vi": "quyền thần kinh", "def": "Nhóm quyền được đề xuất cho kỷ nguyên công nghệ thần kinh: riêng tư tinh thần, bản sắc cá nhân, tự do ý chí, tiếp cận công bằng; đã được luật hoá một phần ở Chile (2021), Colorado và California (2024).", "ch": "ch28"}, {"term": "spike-band power", "vi": "công suất băng spike", "def": "Công suất tín hiệu trong dải 300–3000 Hz của mỗi kênh, dùng làm đặc trưng thay cho đếm spike rời rạc; bền hơn khi spike đơn neuron không tách được (Neuralink sau sự cố rút sợi).", "ch": "ch28"}, {"term": "double dissociation", "vi": "phân ly kép", "def": "Bằng chứng rằng hai chức năng tách được về cơ chế: tổn thương A hỏng X mà không hỏng Y, tổn thương B hỏng Y mà không hỏng X.", "ch": "ch29"}, {"term": "prosopagnosia", "vi": "mù mặt", "def": "Mất khả năng nhận diện khuôn mặt (thường sau tổn thương vùng fusiform bên phải) trong khi nhận diện vật thể, giọng nói vẫn bình thường.", "ch": "ch29"}, {"term": "anosognosia", "vi": "không nhận biết bệnh", "def": "Bệnh nhân không nhận ra khiếm khuyết của chính mình (ví dụ tin tay liệt vẫn cử động), thường sau tổn thương bán cầu phải; gợi ý não không có bộ phát hiện lỗi cho các module của nó.", "ch": "ch29"}, {"term": "bradykinesia", "vi": "vận động chậm", "def": "Cử động chậm, nhỏ dần và khó khởi động — triệu chứng lõi của Parkinson, do output basal ganglia ức chế thalamus quá mức khi mất dopamine.", "ch": "ch29"}, {"term": "substantia nigra pars compacta", "vi": "chất đen phần đặc", "def": "Cụm ~400–600 nghìn neuron dopamine ở midbrain chiếu lên dorsal striatum (đường nigrostriatal); chết dần trong Parkinson.", "ch": "ch29"}, {"term": "dyskinesia", "vi": "rối loạn vận động", "def": "Cử động thừa, không chủ ý, thường là biến chứng của L-DOPA dùng lâu năm khi dopamine tăng quá mức và không có cấu trúc thời gian.", "ch": "ch29"}, {"term": "chorea", "vi": "múa giật", "def": "Cử động không chủ ý, giật, như múa; triệu chứng đặc trưng của Huntington khi đường indirect của basal ganglia mất trước.", "ch": "ch29"}, {"term": "amyloid plaque", "vi": "mảng amyloid", "def": "Tích tụ ngoài tế bào của peptide amyloid-β (cắt từ APP) trong Alzheimer; đích của các kháng thể lecanemab và donanemab.", "ch": "ch29"}, {"term": "neurofibrillary tangle", "vi": "đám rối sợi thần kinh", "def": "Tích tụ trong neuron của protein tau phosphoryl hoá quá mức; lan theo trình tự Braak từ entorhinal cortex và tương quan với triệu chứng tốt hơn amyloid.", "ch": "ch29"}, {"term": "diaschisis", "vi": "diaschisis", "def": "Suy giảm chức năng ở vùng xa nối với vùng tổn thương, do mất input chứ không do hỏng tại chỗ; hồi phục dần sau đột quỵ.", "ch": "ch29"}, {"term": "Epileptor", "vi": "mô hình Epileptor", "def": "Mô hình động lực học của Jirsa và cộng sự (2014): cơn co giật khởi phát qua saddle-node bifurcation và kết thúc qua homoclinic bifurcation, do một biến chậm đẩy.", "ch": "ch29"}, {"term": "schizophrenia", "vi": "tâm thần phân liệt", "def": "Rối loạn tâm thần với triệu chứng dương tính (ảo giác, hoang tưởng), âm tính (mất động lực) và nhận thức; liên quan dopamine striatum, NMDA hypofunction và precision lệch.", "ch": "ch29"}, {"term": "anhedonia", "vi": "mất khả năng thấy vui", "def": "Triệu chứng lõi của trầm cảm; trong mô hình RL hiện ra như reward sensitivity thấp chứ không phải learning rate thấp.", "ch": "ch29"}, {"term": "learned helplessness", "vi": "học bất lực", "def": "Mô hình động vật của trầm cảm (Seligman & Maier 1967); diễn giải lại năm 2016: thụ động là mặc định trước stress, thứ cần học là kiểm soát (vmPFC ức chế raphe).", "ch": "ch29"}, {"term": "PTSD", "vi": "rối loạn stress sau sang chấn", "def": "Sau sự kiện đe doạ, ký ức xâm nhập và phản ứng sợ với cue kéo dài; hiểu như fear conditioning một lần thử, tổng quát hoá rộng và extinction yếu (vmPFC kém ức chế amygdala).", "ch": "ch29"}, {"term": "computational psychiatry", "vi": "tâm thần học tính toán", "def": "Ngành dùng mô hình RL/Bayes/DDM fit vào hành vi từng người để ước lượng tham số cơ chế (learning rate, precision, reward sensitivity...) thay cho nhãn chẩn đoán.", "ch": "ch29"}, {"term": "ADHD", "vi": "rối loạn tăng động giảm chú ý", "def": "Rối loạn phát triển thần kinh với giảm chú ý, tăng động, xung động; thuốc tăng catecholamine ở PFC; mô hình RL nhấn chiết khấu thời gian dốc và eligibility trace ngắn.", "ch": "ch29"}, {"term": "autism", "vi": "tự kỷ", "def": "Phổ khác biệt phát triển thần kinh về giao tiếp xã hội và xử lý cảm giác; giả thuyết E/I tăng và precision giác quan cao/ước lượng volatility cao đang được kiểm tra.", "ch": "ch29"}, {"term": "reward sensitivity", "vi": "độ nhạy phần thưởng", "def": "Hệ số nhân lên phần thưởng trong sai số dự đoán (δ = ρr − V); thấp trong anhedonia.", "ch": "ch29"}, {"term": "volatility", "vi": "độ biến động", "def": "Tốc độ thay đổi của thống kê môi trường; người học tối ưu tăng learning rate khi volatility cao; lo âu và tự kỷ liên quan tới ước lượng volatility lệch.", "ch": "ch29"}, {"term": "parameter recovery", "vi": "khôi phục tham số", "def": "Kiểm tra bắt buộc: mô phỏng dữ liệu từ tham số biết trước rồi fit lại; nếu không khôi phục được thì ước lượng trên dữ liệu thật không đáng tin.", "ch": "ch29"}, {"term": "test-retest reliability", "vi": "độ tin cậy đo lặp", "def": "Tương quan giữa hai lần đo cùng người; thấp ở nhiều bài nhận thức vì khác biệt cá nhân nhỏ (nghịch lý độ tin cậy, Hedge 2018).", "ch": "ch29"}, {"term": "psychedelic", "vi": "chất gây ảo giác nghiên cứu", "def": "Chất đồng vận 5-HT2A (psilocybin, LSD) làm mọc gai dendrite và mở lại critical period; mô hình REBUS đề xuất chúng giảm precision của prior tầng cao — còn tranh cãi.", "ch": "ch29"}, {"term": "mechanistic interpretability", "vi": "diễn giải cơ chế", "def": "Ngành nghiên cứu tìm cách hiểu mạng nơ-ron nhân tạo ở mức cơ chế: feature, mạch, thuật toán ẩn trong trọng số và activation — về phương pháp gần như neuroscience áp lên ANN.", "ch": "ch30"}, {"term": "polysemanticity", "vi": "tính đa nghĩa của neuron", "def": "Hiện tượng một neuron (một phần tử của vector activation) bật với nhiều khái niệm không liên quan; hệ quả của việc feature là hướng chứ không phải trục neuron.", "ch": "ch30"}, {"term": "feature", "vi": "đặc trưng", "def": "Trong interpretability: một hướng trong không gian activation tương ứng với một thuộc tính có ý nghĩa của input (vd. 'tên riêng', 'lỗi trong mã'); đơn vị phân tích thay cho neuron.", "ch": "ch30"}, {"term": "sparse autoencoder", "vi": "bộ tự mã hoá thưa", "def": "Mạng một tầng ẩn rộng, huấn luyện để tái tạo activation của một tầng model với phạt thưa (L1/TopK); các cột decoder là từ điển hướng feature. Về toán học là sparse coding với encoder amortized.", "ch": "ch30"}, {"term": "feature splitting", "vi": "tách feature", "def": "Khi tăng kích thước từ điển SAE, một feature tách thành nhiều feature con tinh hơn; dấu hiệu từ điển học được không phải cấu trúc 'tự nhiên' duy nhất.", "ch": "ch30"}, {"term": "feature absorption", "vi": "hấp thụ feature", "def": "Lỗi của SAE khi một feature tổng quát (vd. 'bắt đầu bằng S') bị một feature cụ thể hơn (vd. 'short') hấp thụ, nên không bật trong trường hợp lẽ ra phải bật.", "ch": "ch30"}, {"term": "probing", "vi": "thăm dò", "def": "Huấn luyện bộ phân loại (thường tuyến tính) trên activation để đoán một biến; cho biết thông tin có mặt nhưng không chứng minh mô hình dùng nó — tương tự tuning curve.", "ch": "ch30"}, {"term": "activation patching", "vi": "vá activation", "def": "Kỹ thuật nhân quả: chạy input hỏng nhưng chép activation từ lượt sạch vào một vị trí, xem output có khôi phục; tương đương optogenetics trong ANN. Còn gọi causal tracing, interchange intervention.", "ch": "ch30"}, {"term": "ablation", "vi": "loại bỏ", "def": "Vô hiệu hoá một thành phần (neuron, head, feature) bằng cách đặt về 0 hoặc giá trị trung bình rồi đo hành vi; tương đương lesion/ức chế trong não; cho biết thành phần có cần hay không.", "ch": "ch30"}, {"term": "circuit", "vi": "mạch", "def": "Tập con các thành phần của mạng cùng đường nối giữa chúng đủ để thực hiện một hành vi cụ thể (vd. mạch indirect object identification trong GPT-2).", "ch": "ch30"}, {"term": "attribution graph", "vi": "đồ thị quy kết", "def": "Phương pháp (Anthropic 2025) thay neuron bằng feature từ cross-layer transcoder rồi truy vết đường nhân quả từ input tới output cho một prompt; 'sơ đồ mạch' cho một hành vi cụ thể của LLM.", "ch": "ch30"}, {"term": "ground truth", "vi": "sự thật nền", "def": "Cơ chế thật đã biết của một hệ (vd. chip 6502, toy model tự xây) dùng để kiểm định xem một phương pháp phân tích có tái khám phá được nó không.", "ch": "ch30"}, {"term": "RDM", "vi": "ma trận khác biệt biểu diễn", "def": "Representational dissimilarity matrix: ma trận khoảng cách giữa biểu diễn của mọi cặp kích thích trong một hệ; dấu vân tay hình học của biểu diễn.", "ch": "ch30"}, {"term": "controversial stimuli", "vi": "kích thích gây tranh cãi", "def": "Kích thích được tổng hợp để hai mô hình cho dự đoán khác nhau nhất, giúp phân biệt mô hình hiệu quả hơn ảnh tự nhiên (Golan và cs. 2020).", "ch": "ch30"}, {"term": "Platonic representation hypothesis", "vi": "giả thuyết biểu diễn Platonic", "def": "Giả thuyết (Huh và cs. 2024) rằng các mô hình lớn, đa nhiệm, đa phương thức hội tụ về cùng một biểu diễn thống kê của thực tại; giải thích vì sao model dự đoán được não, nhưng chỉ ở tầng biểu diễn.", "ch": "ch30"}, {"term": "foundation model", "vi": "mô hình nền", "def": "Mô hình huấn luyện trên dữ liệu lớn, đa dạng rồi thích nghi rẻ cho nhiều nhiệm vụ; trong neuroscience: core chung học từ nhiều cá thể/buổi ghi, readout riêng cho từng neuron hoặc buổi ghi mới.", "ch": "ch30"}, {"term": "digital twin", "vi": "bản sao số", "def": "Mô hình dự đoán đủ chính xác của một hệ cụ thể (vd. vỏ thị giác của một con chuột) để làm thí nghiệm in silico trước khi kiểm in vivo; MICrONS 2025 là ví dụ đầu tiên ở quy mô lớn.", "ch": "ch30"}, {"term": "core–readout", "vi": "lõi–bộ đọc", "def": "Kiến trúc encoding model: một lõi phi tuyến dùng chung biến kích thích thành đặc trưng, và một bộ đọc tuyến tính nhỏ riêng cho từng neuron (vị trí + trọng số).", "ch": "ch30"}, {"term": "inception loop", "vi": "vòng lặp inception", "def": "Dùng model đã khớp để tối ưu kích thích cực đại hoá đáp ứng dự đoán của một neuron, rồi chiếu kích thích ấy cho neuron thật; kiểm định model bằng thí nghiệm vòng kín.", "ch": "ch30"}, {"term": "connectome-constrained model", "vi": "mô hình ràng buộc bởi connectome", "def": "Mạng có sơ đồ nối lấy từ connectome thật (dây và dấu cố định), chỉ vài tham số tự do (Shiu 2024) hoặc độ mạnh synapse học bằng gradient cho một nhiệm vụ (Lappalainen 2024).", "ch": "ch30"}, {"term": "inverse dynamics model", "vi": "mô hình động lực học ngược", "def": "Mô hình ánh xạ từ trạng thái hiện tại và trạng thái mong muốn sang lệnh vận động cần thiết; giả thuyết về điều khiển vận động ở não, được chuột ảo học bằng imitation.", "ch": "ch30"}, {"term": "embodied Turing test", "vi": "bài kiểm tra Turing có thân thể", "def": "Đề xuất của Zador và cs. (2023): tác nhân nhân tạo điều khiển một thân thể sao cho không phân biệt được với con vật thật của loài đó; bậc thang loài từ giun tới linh trưởng.", "ch": "ch30"}, {"term": "whole-brain emulation", "vi": "mô phỏng toàn bộ não", "def": "Ý tưởng mô phỏng mọi neuron và synapse của một bộ não đủ chi tiết để tái tạo hành vi; hiện bị chặn ở dữ liệu, tham số và tính toán, và ngay cả khi có cũng không tự động cho hiểu biết.", "ch": "ch30"}, {"term": "binding problem", "vi": "bài toán liên kết", "def": "Câu hỏi làm sao các thuộc tính được biểu diễn ở những nhóm neuron khác nhau (màu, hình, vị trí) được gắn thành một đối tượng thống nhất; vẫn mở, giả thuyết đồng bộ gamma suy yếu.", "ch": "ch30"}, {"term": "Moravec's paradox", "vi": "nghịch lý Moravec", "def": "Nhận xét (1988) rằng việc khó với người (cờ, tính toán) dễ với máy còn việc dễ với người (đi, nhìn, cầm nắm) lại khó với máy; nền tảng của embodied Turing test.", "ch": "ch30"}];